"""Canal Delights 单文件发行版（源码明文拼装，音频压缩存储）。"""

import importlib.abc
import importlib.util
import sys
import base64

_MODULE_SOURCES = {'canal_delights.__init__': '"""\n运河四季·Turtle 美食绘卷\nCanal Delights - A Turtle-based interactive art piece\n"""\n\n__version__ = "0.1.0"\n__author__ = "Python Turtle Project"\n', 'canal_delights.__main__': '"""\n程序入口 - python -m canal_delights\n"""\n\nfrom .app import main\n\nif __name__ == "__main__":\n    main()\n', 'canal_delights.app': '"""\n应用主类 - 协调所有模块\n"""\n\nimport math\nimport threading\nfrom time import perf_counter\n\nfrom .state import AppState, StateMachine, Mode\nfrom .core.backend import RenderMode, create_engine\nfrom .core.animation import AnimationClock, SceneTransition\nfrom .core.navigation import (\n    BoatPhysics, CITY_POINTS, ROUTE_SEGMENTS, readable_boat_pose,\n    route_point, route_tangent,\n)\nfrom .core.splash import SplashSystem\nfrom .core.music import ScorePlayer\nfrom .core.sound_effects import EffectPlayer\nfrom .core.renderer import DrawingDataParser\nfrom .config import linear_gradient, rgb, CANVAS_WIDTH, CANVAS_HEIGHT, CANVAS_BG\nfrom .content.catalog import get_all_cities, get_city, get_food\nfrom .content.scenes import FOOD_POSITIONS, get_city_scene\nfrom .content.foods.prototype import get_food_drawing\n\n\nclass App:\n    """应用主类"""\n\n    def __init__(self, render_mode=RenderMode.ACCELERATED):\n        self.engine = create_engine(render_mode, CANVAS_WIDTH, CANVAS_HEIGHT)\n        self.parser = DrawingDataParser(self.engine)\n        self.state = AppState()\n        self.machine = StateMachine(self.state)\n        self.bounds = (0, 0, CANVAS_WIDTH, CANVAS_HEIGHT)\n        self._background_rendered = False\n        self.hovered_item = None\n        self.animations = AnimationClock(\n            self.engine.screen, fps=30 if self.engine.mode_name == \'accelerated\' else 10,\n        )\n        self.boat = BoatPhysics()\n        self.splash = SplashSystem(limit=36 if self.engine.mode_name == \'accelerated\' else 10)\n        self.transition = SceneTransition()\n        self.move_direction = 0\n        self.animation_phase = 0.0\n        self._fps = 0.0\n        self._fps_elapsed = 0.0\n        self._fps_frames = 0\n        self._fps_last_time = None\n        self._splash_elapsed = 0.0\n        self._pressed_nav = None\n        self.book_turn = 0.0\n        self.master_volume = .72\n        self.effects_volume = .82\n        self.music = ScorePlayer(volume=self.master_volume)\n        self.effects = EffectPlayer(volume=self.effects_volume)\n        self.audio_enabled = True\n        self._loading_started = False\n        self._loading_progress = 0.0\n        self._loading_target = 0.0\n        self._loading_complete = False\n        self._loading_finished_transition = False\n        self._loading_label = \'正在加载……\'\n        self._guide_shown = False\n        self._completion_auto_shown = False\n\n    def run(self):\n        """运行应用"""\n        print("=" * 50)\n        print("  运河风物志 Canal Delights")\n        print("=" * 50)\n        print()\n        print("操作说明:")\n        print("  INTRO: Enter/点击 开始旅程")\n        print("  MAP:   按住 ←/→ 驾船, 靠近城市后 Enter 探索")\n        print("  CITY:  ←/→ 选择美食, Enter 查看")\n        print("  DETAIL: Enter 完成品鉴")\n        print("  ATLAS: ←/→ 翻页，B 打开/关闭图鉴")\n        print("  Esc:   返回上一级")\n        print("  H:     帮助")\n        print(f"  渲染:  {self.engine.mode_name}")\n        print()\n\n        # 绑定键盘事件\n        self.engine.screen.onkey(self.on_enter, \'Return\')\n        self.engine.screen.onkey(self.on_enter, \'KP_Enter\')\n        self.engine.screen.onkey(self.on_escape, \'Escape\')\n        self.engine.screen.onkeypress(self.on_left, \'Left\')\n        self.engine.screen.onkeypress(self.on_right, \'Right\')\n        self.engine.screen.onkeyrelease(self.on_direction_release, \'Left\')\n        self.engine.screen.onkeyrelease(self.on_direction_release, \'Right\')\n        self.engine.screen.onkey(self.on_help, \'h\')\n        self.engine.screen.onkey(self.on_help, \'H\')\n        self.engine.screen.onkey(self.on_atlas, \'b\')\n        self.engine.screen.onkey(self.on_atlas, \'B\')\n\n        # 鼠标点击\n        self.engine.screen.onclick(self.on_click)\n        self.engine.on_motion(self.on_motion)\n        self.engine.on_pointer_press(self.on_pointer_press)\n        self.engine.on_pointer_release(self.on_pointer_release)\n\n        self.engine.listen()\n        self.render()\n        self.animations.add(self.on_animation_frame)\n        try:\n            self.engine.mainloop()\n        finally:\n            self.music.stop()\n            self.effects.stop()\n\n    def render(self):\n        """渲染当前帧"""\n        # The paper is static and lives on its own retained layer.  Interaction\n        # only clears content, which is essential for smooth animation later.\n        if not self._background_rendered:\n            self.engine.set_layer(\'background\')\n            self.draw_background()\n            self._background_rendered = True\n\n        self.engine.clear(\'content\')\n        self.engine.set_layer(\'content\')\n\n        # 根据模式绘制内容\n        if self.state.mode == Mode.INTRO:\n            self.draw_intro()\n        elif self.state.mode == Mode.LOADING:\n            self.draw_loading()\n        elif self.state.mode == Mode.MAP:\n            self.draw_map()\n        elif self.state.mode == Mode.CITY:\n            self.draw_city()\n        elif self.state.mode == Mode.FOOD_DETAIL:\n            self.draw_food_detail()\n        elif self.state.mode == Mode.ATLAS:\n            self.draw_atlas()\n        elif self.state.mode == Mode.SETTINGS:\n            self.draw_settings()\n        elif self.state.mode == Mode.FINALE:\n            self.draw_finale()\n\n        if self.state.mode not in (Mode.INTRO, Mode.LOADING):\n            self.draw_back_button()\n\n        # 绘制帮助覆盖层\n        if self.state.help_open:\n            self.draw_help()\n        if self.state.completion_open:\n            self.draw_completion()\n\n        # 绘制状态提示\n        self.draw_status()\n\n        if self.transition.active:\n            self.draw_transition()\n\n        self.engine.update()\n\n    def draw_background(self):\n        """绘制背景"""\n        data = [\n            [\'R\', [0, 0, 1, 1], {\'fill\': CANVAS_BG}],\n            # paper fibres and an understated double border make every scene\n            # read as one scroll instead of a white application window.\n            [\'R\', [0.018, 0.025, 0.964, 0.95], {\'stroke\': rgb(164, 121, 62), \'stroke_width\': 3}],\n            [\'R\', [0.032, 0.041, 0.936, 0.918], {\'stroke\': rgb(218, 187, 126), \'stroke_width\': 1}],\n        ]\n        for x, y in ((.10,.13),(.22,.84),(.39,.09),(.67,.88),(.88,.18),(.92,.72)):\n            data.append([\'E\', [x, y, .035, .006], {\'fill\': rgb(237, 228, 204)}])\n        self.parser.parse(data, self.bounds)\n\n    def _food_medallion(self, cx, cy, city_id, food_id, selected=False):\n        """Small, recognisable food illustration used by the city selection."""\n        rim = rgb(184, 134, 11) if selected else rgb(190, 180, 155)\n        data = [\n            [\'E\', [cx, cy - .065, .115, .028], {\'fill\': rgb(216, 205, 178)}],\n            [\'C\', [cx, cy, .105], {\'fill\': rgb(250, 248, 240), \'stroke\': rim, \'stroke_width\': 2}],\n        ]\n        drawing = get_food_drawing(city_id, food_id)\n        if drawing:\n            data.append([\'GR\', drawing, {\'transform\': {\n                \'scale\': [.52, .52], \'translate\': [cx - .5, cy - .45],\n                \'pivot\': [.5, .45],\n            }}])\n        return data\n\n    @staticmethod\n    def _wrapped_lines(text, width=24):\n        """Wrap Chinese prose without requiring whitespace between words."""\n        return [text[index:index + width] for index in range(0, len(text), width)]\n\n    @staticmethod\n    def _inside(nx, ny, bounds):\n        x, y, width, height = bounds\n        return x <= nx <= x + width and y <= ny <= y + height\n\n    def _preview_layout(self, city_index):\n        """Size to wrapped copy and place beside the associated marker."""\n        marker_x, marker_y = CITY_POINTS[city_index]\n        lines = self._wrapped_lines(get_city(city_index)[\'description\'], 18)\n        width = .38\n        height = .17 + .022 * len(lines)\n        x = max(.045, min(.955 - width, marker_x - width / 2))\n        above_y = marker_y + .075\n        y = above_y if above_y + height <= .95 else marker_y - height - .075\n        button = (x + width - .115, y + .018, .090, .050)\n        return x, y, width, height, button\n\n    @staticmethod\n    def _city_thumbnail(city_id, cx, cy, theme, phase):\n        """Small city silhouettes that avoid scaling full-scene gradients."""\n        sway = .003 * math.sin(phase * 1.5)\n        data = [\n            [\'E\', [cx, cy - .035, .065, .012], {\'fill\': rgb(183, 211, 204)}],\n            [\'B\', [[cx-.065,cy-.025],[cx-.025,cy-.012],[cx+.025,cy-.038],[cx+.065,cy-.020]],\n             {\'stroke\': rgb(112, 169, 175), \'stroke_width\': 2}],\n        ]\n        if city_id == \'beijing\':\n            data += [\n                [\'R\', [cx-.045,cy-.025,.09,.050], {\'fill\': rgb(174, 72, 54)}],\n                [\'G\', [[cx-.060,cy+.025],[cx+.060,cy+.025],[cx+.040,cy+.050],[cx-.040,cy+.050]], {\'fill\': theme}],\n                [\'R\', [cx-.010,cy-.025,.020,.035], {\'fill\': rgb(80, 48, 35)}],\n            ]\n        elif city_id == \'tianjin\':\n            data += [\n                [\'C\', [cx,cy+.010,.047], {\'stroke\': theme, \'stroke_width\': 2}],\n                [\'L\', [[cx-.035,cy-.025],[cx,cy+.010],[cx+.035,cy-.025]], {\'stroke\': theme, \'stroke_width\': 2}],\n                [\'L\', [[cx-.047,cy+.010],[cx+.047,cy+.010]], {\'stroke\': theme, \'stroke_width\': 1}],\n                [\'L\', [[cx,cy-.037],[cx,cy+.057]], {\'stroke\': theme, \'stroke_width\': 1}],\n            ]\n        elif city_id == \'yangzhou\':\n            data += [\n                [\'B\', [[cx-.060,cy-.025],[cx-.032,cy+.045],[cx+.010,cy+.045],[cx+.040,cy-.025]], {\'stroke\': rgb(210, 203, 178), \'stroke_width\': 6}],\n                [\'B\', [[cx-.057,cy-.025],[cx-.030,cy+.037],[cx+.008,cy+.037],[cx+.037,cy-.025]], {\'stroke\': theme, \'stroke_width\': 1}],\n                [\'L\', [[cx+.048,cy-.030],[cx+.048+sway,cy+.055]], {\'stroke\': rgb(77, 112, 67), \'stroke_width\': 2}],\n            ]\n        elif city_id == \'suzhou\':\n            data += [\n                [\'R\', [cx-.055,cy-.025,.11,.055], {\'fill\': rgb(237, 232, 213), \'stroke\': rgb(61, 66, 65), \'stroke_width\': 1}],\n                [\'G\', [[cx-.065,cy+.030],[cx+.065,cy+.030],[cx+.045,cy+.052],[cx-.045,cy+.052]], {\'fill\': rgb(61, 66, 65)}],\n                [\'B\', [[cx-.015,cy-.025],[cx+.010,cy+.025],[cx+.045,cy+.025],[cx+.065,cy-.025]], {\'stroke\': rgb(61, 66, 65), \'stroke_width\': 2}],\n            ]\n        else:\n            data += [\n                [\'B\', [[cx-.065,cy-.005],[cx-.035,cy+.045],[cx,cy+.010],[cx+.040,cy+.050]], {\'stroke\': rgb(105, 145, 97), \'stroke_width\': 10}],\n                [\'R\', [cx+.020,cy-.025,.025,.072], {\'fill\': rgb(190, 158, 99), \'stroke\': theme, \'stroke_width\': 1}],\n                [\'G\', [[cx+.012,cy+.047],[cx+.053,cy+.047],[cx+.043,cy+.060],[cx+.022,cy+.060]], {\'fill\': rgb(91, 67, 45)}],\n            ]\n        return data\n\n    def draw_intro(self):\n        """绘制开场"""\n        bob = math.sin(self.animation_phase * 2.2) * .004\n        data = [\n            [\'B\', [[.08,.29],[.28,.45],[.60,.13],[.91,.31]], {\'stroke\': rgb(102, 155, 167), \'stroke_width\': 28}],\n            [\'B\', [[.08,.29],[.28,.45],[.60,.13],[.91,.31]], {\'stroke\': rgb(188, 222, 221), \'stroke_width\': 3}],\n            [\'G\', [[.17,.31+bob],[.23,.36+bob],[.29,.31+bob]], {\'fill\': rgb(102, 63, 37)}],\n            [\'L\', [[.23,.36+bob],[.23,.43+bob]], {\'stroke\': rgb(82, 57, 38), \'stroke_width\': 2}],\n            [\'G\', [[.23,.42+bob],[.28,.39+bob],[.23,.36+bob]], {\'fill\': rgb(201, 48, 44)}],\n            [\'B\', [[.13,.278-bob],[.19,.265+bob],[.26,.27-bob],[.33,.275]], {\'stroke\': rgb(198, 222, 215), \'stroke_width\': 2}],\n            # 标题\n            [\'T\', [0.5, 0.59, \'运河风物志\'], {\'font_size\': 46, \'font_weight\': \'bold\', \'color\': rgb(139, 69, 19)}],\n            [\'T\', [0.5, 0.515, \'Canal Delights\'], {\'font_size\': 24, \'color\': rgb(164, 121, 62)}],\n            # 副标题\n            [\'T\', [0.5, 0.35, \'一河通南北，五味见四时\'], {\'font_size\': 18, \'color\': rgb(100, 100, 100)}],\n            # 悬浮按钮\n            [\'RR\', [.385, .155, .23, .075, .028], {\n                \'fill\': rgb(201, 48, 44) if self.hovered_item == (\'start\', 0) else rgb(139, 69, 19),\n                \'stroke\': rgb(225, 184, 105), \'stroke_width\': 2,\n            }],\n            [\'T\', [0.5, 0.177, \'启 程\'], {\'font_size\': 15, \'font_weight\': \'bold\', \'color\': rgb(255, 248, 229)}],\n            [\'T\', [0.5, 0.12, \'Enter 或点击\'], {\'font_size\': 10, \'color\': rgb(150, 138, 116)}],\n        ]\n        self.parser.parse(data, self.bounds)\n\n    def draw_loading(self):\n        """One-time animated preheating screen shown before the first map."""\n        wave_x = .08 * math.sin(self.animation_phase * 2.2)\n        progress = max(0., min(1., self._loading_progress))\n        data = [\n            [\'T\', [.50, .68, \'正在展开运河长卷\'], {\'font_size\': 27, \'font_weight\': \'bold\', \'color\': rgb(73, 60, 46)}],\n            [\'T\', [.50, .625, \'资源加载中，请耐心等待\'], {\'font_size\': 11, \'color\': rgb(139, 109, 72)}],\n            [\'B\', [[.17,.46],[.27,.49+wave_x*.10],[.39,.45-wave_x*.08],[.50,.46]], {\n                \'stroke\': rgb(89, 154, 161), \'stroke_width\': 5,\n            }],\n            [\'B\', [[.50,.46],[.61,.49+wave_x*.06],[.73,.45-wave_x*.08],[.83,.46]], {\n                \'stroke\': rgb(89, 154, 161), \'stroke_width\': 5,\n            }],\n            [\'RR\', [.25, .34, .50, .028, .014], {\'fill\': rgb(214, 202, 174), \'stroke\': rgb(174, 137, 82), \'stroke_width\': 1}],\n            [\'RR\', [.25, .34, .50*progress, .028, .014], {\'fill\': rgb(70, 145, 132)}],\n            [\'T\', [.50, .385, self._loading_label], {\'font_size\': 8, \'color\': rgb(164, 143, 113)}],\n            [\'T\', [.50, .285, f\'{round(progress*100)}%\'], {\'font_size\': 17, \'font_weight\': \'bold\', \'color\': rgb(89, 112, 84)}],\n        ]\n        self.parser.parse(data, self.bounds)\n\n    def _start_first_loading(self):\n        self.machine.start_loading()\n        if self._loading_started:\n            return\n        self._loading_started = True\n        threading.Thread(target=self._prepare_first_journey, name=\'canal-loader\', daemon=True).start()\n\n    def _finish_first_loading(self):\n        self.machine.finish_loading()\n        if not self._guide_shown:\n            self.state.help_open = True\n            self._guide_shown = True\n\n    def _open_guide_from_settings(self):\n        self.machine.back()\n        self.state.help_open = True\n\n    def _enter_journey(self):\n        """Route later visits directly to the map after the one-time preload."""\n        if self._loading_complete:\n            self.machine.start_journey()\n        else:\n            self._start_first_loading()\n\n    def _prepare_first_journey(self):\n        try:\n            self._loading_label = \'正在加载交互音效……\'\n            self._loading_target = .16\n            self.effects.prepare()\n            self._loading_label = \'正在加载清新风背景音乐……\'\n            self._loading_target = .38\n            self.music.prepare()\n            self._loading_label = \'正在完成首次初始化……\'\n        except Exception:\n            # Audio availability must never strand the user on the loader.\n            self.audio_enabled = False\n            self.music.set_enabled(False)\n            self.effects.set_enabled(False)\n            self._loading_label = \'音频初始化不可用，正在以静音模式进入……\'\n        finally:\n            self._loading_target = 1.0\n            self._loading_complete = True\n\n    def draw_map(self):\n        """绘制地图"""\n        cities = [\'北京\', \'天津\', \'扬州\', \'苏州\', \'杭州\']\n        colors = [rgb(201, 48, 44), rgb(139, 69, 19), rgb(46, 139, 87),\n                  rgb(65, 105, 225), rgb(107, 142, 35)]\n\n        # 标题\n        route_commands = [[\'M\', *CITY_POINTS[0]]]\n        for _, control_1, control_2, end in ROUTE_SEGMENTS:\n            route_commands.append([\'C\', *control_1, *control_2, *end])\n\n        nearby_city = self.boat.nearby_city()\n        data = [\n            [\'R\', [.034, .043, .932, .914], {\'gradient\': linear_gradient([\n                [rgb(239, 230, 205), 0.0], [rgb(250, 244, 225), .48], [rgb(226, 218, 192), 1.0],\n            ], angle=25, steps=12 if self.engine.mode_name == \'accelerated\' else 6), \'z\': -20}],\n            [\'PATH\', route_commands, {\'stroke\': rgb(94, 155, 170), \'stroke_width\': 40}],\n            [\'PATH\', route_commands, {\'stroke\': rgb(181, 220, 220), \'stroke_width\': 27}],\n            [\'PATH\', route_commands, {\'stroke\': rgb(226, 242, 235), \'stroke_width\': 3}],\n            [\'T\', [0.5, 0.9, \'京杭大运河\'], {\'font_size\': 28, \'color\': rgb(50, 50, 50)}],\n            [\'T\', [0.5, 0.845, \'驾一叶轻舟，循水寻味\'], {\'font_size\': 13, \'color\': rgb(122, 101, 75)}],\n        ]\n\n        # Low-contrast brocade and water-line motifs give the map depth without\n        # competing with the route or behaving like free-floating particles.\n        pattern = rgb(218, 204, 170)\n        for index in range(6):\n            y = .18 + index * .115\n            offset = .012 * math.sin(self.animation_phase * .55 + index)\n            data.append([\'B\', [[.07, y], [.28, y + .045 + offset], [.68, y - .035], [.94, y + .010]],\n                         {\'stroke\': pattern, \'stroke_width\': 1, \'z\': -10}])\n        for x, y in ((.10,.76),(.88,.76),(.13,.15),(.88,.17)):\n            data.extend([\n                [\'A\', [x, y, .040, 15, 165], {\'stroke\': rgb(207, 186, 143), \'stroke_width\': 2, \'z\': -10}],\n                [\'A\', [x + .050, y, .032, 20, 160], {\'stroke\': rgb(207, 186, 143), \'stroke_width\': 2, \'z\': -10}],\n            ])\n\n        # 城市节点\n        for i, (city, color) in enumerate(zip(cities, colors)):\n            x, y = CITY_POINTS[i]\n\n            # Unified inverted-drop marker. Proximity, visited and stamped\n            # states change its color without changing its visual language.\n            active = i == nearby_city\n            pulse = .004 * (1 + math.sin(self.animation_phase * 4)) if active else 0\n            marker_fill = color if active else rgb(190, 190, 181)\n            if i in self.state.visited_cities and not active:\n                marker_fill = tuple(int((channel + 230) / 2) for channel in color)\n            data.append([\'C\', [x, y + .018, .050 + pulse], {\n                \'fill\': rgb(247, 241, 220), \'stroke\': color if active else rgb(158, 151, 136), \'stroke_width\': 2,\n            }])\n            data.append([\'G\', [[x - .034, y + .010], [x + .034, y + .010], [x, y - .050]], {\'fill\': marker_fill}])\n            data.append([\'C\', [x, y + .020, .030], {\'fill\': marker_fill}])\n            data.append([\'C\', [x, y + .020, .010], {\'fill\': rgb(247, 241, 220)}])\n\n            # 城市名\n            data.append([\'T\', [x, y - 0.08, city], {\'font_size\': 14, \'color\': rgb(50, 50, 50)}])\n\n            # 印章标记\n            if i in self.state.stamped_cities:\n                data.append([\'T\', [x, y + 0.02, \'✓\'], {\'font_size\': 20, \'color\': rgb(255, 0, 0)}])\n\n        boat_x, boat_y = route_point(self.boat.position)\n        tangent_x, tangent_y = route_tangent(self.boat.position)\n        direction = 1 if self.boat.velocity >= 0 else -1\n        boat_angle, boat_flipped = readable_boat_pose(\n            (tangent_x, tangent_y), direction, (CANVAS_WIDTH, CANVAS_HEIGHT),\n        )\n        bob = math.sin(self.animation_phase * 5) * .003\n        wake_strength = min(1.0, abs(self.boat.velocity) / .12)\n        tail_x = boat_x - tangent_x * direction * (.035 + .025 * wake_strength)\n        tail_y = boat_y - tangent_y * direction * (.035 + .025 * wake_strength)\n        normal_x, normal_y = -tangent_y, tangent_x\n        if wake_strength > .05:\n            data.extend([\n                [\'B\', [[boat_x, boat_y - .016],\n                       [tail_x + normal_x*.020, tail_y + normal_y*.020],\n                       [tail_x + normal_x*.035, tail_y + normal_y*.035],\n                       [tail_x - tangent_x*direction*.035, tail_y - tangent_y*direction*.035]],\n                 {\'stroke\': rgb(226, 241, 233), \'stroke_width\': 2}],\n                [\'B\', [[boat_x, boat_y - .016],\n                       [tail_x - normal_x*.020, tail_y - normal_y*.020],\n                       [tail_x - normal_x*.035, tail_y - normal_y*.035],\n                       [tail_x - tangent_x*direction*.035, tail_y - tangent_y*direction*.035]],\n                 {\'stroke\': rgb(134, 184, 187), \'stroke_width\': 2}],\n            ])\n        data.extend(self.splash.drawing_data())\n        data.append([\'GR\', [\n            [\'E\', [boat_x, boat_y - .018 + bob, .050, .012], {\'fill\': rgb(111, 170, 181)}],\n            [\'G\', [[boat_x - .047, boat_y + bob], [boat_x + .047, boat_y + bob],\n                   [boat_x + .030, boat_y - .025 + bob], [boat_x - .030, boat_y - .025 + bob]],\n             {\'fill\': rgb(115, 65, 38), \'stroke\': rgb(72, 45, 31), \'stroke_width\': 1}],\n            [\'L\', [[boat_x, boat_y + bob], [boat_x, boat_y + .060 + bob]],\n             {\'stroke\': rgb(75, 49, 33), \'stroke_width\': 2}],\n            [\'G\', [[boat_x + .002, boat_y + .055 + bob], [boat_x + .002, boat_y + .012 + bob],\n                   [boat_x + .040, boat_y + .025 + bob]], {\'fill\': rgb(201, 48, 44)}],\n        ], {\'transform\': {\n            \'scale\': [-1, 1] if boat_flipped else [1, 1],\n            \'rotate\': boat_angle, \'pivot\': [boat_x, boat_y],\n        }}])\n\n        # Side controls behave like a compact physical throttle.\n        left_hover = self.hovered_item == (\'nav\', -1)\n        right_hover = self.hovered_item == (\'nav\', 1)\n        left_pressed = self._pressed_nav == -1\n        right_pressed = self._pressed_nav == 1\n        data.extend([\n            [\'RR\', [.055, .39, .075, .10, .025], {\'fill\': rgb(105, 57, 35) if left_pressed else (rgb(139, 69, 19) if left_hover else rgb(224, 207, 170)), \'stroke\': rgb(164, 121, 62), \'stroke_width\': 3 if left_pressed else 2}],\n            [\'T\', [.092, .418, \'‹\'], {\'font_size\': 26, \'color\': rgb(255, 248, 229) if left_hover else rgb(91, 63, 39)}],\n            [\'RR\', [.87, .39, .075, .10, .025], {\'fill\': rgb(105, 57, 35) if right_pressed else (rgb(139, 69, 19) if right_hover else rgb(224, 207, 170)), \'stroke\': rgb(164, 121, 62), \'stroke_width\': 3 if right_pressed else 2}],\n            [\'T\', [.907, .418, \'›\'], {\'font_size\': 26, \'color\': rgb(255, 248, 229) if right_hover else rgb(91, 63, 39)}],\n            [\'RR\', [.835, .865, .110, .060, .018], {\n                \'fill\': rgb(139, 69, 19) if self.hovered_item == (\'settings\', 0) else rgb(232, 218, 187),\n                \'stroke\': rgb(164, 121, 62), \'stroke_width\': 1,\n            }],\n            [\'T\', [.890, .883, \'设置\'], {\'font_size\': 11, \'font_weight\': \'bold\',\n                                        \'color\': rgb(255, 248, 229) if self.hovered_item == (\'settings\', 0) else rgb(91, 63, 39)}],\n        ])\n\n        # A compact open-book silhouette: leather rim, layered pages, page\n        # rules and a cinnabar bookmark.  It floats instead of sitting inside\n        # another generic rectangular button.\n        atlas_hover = self.hovered_item == (\'atlas\', 0)\n        lift = (.008 if atlas_hover else 0) + .002 * math.sin(self.animation_phase * 1.6)\n        rim = rgb(221, 174, 83) if atlas_hover else rgb(166, 104, 55)\n        data.extend([\n            [\'E\', [.125, .055 + lift, .088, .014], {\'fill\': rgb(193, 175, 139)}],\n            [\'G\', [[.043,.072+lift],[.117,.061+lift],[.125,.071+lift],\n                   [.133,.061+lift],[.207,.072+lift],[.197,.169+lift],\n                   [.139,.159+lift],[.125,.148+lift],[.111,.159+lift],[.053,.169+lift]], {\n                \'fill\': rgb(119, 61, 43), \'stroke\': rim, \'stroke_width\': 3 if atlas_hover else 2,\n            }],\n            [\'G\', [[.054,.083+lift],[.119,.073+lift],[.119,.151+lift],\n                   [.110,.158+lift],[.063,.162+lift]], {\n                \'fill\': rgb(251, 241, 210), \'stroke\': rgb(213, 180, 119), \'stroke_width\': 1,\n            }],\n            [\'G\', [[.131,.073+lift],[.196,.083+lift],[.187,.162+lift],\n                   [.140,.158+lift],[.131,.151+lift]], {\n                \'fill\': rgb(247, 233, 195), \'stroke\': rgb(213, 180, 119), \'stroke_width\': 1,\n            }],\n            [\'L\', [[.125,.071+lift],[.125,.150+lift]], {\'stroke\': rgb(132, 84, 51), \'stroke_width\': 2}],\n            [\'G\', [[.166,.156+lift],[.180,.158+lift],[.177,.105+lift],\n                   [.171,.112+lift],[.165,.104+lift]], {\'fill\': rgb(188, 50, 43)}],\n            [\'L\', [[.068,.137+lift],[.108,.132+lift]], {\'stroke\': rgb(210, 190, 151), \'stroke_width\': 1}],\n            [\'L\', [[.066,.120+lift],[.108,.116+lift]], {\'stroke\': rgb(210, 190, 151), \'stroke_width\': 1}],\n            [\'L\', [[.142,.132+lift],[.185,.137+lift]], {\'stroke\': rgb(207, 184, 143), \'stroke_width\': 1}],\n            [\'L\', [[.142,.116+lift],[.184,.120+lift]], {\'stroke\': rgb(207, 184, 143), \'stroke_width\': 1}],\n            [\'RR\', [.094, .078 + lift, .062, .030, .010], {\n                \'fill\': rgb(218, 177, 94) if atlas_hover else rgb(229, 203, 145),\n                \'stroke\': rgb(139, 69, 19), \'stroke_width\': 1,\n            }],\n            [\'T\', [.125, .085 + lift, \'图鉴\'], {\'font_size\': 9, \'font_weight\': \'bold\',\n                                              \'color\': rgb(105, 57, 35)}],\n        ])\n\n        if nearby_city is not None:\n            city_data = get_city(nearby_city)\n            explore_hover = self.hovered_item == (\'explore\', nearby_city)\n            card_x, card_y, card_w, card_h, explore_bounds = self._preview_layout(nearby_city)\n            marker_x, marker_y = CITY_POINTS[nearby_city]\n            card_above = card_y > marker_y\n            stem_y = card_y if card_above else card_y + card_h\n            data.extend([\n                [\'G\', [[marker_x - .018, stem_y], [marker_x + .018, stem_y],\n                       [marker_x, marker_y + (.052 if card_above else -.052)]],\n                 {\'fill\': rgb(250, 245, 225), \'stroke\': city_data[\'theme\'], \'stroke_width\': 1, \'z\': 99}],\n                [\'RR\', [card_x, card_y, card_w, card_h, .022], {\'fill\': rgb(250, 245, 225), \'stroke\': city_data[\'theme\'], \'stroke_width\': 2, \'z\': 100}],\n            ])\n            # A lightweight animated silhouette avoids scaling full-scene\n            # gradients, which would be expensive in pure Turtle mode.\n            thumb_x, thumb_y = card_x + .075, card_y + card_h / 2\n            data.append([\'GR\', self._city_thumbnail(\n                city_data[\'id\'], thumb_x, thumb_y, city_data[\'theme\'], self.animation_phase,\n            ), {\'z\': 101}])\n            copy_x = card_x + .145\n            top = card_y + card_h\n            data.extend([\n                [\'T\', [copy_x, top - .045, city_data[\'name\']], {\'font_size\': 17, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(55, 48, 39), \'z\': 102}],\n                [\'T\', [copy_x, top - .078, city_data[\'cuisine\']], {\'font_size\': 9, \'align\': \'left\', \'color\': city_data[\'theme\'], \'z\': 102}],\n                [\'RR\', [*explore_bounds, .014], {\'fill\': city_data[\'theme\'] if explore_hover else rgb(219, 190, 130), \'stroke\': city_data[\'theme\'], \'stroke_width\': 1, \'z\': 102}],\n                [\'T\', [explore_bounds[0] + explore_bounds[2] / 2, explore_bounds[1] + .013, \'探索\'], {\'font_size\': 10, \'font_weight\': \'bold\', \'color\': rgb(255, 250, 235) if explore_hover else rgb(75, 54, 35), \'z\': 103}],\n            ])\n            for line_index, line in enumerate(self._wrapped_lines(city_data[\'description\'], 18)):\n                data.append([\'T\', [copy_x, top - .108 - line_index * .022, line], {\n                    \'font_size\': 8, \'align\': \'left\', \'color\': rgb(120, 105, 83), \'z\': 102,\n                }])\n\n        self.parser.parse(data, self.bounds)\n\n    def draw_city(self):\n        """绘制城市场景"""\n        city_data = get_city(self.state.current_city)\n        city = city_data[\'name\']\n\n        theme = city_data[\'theme\']\n        data = get_city_scene(\n            city_data[\'id\'], theme, self.animation_phase,\n            gradient_steps=10 if self.engine.mode_name == \'accelerated\' else 5,\n        )\n        data.append([\'T\', [0.5, 0.86, f\'{city} · 城市食景\'], {\n            \'font_size\': 30, \'font_weight\': \'bold\', \'color\': rgb(50, 50, 50),\n        }])\n        data.append([\'T\', [0.5, 0.815, f"{city_data[\'cuisine\']} · 寻访四道时味"], {\n            \'font_size\': 11, \'color\': rgb(130, 112, 85),\n        }])\n\n        # 四道美食\n        for i, food_data in enumerate(city_data[\'foods\']):\n            x, y = FOOD_POSITIONS[city_data[\'id\']][i]\n\n            hovered = self.hovered_item == (\'food\', i)\n            highlighted = i == self.state.current_food or hovered\n            medallion = self._food_medallion(\n                x, y, city_data[\'id\'], food_data[\'id\'], highlighted,\n            )\n            scale = .84 if hovered else .74\n            data.append([\'GR\', medallion, {\'transform\': {\n                \'scale\': [scale, scale], \'pivot\': [x, y],\n            }}])\n\n            # 美食名\n            data.append([\'T\', [x, y - 0.105, food_data[\'name\']], {\'font_size\': 12, \'color\': rgb(50, 50, 50)}])\n            if f\'{self.state.current_city}_{i}\' in self.state.discovered_foods:\n                data.append([\'C\', [x + .075, y + .070, .023], {\'fill\': rgb(176, 45, 39), \'stroke\': rgb(246, 220, 160), \'stroke_width\': 1}])\n                data.append([\'T\', [x + .075, y + .061, \'✓\'], {\'font_size\': 10, \'color\': rgb(255, 246, 224)}])\n\n        # 提示\n        data.append([\'T\', [0.5, 0.12, \'悬浮预览 · 点击探索 · ←/→ 切换\'],\n                    {\'font_size\': 12, \'color\': rgb(150, 150, 150)}])\n\n        self.parser.parse(data, self.bounds)\n\n    def draw_food_detail(self):\n        """绘制美食详情"""\n        city_data = get_city(self.state.current_city)\n        food_data = get_food(self.state.current_city, self.state.current_food)\n        city_name = city_data[\'name\']\n\n        theme = city_data[\'theme\']\n        detail_bob = .004 * math.sin(self.animation_phase * 1.7)\n        data = [\n            # Upper area: illustration 3/10, introduction 7/10.\n            [\'RR\', [.065, .53, .27, .31, .025], {\'fill\': rgb(250, 246, 230), \'stroke\': theme, \'stroke_width\': 2}],\n            [\'RR\', [.365, .53, .57, .31, .025], {\'fill\': rgb(247, 240, 217), \'stroke\': rgb(215, 192, 147), \'stroke_width\': 1}],\n            [\'T\', [.405, .775, f\'{city_name} · {food_data["name"]}\'], {\'font_size\': 25, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(52, 44, 34)}],\n            [\'T\', [.405, .727, city_data[\'cuisine\']], {\'font_size\': 11, \'align\': \'left\', \'color\': theme}],\n\n            # Lower area: story occupies roughly 60% of the content height.\n            [\'RR\', [.065, .135, .87, .35, .025], {\'fill\': rgb(242, 232, 203), \'stroke\': rgb(204, 173, 116), \'stroke_width\': 1}],\n            [\'T\', [.105, .420, \'食味小记\'], {\'font_size\': 19, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': theme}],\n            [\'RR\', [.745, .175, .15, .065, .018], {\'fill\': theme if self.hovered_item == (\'taste\', 0) else rgb(222, 196, 142), \'stroke\': theme, \'stroke_width\': 1}],\n            [\'T\', [.82, .194, \'完成品鉴\'], {\'font_size\': 12, \'font_weight\': \'bold\', \'color\': rgb(255, 249, 234) if self.hovered_item == (\'taste\', 0) else rgb(75, 55, 36)}],\n        ]\n\n        for index, line in enumerate(self._wrapped_lines(food_data[\'intro\'], 25)[:3]):\n            data.append([\'T\', [.405, .674 - index * .043, line], {\n                \'font_size\': 12, \'align\': \'left\', \'color\': rgb(91, 76, 56),\n            }])\n        for index, line in enumerate(self._wrapped_lines(food_data[\'story\'], 38)[:4]):\n            data.append([\'T\', [.105, .360 - index * .048, line], {\n                \'font_size\': 12, \'align\': \'left\', \'color\': rgb(79, 68, 53),\n            }])\n\n        # 添加食物绘图数据\n        food_drawing = get_food_drawing(city_data[\'id\'], food_data[\'id\'])\n        data.append([\'GR\', food_drawing, {\n            \'transform\': {\'scale\': [.60, .60], \'translate\': [-.30, .255 + detail_bob], \'pivot\': [.5, .45]},\n        }])\n\n        self.parser.parse(data, self.bounds)\n\n    def draw_atlas(self):\n        """绘制带翻页反馈的动漫风格美食图鉴。"""\n        cities = get_all_cities()\n        page = self.state.atlas_page\n        lift = .004 * math.sin(self.animation_phase * 1.4)\n        data = [\n            [\'E\', [.50, .135 + lift, .39, .035], {\'fill\': rgb(188, 169, 132)}],\n            [\'RR\', [.105, .17 + lift, .79, .66, .035], {\n                \'fill\': rgb(112, 56, 42), \'stroke\': rgb(190, 139, 67), \'stroke_width\': 3,\n            }],\n            [\'G\', [[.13,.20+lift],[.495,.185+lift],[.495,.79+lift],[.14,.805+lift]], {\n                \'fill\': rgb(249, 240, 211), \'stroke\': rgb(208, 181, 124), \'stroke_width\': 2,\n            }],\n            [\'G\', [[.505,.185+lift],[.87,.20+lift],[.86,.805+lift],[.505,.79+lift]], {\n                \'fill\': rgb(247, 235, 202), \'stroke\': rgb(208, 181, 124), \'stroke_width\': 2,\n            }],\n            [\'B\', [[.50,.19+lift],[.485,.39+lift],[.515,.60+lift],[.50,.795+lift]], {\n                \'stroke\': rgb(148, 104, 62), \'stroke_width\': 3,\n            }],\n            [\'T\', [.50, .865, \'京杭大运河 · 美食图鉴\'], {\n                \'font_size\': 27, \'font_weight\': \'bold\', \'color\': rgb(85, 55, 39),\n            }],\n        ]\n\n        if page == 0:\n            discovered = len(self.state.discovered_foods)\n            data.extend([\n                [\'T\', [.19, .735 + lift, \'行旅总览\'], {\'font_size\': 22, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(139, 69, 19)}],\n                [\'T\', [.19, .685 + lift, f\'已收录 {discovered} / 20 道运河风味\'], {\'font_size\': 12, \'align\': \'left\', \'color\': rgb(110, 91, 68)}],\n                [\'T\', [.56, .735 + lift, \'五城印记\'], {\'font_size\': 22, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(139, 69, 19)}],\n            ])\n            for index, city in enumerate(cities):\n                column = 0 if index < 3 else 1\n                row = index if index < 3 else index - 3\n                x = .19 if column == 0 else .56\n                y = .60 - row * .145 + lift\n                count = sum(f\'{index}_{food}\' in self.state.discovered_foods for food in range(4))\n                data.extend([\n                    [\'C\', [x + .025, y + .018, .025], {\'fill\': city[\'theme\'] if count == 4 else rgb(205, 195, 172)}],\n                    [\'T\', [x + .065, y + .013, city[\'name\']], {\'font_size\': 14, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(69, 57, 45)}],\n                    [\'T\', [x + .21, y + .013, f\'{count}/4\'], {\'font_size\': 11, \'align\': \'right\', \'color\': city[\'theme\']}],\n                    [\'R\', [x + .065, y - .018, .145, .010], {\'fill\': rgb(222, 211, 185)}],\n                    [\'R\', [x + .065, y - .018, .145 * count / 4, .010], {\'fill\': city[\'theme\']}],\n                ])\n            if self.state.is_all_stamped():\n                # Trophy sits in the open space beneath Hangzhou on the\n                # right-hand page and acts as a replay button for the finale.\n                tx, ty = .80, .305 + lift\n                data.extend([\n                    [\'C\', [tx, ty + .026, .030], {\'fill\': rgb(214, 169, 62), \'stroke\': rgb(139, 91, 28), \'stroke_width\': 1}],\n                    [\'R\', [tx - .010, ty - .005, .020, .025], {\'fill\': rgb(214, 169, 62), \'stroke\': rgb(139, 91, 28), \'stroke_width\': 1}],\n                    [\'R\', [tx - .035, ty + .015, .020, .028], {\'fill\': rgb(214, 169, 62), \'stroke\': rgb(139, 91, 28), \'stroke_width\': 1}],\n                    [\'R\', [tx + .015, ty + .015, .020, .028], {\'fill\': rgb(214, 169, 62), \'stroke\': rgb(139, 91, 28), \'stroke_width\': 1}],\n                    [\'R\', [tx - .030, ty - .020, .060, .008], {\'fill\': rgb(139, 91, 28)}],\n                    [\'T\', [tx, ty - .050, \'通关纪念\'], {\'font_size\': 8, \'font_weight\': \'bold\', \'color\': rgb(139, 91, 28)}],\n                ])\n        else:\n            city_index = page - 1\n            city = cities[city_index]\n            data.extend([\n                [\'T\', [.18, .735 + lift, city[\'name\']], {\'font_size\': 28, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': city[\'theme\']}],\n                [\'T\', [.18, .690 + lift, city[\'cuisine\']], {\'font_size\': 11, \'align\': \'left\', \'color\': rgb(99, 81, 61)}],\n            ])\n            for index, line in enumerate(self._wrapped_lines(city[\'description\'], 23)[:2]):\n                data.append([\'T\', [.55, .735 - index * .035 + lift, line], {\n                    \'font_size\': 10, \'align\': \'left\', \'color\': rgb(110, 91, 68),\n                }])\n            positions = ((.27,.54),(.43,.37),(.62,.54),(.78,.37))\n            for food_index, (food, (x, y)) in enumerate(zip(city[\'foods\'], positions)):\n                found = f\'{city_index}_{food_index}\' in self.state.discovered_foods\n                medallion = self._food_medallion(\n                    x, y + lift, city[\'id\'], food[\'id\'], found,\n                )\n                data.append([\'GR\', medallion, {\'transform\': {\n                    \'scale\': [.52, .52], \'pivot\': [x, y + lift],\n                }}])\n                data.append([\'T\', [x, y - .072 + lift, food[\'name\'] if found else \'尚未品鉴\'], {\n                    \'font_size\': 11, \'font_weight\': \'bold\' if found else \'normal\',\n                    \'color\': city[\'theme\'] if found else rgb(156, 146, 124),\n                }])\n                data.append([\'T\', [x, y - .102 + lift, \'已收录 ✓\' if found else \'沿运河继续寻味\'], {\n                    \'font_size\': 8, \'color\': rgb(113, 101, 79),\n                }])\n\n        prev_disabled = page == 0\n        next_disabled = page == len(cities)\n        prev_hover = self.hovered_item == (\'atlas_nav\', -1) and not prev_disabled\n        next_hover = self.hovered_item == (\'atlas_nav\', 1) and not next_disabled\n        data.extend([\n            [\'RR\', [.20, .105, .12, .055, .018], {\'fill\': rgb(139, 69, 19) if prev_hover else (rgb(224, 216, 196) if prev_disabled else rgb(218, 190, 137)), \'stroke\': rgb(167, 120, 62), \'stroke_width\': 1}],\n            [\'T\', [.26, .121, \'‹ 上一页\'], {\'font_size\': 10, \'color\': rgb(255, 248, 229) if prev_hover else rgb(105, 80, 56)}],\n            [\'T\', [.50, .123, f\'{page + 1} / {len(cities) + 1}\'], {\'font_size\': 10, \'color\': rgb(136, 117, 88)}],\n            [\'RR\', [.68, .105, .12, .055, .018], {\'fill\': rgb(139, 69, 19) if next_hover else (rgb(224, 216, 196) if next_disabled else rgb(218, 190, 137)), \'stroke\': rgb(167, 120, 62), \'stroke_width\': 1}],\n            [\'T\', [.74, .121, \'下一页 ›\'], {\'font_size\': 10, \'color\': rgb(255, 248, 229) if next_hover else rgb(105, 80, 56)}],\n        ])\n\n        if abs(self.book_turn) > .025:\n            amount = min(1.0, abs(self.book_turn))\n            edge = .50 + (.34 * amount if self.book_turn > 0 else -.34 * amount)\n            data.append([\'G\', [[.50,.205+lift],[edge,.23+lift],[edge,.77+lift],[.50,.79+lift]], {\n                \'fill\': rgb(238, 224, 190), \'stroke\': rgb(188, 150, 91), \'stroke_width\': 2, \'z\': 200,\n            }])\n        self.parser.parse(data, self.bounds)\n\n    def draw_settings(self):\n        """绘制设置页；主音量连接代码演奏，音效接口保持预留。"""\n        pulse = .006 * math.sin(self.animation_phase * 1.8)\n        accelerated = self.engine.mode_name == \'accelerated\'\n        acceleration_available = self.engine.supports_acceleration\n        toggle_hover = self.hovered_item == (\'acceleration\', 0) and acceleration_available\n        audio_hover = self.hovered_item == (\'audio_enabled\', 0)\n        data = [\n            [\'T\', [.50, .865, \'设置\'], {\'font_size\': 30, \'font_weight\': \'bold\', \'color\': rgb(67, 54, 42)}],\n            [\'T\', [.50, .820, \'画面与声音\'], {\'font_size\': 11, \'color\': rgb(137, 113, 79)}],\n            [\'E\', [.50, .185, .315, .025], {\'fill\': rgb(201, 185, 151)}],\n            [\'RR\', [.19, .20 + pulse, .62, .56, .032], {\n                \'fill\': rgb(247, 238, 211), \'stroke\': rgb(173, 126, 67), \'stroke_width\': 2,\n            }],\n            [\'T\', [.255, .675 + pulse, \'渲染性能\'], {\'font_size\': 17, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(73, 60, 46)}],\n            [\'T\', [.255, .632 + pulse, \'加速模式\'], {\'font_size\': 14, \'align\': \'left\', \'color\': rgb(82, 68, 52)}],\n            [\'T\', [.255, .598 + pulse, \'关闭后使用纯 Turtle 绘制，帧率会相应降低\'], {\'font_size\': 9, \'align\': \'left\', \'color\': rgb(135, 117, 91)}],\n            [\'RR\', [.655, .617 + pulse, .095, .052, .026], {\n                \'fill\': rgb(54, 142, 104) if accelerated else rgb(190, 183, 165),\n                \'stroke\': rgb(35, 112, 81) if toggle_hover else rgb(151, 135, 106),\n                \'stroke_width\': 3 if toggle_hover else 1,\n            }],\n            [\'C\', [.722 if accelerated else .682, .643 + pulse, .020], {\n                \'fill\': rgb(255, 250, 233) if acceleration_available else rgb(216, 208, 189),\n            }],\n            [\'L\', [[.24,.555+pulse],[.76,.555+pulse]], {\'stroke\': rgb(213, 193, 153), \'stroke_width\': 1}],\n            [\'T\', [.255, .510 + pulse, \'音频设置\'], {\'font_size\': 17, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(73, 60, 46)}],\n            [\'T\', [.545, .510 + pulse, \'总开关\'], {\'font_size\': 11, \'align\': \'left\', \'color\': rgb(91, 74, 55)}],\n            [\'RR\', [.655, .484 + pulse, .095, .046, .023], {\n                \'fill\': rgb(54, 142, 104) if self.audio_enabled else rgb(190, 183, 165),\n                \'stroke\': rgb(35, 112, 81) if audio_hover else rgb(151, 135, 106),\n                \'stroke_width\': 2 if audio_hover else 1,\n            }],\n            [\'C\', [.721 if self.audio_enabled else .684, .507 + pulse, .017], {\'fill\': rgb(255, 250, 233)}],\n        ]\n\n        for label, value, y, key in (\n            (\'音乐音量\', self.master_volume, .435, \'master_volume\'),\n            (\'音效\', self.effects_volume, .335, \'effects_volume\'),\n        ):\n            hovered = self.hovered_item == (key, 0)\n            knob_x = .43 + .30 * value\n            data.extend([\n                [\'T\', [.255, y + .004 + pulse, label], {\'font_size\': 12, \'align\': \'left\', \'color\': rgb(91, 74, 55)}],\n                [\'RR\', [.43, y + pulse, .30, .012, .006], {\'fill\': rgb(211, 200, 174)}],\n                [\'RR\', [.43, y + pulse, .30 * value, .012, .006], {\'fill\': rgb(173, 126, 67)}],\n                [\'C\', [knob_x, y + .006 + pulse, .015 if hovered else .012], {\n                    \'fill\': rgb(139, 69, 19) if hovered else rgb(181, 129, 65),\n                    \'stroke\': rgb(255, 246, 220), \'stroke_width\': 2,\n                }],\n                [\'T\', [.765, y + .001 + pulse, f\'{round(value * 100)}%\'], {\n                    \'font_size\': 10, \'align\': \'right\', \'color\': rgb(118, 98, 72),\n                }],\n            ])\n        status = \'已启用 Canvas 批量渲染\' if accelerated else \'当前使用纯 Turtle 渲染\'\n        if not acceleration_available:\n            status += \'（命令行兼容模式）\'\n        data.extend([\n            [\'T\', [.50, .272 + pulse, status], {\'font_size\': 10, \'color\': rgb(119, 97, 70)}],\n            [\'RR\', [.39, .212, .22, .040, .018], {\n                \'fill\': rgb(139, 69, 19) if self.hovered_item == (\'guide\', 0) else rgb(232, 218, 187),\n                \'stroke\': rgb(203, 157, 74), \'stroke_width\': 2,\n            }],\n            [\'T\', [.50, .226, \'使用引导\'], {\'font_size\': 10, \'font_weight\': \'bold\', \'color\': rgb(255, 248, 229) if self.hovered_item == (\'guide\', 0) else rgb(91, 63, 39)}],\n        ])\n        self.parser.parse(data, self.bounds)\n\n    def draw_back_button(self):\n        """Global back affordance shared by every non-intro scene."""\n        hovered = self.hovered_item == (\'back\', 0)\n        data = [\n            [\'RR\', [.055, .875, .105, .060, .018], {\n                \'fill\': rgb(139, 69, 19) if hovered else rgb(232, 218, 187),\n                \'stroke\': rgb(164, 121, 62), \'stroke_width\': 1,\n            }],\n            [\'T\', [.108, .892, \'‹ 返回\'], {\'font_size\': 11, \'font_weight\': \'bold\',\n                                          \'color\': rgb(255, 248, 229) if hovered else rgb(91, 63, 39)}],\n        ]\n        self.parser.parse(data, self.bounds)\n\n    def draw_transition(self):\n        """A scroll-closing transition shared by all scene changes."""\n        cover = self.transition.cover\n        if cover <= 0:\n            return\n        half = .5 * cover\n        data = [\n            [\'R\', [0, 0, half, 1], {\'fill\': rgb(232, 218, 184), \'z\': 900}],\n            [\'R\', [1 - half, 0, half, 1], {\'fill\': rgb(232, 218, 184), \'z\': 900}],\n            [\'L\', [[half, .03], [half, .97]], {\'stroke\': rgb(169, 124, 65), \'stroke_width\': 3, \'z\': 910}],\n            [\'L\', [[1 - half, .03], [1 - half, .97]], {\'stroke\': rgb(169, 124, 65), \'stroke_width\': 3, \'z\': 910}],\n        ]\n        if cover > .84:\n            data.append([\'T\', [.5, .49, \'Canal delights\'], {\'font_size\': 18, \'color\': rgb(126, 82, 48), \'z\': 920}])\n        self.parser.parse(data, self.bounds)\n\n    def draw_finale(self):\n        """绘制终章"""\n        lantern_bob = .008 * math.sin(self.animation_phase * 1.8)\n        data = [\n            [\'T\', [0.5, 0.7, \'运河四季·人间五味\'], {\'font_size\': 36, \'color\': rgb(139, 69, 19)}],\n            [\'T\', [0.5, 0.55, \'五城印章已全部收集\'], {\'font_size\': 18, \'color\': rgb(100, 100, 100)}],\n            [\'T\', [0.5, 0.4 + lantern_bob, \'🏮  🏮  🏮  🏮  🏮\'], {\'font_size\': 24, \'color\': rgb(201, 48, 44)}],\n            [\'B\', [[.22,.34-lantern_bob],[.39,.37],[.62,.32+lantern_bob],[.78,.35]], {\'stroke\': rgb(218, 190, 130), \'stroke_width\': 2}],\n            [\'T\', [0.5, 0.25, \'一河通南北，五味见四时\'], {\'font_size\': 16, \'color\': rgb(150, 150, 150)}],\n            [\'T\', [0.5, 0.15, \'Enter 重新游览\'], {\'font_size\': 12, \'color\': rgb(150, 150, 150)}],\n        ]\n\n        self.parser.parse(data, self.bounds)\n\n    def draw_help(self):\n        """绘制首次旅程引导浮窗。"""\n        pulse = .004 * math.sin(self.animation_phase * 1.7)\n        data = [\n            # This is a modal overlay on the map, not a separate page.  Keep\n            # the map visible around the paper card instead of painting an\n            # opaque canvas-sized background.\n            [\'RR\', [.155, .135 + pulse, .69, .73, .040], {\'fill\': rgb(106, 75, 48), \'z\': 701}],\n            [\'RR\', [.165, .145 + pulse, .67, .71, .036], {\'fill\': rgb(250, 241, 215), \'stroke\': rgb(173, 126, 67), \'stroke_width\': 2, \'z\': 702}],\n            [\'T\', [.50, .775 + pulse, \'第一次出发前，先认识这条运河\'], {\'font_size\': 21, \'font_weight\': \'bold\', \'color\': rgb(73, 58, 43), \'z\': 703}],\n            [\'T\', [.50, .735 + pulse, \'一份轻松的游览说明，随时可在设置中再次打开\'], {\'font_size\': 9, \'color\': rgb(139, 112, 76), \'z\': 703}],\n            [\'L\', [[.22,.69+pulse],[.78,.69+pulse]], {\'stroke\': rgb(211, 180, 122), \'stroke_width\': 1, \'z\': 703}],\n            [\'T\', [.235, .635 + pulse, \'情境说明\'], {\'font_size\': 14, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(139, 69, 19), \'z\': 703}],\n            [\'T\', [.235, .600 + pulse, \'你坐在小船上，沿京杭大运河游览五座城市\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'T\', [.235, .568 + pulse, \'靠近城市定位标后，浮窗会告诉你下一步\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'T\', [.235, .505 + pulse, \'游船控制\'], {\'font_size\': 14, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(139, 69, 19), \'z\': 703}],\n            [\'T\', [.235, .470 + pulse, \'按住左右箭头或键盘 ← / → 驾船，松开后会自然减速\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'T\', [.235, .438 + pulse, \'航行时会有水花，速度越快水声越明显\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'T\', [.235, .375 + pulse, \'探索引导\'], {\'font_size\': 14, \'font_weight\': \'bold\', \'align\': \'left\', \'color\': rgb(139, 69, 19), \'z\': 703}],\n            [\'T\', [.235, .340 + pulse, \'靠近城市后点击浮窗“探索”，或按 Enter 进入\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'T\', [.235, .308 + pulse, \'在城市中选择美食，完成品鉴即可收集图鉴与印章\'], {\'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 703}],\n            [\'RR\', [.39, .165 + pulse, .22, .040, .018], {\'fill\': rgb(139, 69, 19), \'stroke\': rgb(203, 157, 74), \'stroke_width\': 2, \'z\': 703}],\n            [\'T\', [.50, .179 + pulse, \'开始探索\'], {\'font_size\': 10, \'font_weight\': \'bold\', \'color\': rgb(255, 248, 229), \'z\': 704}],\n        ]\n\n        self.parser.parse(data, self.bounds)\n\n    def draw_completion(self):\n        """绘制叠加在地图上的通关纪念浮窗。"""\n        pulse = .003 * math.sin(self.animation_phase * 1.5)\n        text = (\n            \'从北京的晨雾到杭州的晚风，你沿着一条水脉，收集了五座城的滋味。\'\n            \'运河不只运送粮米与百货，也把灶台的烟火、四季的鲜意和人们的乡愁，\'\n            \'一程一程地写进水声。北方的厚重，南方的清润，在船桨起落之间相逢；\'\n            \'一碗面、一笼点心、一盏茶，都是岸边人家对远客的温柔招呼。\'\n            \'如今图鉴已经合卷，但旅程并没有真正结束：当你再次想起这些味道，\'\n            \'运河仍会在记忆里缓缓流淌，带你回到那片有风、有水、有灯火的江南。\'\n        )\n        lines = self._wrapped_lines(text, 31)[:8]\n        data = [\n            [\'RR\', [.155, .135 + pulse, .69, .73, .040], {\'fill\': rgb(106, 75, 48), \'z\': 710}],\n            [\'RR\', [.165, .145 + pulse, .67, .71, .036], {\'fill\': rgb(250, 241, 215), \'stroke\': rgb(173, 126, 67), \'stroke_width\': 2, \'z\': 711}],\n            [\'T\', [.50, .775 + pulse, \'恭喜你，运河图鉴全收集\'], {\'font_size\': 21, \'font_weight\': \'bold\', \'color\': rgb(73, 58, 43), \'z\': 712}],\n            [\'T\', [.50, .735 + pulse, \'一册风物入手，五城烟火同行\'], {\'font_size\': 10, \'color\': rgb(139, 112, 76), \'z\': 712}],\n            [\'L\', [[.22,.69+pulse],[.78,.69+pulse]], {\'stroke\': rgb(211, 180, 122), \'stroke_width\': 1, \'z\': 712}],\n        ]\n        for index, line in enumerate(lines):\n            data.append([\'T\', [.235, .645 - index * .042 + pulse, line], {\n                \'font_size\': 10, \'align\': \'left\', \'color\': rgb(91, 74, 55), \'z\': 712,\n            }])\n        data.extend([\n            [\'RR\', [.39, .165 + pulse, .22, .040, .018], {\'fill\': rgb(139, 69, 19), \'stroke\': rgb(203, 157, 74), \'stroke_width\': 2, \'z\': 712}],\n            [\'T\', [.50, .179 + pulse, \'继续游览\'], {\'font_size\': 10, \'font_weight\': \'bold\', \'color\': rgb(255, 248, 229), \'z\': 713}],\n        ])\n        self.parser.parse(data, self.bounds)\n\n    def draw_status(self):\n        """绘制状态提示"""\n        mode_names = {\n            Mode.INTRO: \'开场\',\n            Mode.LOADING: \'加载\',\n            Mode.MAP: \'地图\',\n            Mode.CITY: \'城市\',\n            Mode.FOOD_DETAIL: \'详情\',\n            Mode.ATLAS: \'图鉴\',\n            Mode.SETTINGS: \'设置\',\n            Mode.FINALE: \'终章\',\n        }\n        mode_name = mode_names.get(self.state.mode, \'未知\')\n        data = [\n            [\'T\', [0.95, 0.065, f\'FPS: {round(self._fps):02d}  [{mode_name}]\'], {\n                \'font_size\': 12, \'font_weight\': \'bold\',\n                \'color\': rgb(169, 151, 124), \'align\': \'right\',\n            }],\n        ]\n        self.parser.parse(data, self.bounds)\n\n    # 事件处理\n    def begin_transition(self, action):\n        """Lock input and change scene at the covered midpoint."""\n        if self.transition.active:\n            return\n        self.move_direction = 0\n        self._pressed_nav = None\n        self.state.transition_locked = True\n\n        def switch_scene():\n            # StateMachine intentionally rejects transitions while locked, so\n            # unlock only for the atomic midpoint scene change.\n            self.state.transition_locked = False\n            action()\n            self._maybe_open_completion()\n            self.state.transition_locked = True\n            self.hovered_item = None\n\n        self.transition.start(switch_scene)\n\n    def _maybe_open_completion(self):\n        """在完成收集后再次抵达地图时打开一次通关浮窗。"""\n        if (self.state.mode == Mode.MAP and self.state.is_all_stamped()\n                and not self._completion_auto_shown):\n            self.state.completion_open = True\n            self._completion_auto_shown = True\n\n    def _open_completion_from_atlas(self):\n        """从图鉴奖杯回到地图，并重新打开通关浮窗。"""\n        self.machine.back()\n        self.state.completion_open = True\n\n    def on_enter(self):\n        """Enter 键"""\n        if self.state.transition_locked:\n            return\n        if self.state.help_open:\n            self.machine.toggle_help()\n            self.render()\n            return\n        if self.state.completion_open:\n            self.state.completion_open = False\n            self.render()\n            return\n\n        if self.state.mode == Mode.INTRO:\n            self.effects.play(\'key\')\n            self.begin_transition(self._enter_journey)\n        elif self.state.mode == Mode.MAP:\n            if self.state.is_all_stamped():\n                self.state.completion_open = True\n            elif self.boat.nearby_city() is not None:\n                self.state.current_city = self.boat.nearby_city()\n                self.effects.play(\'fresh\')\n                self.begin_transition(self.machine.enter_city)\n        elif self.state.mode == Mode.CITY:\n            self.effects.play(\'scroll\')\n            self.begin_transition(self.machine.open_food)\n        elif self.state.mode == Mode.FOOD_DETAIL:\n            self.effects.play(\'stamp\')\n            self.begin_transition(self.machine.complete_tasting)\n        elif self.state.mode == Mode.ATLAS:\n            self._turn_atlas(1)\n        elif self.state.mode == Mode.FINALE:\n            self.begin_transition(self.machine.return_from_finale)\n\n        self.render()\n\n    def on_escape(self):\n        """Esc 键"""\n        if self.state.help_open:\n            self.machine.toggle_help()\n        elif self.state.completion_open:\n            self.state.completion_open = False\n        elif self.state.mode == Mode.FINALE:\n            self.begin_transition(self.machine.return_from_finale)\n        elif self.state.mode != Mode.INTRO:\n            self.effects.play(\'scroll\' if self.state.mode in (Mode.ATLAS, Mode.FOOD_DETAIL) else \'key\')\n            self.begin_transition(self.machine.back)\n        self.render()\n\n    def on_left(self):\n        """左方向键"""\n        if self.state.help_open or self.state.transition_locked:\n            return\n\n        if self.state.mode == Mode.MAP:\n            self.move_direction = -1\n        elif self.state.mode == Mode.CITY:\n            self.machine.prev_food()\n            self.render()\n        elif self.state.mode == Mode.ATLAS:\n            self._turn_atlas(-1)\n\n    def on_right(self):\n        """右方向键"""\n        if self.state.help_open or self.state.transition_locked:\n            return\n\n        if self.state.mode == Mode.MAP:\n            self.move_direction = 1\n        elif self.state.mode == Mode.CITY:\n            self.machine.next_food()\n            self.render()\n        elif self.state.mode == Mode.ATLAS:\n            self._turn_atlas(1)\n\n    def on_direction_release(self):\n        self.move_direction = 0\n\n    def _turn_atlas(self, direction):\n        previous = self.state.atlas_page\n        self.machine.turn_atlas(direction)\n        if self.state.atlas_page != previous:\n            self.effects.play(\'page\')\n            self.book_turn = float(direction)\n            self.render()\n\n    def on_animation_frame(self, delta_seconds):\n        """Drive restrained vector motion, boat physics and transitions."""\n        # Measure delivered animation frames over a short rolling window so\n        # the indicator reflects real rendering performance rather than the\n        # configured target FPS.\n        now = perf_counter()\n        measured_delta = (now - self._fps_last_time) if self._fps_last_time is not None else 0.0\n        self._fps_last_time = now\n        self._fps_elapsed += max(0.0, measured_delta)\n        self._fps_frames += 1\n        if self._fps_elapsed >= .25:\n            self._fps = self._fps_frames / self._fps_elapsed\n            self._fps_elapsed = 0.0\n            self._fps_frames = 0\n        self.animation_phase += delta_seconds\n        was_transitioning = self.transition.active\n        self.transition.step(delta_seconds)\n        if abs(self.book_turn) > .001:\n            self.book_turn *= math.exp(-7.5 * delta_seconds)\n        else:\n            self.book_turn = 0.0\n        if was_transitioning and not self.transition.active:\n            self.state.transition_locked = False\n\n        if self.state.mode == Mode.LOADING:\n            ceiling = self._loading_target if self._loading_complete else min(self._loading_target + .42, .92)\n            self._loading_progress += (ceiling - self._loading_progress) * min(1., delta_seconds * 2.6)\n            if self._loading_complete and self._loading_progress >= .985 and not self._loading_finished_transition:\n                self._loading_finished_transition = True\n                if self.audio_enabled:\n                    self.music.start()\n                self.begin_transition(self._finish_first_loading)\n\n        if self.state.mode == Mode.MAP:\n            moved = self.boat.step(self.move_direction, delta_seconds)\n            self.splash.step(delta_seconds)\n            self._splash_elapsed += delta_seconds\n            if moved and abs(self.boat.velocity) > .018 and self._splash_elapsed >= .075:\n                x, y = route_point(self.boat.position)\n                self.splash.emit(\n                    x, y - .018,\n                    1 if self.boat.velocity >= 0 else -1,\n                    2 if self.engine.mode_name == \'accelerated\' else 1,\n                )\n                self._splash_elapsed = 0.0\n            nearby = self.boat.nearby_city()\n            if nearby is not None:\n                self.state.current_city = nearby\n            self.effects.set_water_level(abs(self.boat.velocity) / self.boat.max_speed)\n        else:\n            self.effects.set_water_level(0)\n        self.render()\n        return True\n\n    def on_help(self):\n        """H 键"""\n        if self.state.transition_locked:\n            return\n        self.machine.toggle_help()\n        self.render()\n\n    def on_atlas(self):\n        """B toggles the atlas from either side of the map."""\n        if self.state.transition_locked or self.state.help_open:\n            return\n        if self.state.mode == Mode.MAP:\n            self.effects.play(\'scroll\')\n            self.begin_transition(self.machine.open_atlas)\n        elif self.state.mode == Mode.ATLAS:\n            self.effects.play(\'scroll\')\n            self.begin_transition(self.machine.back)\n        self.render()\n\n    def _toggle_acceleration(self):\n        """Switch renderer implementation while preserving application state."""\n        if not self.engine.supports_acceleration:\n            return\n        self.engine.set_acceleration(self.engine.mode_name != \'accelerated\')\n        self._background_rendered = False\n        accelerated = self.engine.mode_name == \'accelerated\'\n        self.animations.set_fps(30 if accelerated else 10)\n        self.splash.limit = 36 if accelerated else 10\n        self.splash.drops = self.splash.drops[-self.splash.limit:]\n\n    def _set_volume(self, setting, nx):\n        value = max(0.0, min(1.0, (nx - .43) / .30))\n        if setting == \'master_volume\':\n            self.master_volume = value\n            self.music.set_volume(value)\n        else:\n            self.effects_volume = value\n            self.effects.set_volume(value)\n\n    def _toggle_audio(self):\n        self.audio_enabled = not self.audio_enabled\n        self.music.set_enabled(self.audio_enabled)\n        self.effects.set_enabled(self.audio_enabled)\n\n    def on_motion(self, x, y):\n        """Update semantic hover state without redrawing for every pixel."""\n        nx, ny = x / CANVAS_WIDTH, y / CANVAS_HEIGHT\n        hovered = None\n\n        if self.state.transition_locked:\n            return\n        if not self.state.help_open and self.state.mode != Mode.INTRO and .045 <= nx <= .17 and .86 <= ny <= .95:\n            hovered = (\'back\', 0)\n        elif not self.state.help_open and self.state.mode == Mode.INTRO:\n            if .35 <= nx <= .65 and .14 <= ny <= .26:\n                hovered = (\'start\', 0)\n        elif not self.state.help_open and self.state.mode == Mode.MAP:\n            if .825 <= nx <= .955 and .85 <= ny <= .94:\n                hovered = (\'settings\', 0)\n            elif .04 <= nx <= .21 and .05 <= ny <= .17:\n                hovered = (\'atlas\', 0)\n            else:\n                nearby = self.boat.nearby_city()\n                if nearby is not None and self._inside(\n                    nx, ny, self._preview_layout(nearby)[-1],\n                ):\n                    hovered = (\'explore\', nearby)\n                elif .045 <= nx <= .14 and .37 <= ny <= .51:\n                    hovered = (\'nav\', -1)\n                elif .86 <= nx <= .955 and .37 <= ny <= .51:\n                    hovered = (\'nav\', 1)\n        elif not self.state.help_open and self.state.mode == Mode.CITY:\n            city_id = get_city(self.state.current_city)[\'id\']\n            for index, (px, py) in enumerate(FOOD_POSITIONS[city_id]):\n                if (px - nx) ** 2 + (py - ny) ** 2 <= .010:\n                    hovered = (\'food\', index)\n                    break\n        elif not self.state.help_open and self.state.mode == Mode.FOOD_DETAIL:\n            if .73 <= nx <= .91 and .16 <= ny <= .25:\n                hovered = (\'taste\', 0)\n        elif not self.state.help_open and self.state.mode == Mode.ATLAS:\n            if .19 <= nx <= .33 and .09 <= ny <= .17 and self.state.atlas_page > 0:\n                hovered = (\'atlas_nav\', -1)\n            elif .67 <= nx <= .81 and .09 <= ny <= .17 and self.state.atlas_page < 5:\n                hovered = (\'atlas_nav\', 1)\n        elif not self.state.help_open and self.state.mode == Mode.SETTINGS:\n            if .36 <= nx <= .64 and .20 <= ny <= .27:\n                hovered = (\'guide\', 0)\n            elif .64 <= nx <= .77 and .47 <= ny <= .54:\n                hovered = (\'audio_enabled\', 0)\n            elif (.64 <= nx <= .77 and .60 <= ny <= .69\n                    and self.engine.supports_acceleration):\n                hovered = (\'acceleration\', 0)\n            elif .40 <= nx <= .75 and .40 <= ny <= .48:\n                hovered = (\'master_volume\', 0)\n            elif .40 <= nx <= .75 and .30 <= ny <= .38:\n                hovered = (\'effects_volume\', 0)\n\n        self.engine.set_cursor(\'hand2\' if hovered is not None else \'\')\n        if hovered != self.hovered_item:\n            self.hovered_item = hovered\n            self.render()\n\n    def on_click(self, x, y):\n        """鼠标点击"""\n        if self.state.transition_locked:\n            return\n        if self.state.help_open:\n            self.effects.play(\'key\')\n            self.machine.toggle_help()\n            self.render()\n            return\n        if self.state.completion_open:\n            self.effects.play(\'key\')\n            self.state.completion_open = False\n            self.render()\n            return\n\n        nx, ny = x / CANVAS_WIDTH, y / CANVAS_HEIGHT\n        if self.state.can_go_back() and .045 <= nx <= .17 and .86 <= ny <= .95:\n            self.effects.play(\'scroll\' if self.state.mode in (Mode.ATLAS, Mode.FOOD_DETAIL) else \'key\')\n            if self.state.mode == Mode.FINALE:\n                self.begin_transition(self.machine.return_from_finale)\n            else:\n                self.begin_transition(self.machine.back)\n        elif self.state.mode == Mode.INTRO:\n            if .35 <= nx <= .65 and .14 <= ny <= .26:\n                self.effects.play(\'key\')\n                self.begin_transition(self._enter_journey)\n        elif self.state.mode == Mode.MAP:\n            if .825 <= nx <= .955 and .85 <= ny <= .94:\n                self.effects.play(\'key\')\n                self.begin_transition(self.machine.open_settings)\n            elif .04 <= nx <= .21 and .05 <= ny <= .17:\n                self.effects.play(\'scroll\')\n                self.begin_transition(self.machine.open_atlas)\n            else:\n                nearby = self.boat.nearby_city()\n                if nearby is not None and self._inside(\n                    nx, ny, self._preview_layout(nearby)[-1],\n                ):\n                    self.state.current_city = nearby\n                    self.effects.play(\'fresh\')\n                    self.begin_transition(self.machine.enter_city)\n                elif .045 <= nx <= .14 and .37 <= ny <= .51:\n                    self.effects.play(\'key\')\n                    self.boat.nudge(-1)\n                elif .86 <= nx <= .955 and .37 <= ny <= .51:\n                    self.effects.play(\'key\')\n                    self.boat.nudge(1)\n        elif self.state.mode == Mode.CITY:\n            city_id = get_city(self.state.current_city)[\'id\']\n            for index, (px, py) in enumerate(FOOD_POSITIONS[city_id]):\n                if (px - nx) ** 2 + (py - ny) ** 2 <= .010:\n                    self.state.current_food = index\n                    self.effects.play(\'scroll\')\n                    self.begin_transition(self.machine.open_food)\n                    break\n        elif self.state.mode == Mode.FOOD_DETAIL:\n            if .73 <= nx <= .91 and .16 <= ny <= .25:\n                self.effects.play(\'stamp\')\n                self.begin_transition(self.machine.complete_tasting)\n        elif self.state.mode == Mode.ATLAS:\n            if (self.state.atlas_page == 0 and self.state.is_all_stamped()\n                    and .74 <= nx <= .88 and .25 <= ny <= .38):\n                self.effects.play(\'stamp\')\n                self.begin_transition(self._open_completion_from_atlas)\n            elif .19 <= nx <= .33 and .09 <= ny <= .17:\n                self._turn_atlas(-1)\n            elif .67 <= nx <= .81 and .09 <= ny <= .17:\n                self._turn_atlas(1)\n        elif self.state.mode == Mode.SETTINGS:\n            if .36 <= nx <= .64 and .20 <= ny <= .27:\n                self.effects.play(\'scroll\')\n                self.begin_transition(self._open_guide_from_settings)\n            elif .64 <= nx <= .77 and .47 <= ny <= .54:\n                self.effects.play(\'key\')\n                self._toggle_audio()\n            elif .64 <= nx <= .77 and .60 <= ny <= .69:\n                self.effects.play(\'key\')\n                self._toggle_acceleration()\n            elif .40 <= nx <= .75 and .40 <= ny <= .48:\n                self._set_volume(\'master_volume\', nx)\n            elif .40 <= nx <= .75 and .30 <= ny <= .38:\n                self._set_volume(\'effects_volume\', nx)\n        self.render()\n\n    def on_pointer_press(self, x, y):\n        """Turn map arrows into continuous press-and-hold throttles."""\n        if self.state.mode != Mode.MAP or self.state.help_open or self.state.transition_locked:\n            return\n        nx, ny = x / CANVAS_WIDTH, y / CANVAS_HEIGHT\n        nearby = self.boat.nearby_city()\n        if nearby is not None and self._inside(\n            nx, ny, self._preview_layout(nearby)[-1],\n        ):\n            # The floating Explore button intentionally wins when the Suzhou\n            # card overlaps the forward throttle.\n            return\n        direction = 0\n        if .045 <= nx <= .14 and .37 <= ny <= .51:\n            direction = -1\n        elif .86 <= nx <= .955 and .37 <= ny <= .51:\n            direction = 1\n        if direction:\n            self._pressed_nav = direction\n            self.move_direction = direction\n            self.hovered_item = (\'nav\', direction)\n            self.render()\n\n    def on_pointer_release(self, _x, _y):\n        if self._pressed_nav is not None:\n            self._pressed_nav = None\n            self.move_direction = 0\n            self.render()\n\n\ndef main(argv=None):\n    """主程序入口"""\n    import argparse\n    import os\n\n    parser = argparse.ArgumentParser(description=\'运河风物志 Canal Delights\')\n    parser.add_argument(\n        \'--renderer\', choices=[mode.value for mode in RenderMode],\n        default=os.environ.get(\'CANAL_RENDERER\', RenderMode.ACCELERATED.value),\n        help=\'渲染后端：accelerated（默认）或 pure（纯 Turtle）\',\n    )\n    args = parser.parse_args(argv)\n    app = App(args.renderer)\n    app.run()\n\n\nif __name__ == \'__main__\':\n    main()\n', 'canal_delights.config': '"""\n配置文件 - DSL 类型定义、主题常量\n"""\n\n# ============================================\n# DSL 类型码定义（14 种）\n# ============================================\n\n# 类型码 -> (名称, 描述)\nPRIMITIVE_TYPES = {\n    # 基础图形\n    \'P\':    (\'Point\',        \'点状纹理\'),\n    \'L\':    (\'Line\',         \'线段/折线\'),\n    \'R\':    (\'Rect\',         \'矩形\'),\n    \'RR\':   (\'RoundedRect\',  \'圆角矩形\'),\n    \'C\':    (\'Circle\',       \'圆形\'),\n    \'E\':    (\'Ellipse\',      \'椭圆\'),\n    \'G\':    (\'Polygon\',      \'多边形\'),\n    \'A\':    (\'Arc\',          \'弧形\'),\n\n    # 曲线\n    \'Q\':    (\'Quadratic\',    \'二次贝塞尔\'),\n    \'B\':    (\'Cubic\',        \'三次贝塞尔\'),\n    \'PATH\': (\'CompoundPath\', \'复合路径\'),\n\n    # 装饰\n    \'RG\':   (\'Ring\',         \'圆环\'),\n\n    # 文字\n    \'T\':    (\'Text\',         \'文字\'),\n\n    # 组合\n    \'GR\':   (\'Group\',        \'组/容器\'),\n}\n\n# 类型码列表（用于校验）\nVALID_TYPE_CODES = set(PRIMITIVE_TYPES.keys())\n\n\n# ============================================\n# Style 结构定义\n# ============================================\n\ndef make_style(\n    fill=None,\n    stroke=None,\n    stroke_width=1.0,\n    cap=\'round\',\n    join=\'round\',\n    gradient=None,\n    opacity=1.0,\n    blend_with=None,\n    z=0,\n):\n    """\n    创建样式对象\n\n    参数:\n        fill: RGB 元组 (r, g, b) 或 None（不填充）\n        stroke: RGB 元组 (r, g, b) 或 None（不描边）\n        stroke_width: 线宽\n        cap: 线端样式 \'round\' | \'butt\' | \'square\'\n        join: 连接样式 \'round\' | \'miter\' | \'bevel\'\n        gradient: 渐变定义字典或 None\n        opacity: 不透明度 0.0-1.0（需配合 blend_with 预混色）\n        blend_with: 背景色 RGB 元组（opacity < 1 时必须提供）\n        z: z-order 层级\n    """\n    return {\n        \'fill\': fill,\n        \'stroke\': stroke,\n        \'stroke_width\': stroke_width,\n        \'cap\': cap,\n        \'join\': join,\n        \'gradient\': gradient,\n        \'opacity\': opacity,\n        \'blend_with\': blend_with,\n        \'z\': z,\n    }\n\n\ndef make_text_style(\n    font_family=\'Microsoft YaHei\',\n    font_size=16,\n    font_weight=\'normal\',\n    align=\'center\',\n    color=None,\n    z=0,\n):\n    """\n    创建文字样式\n\n    参数:\n        font_family: 字体名称（需提供回退列表）\n        font_size: 字号\n        font_weight: \'normal\' | \'bold\'\n        align: \'left\' | \'center\' | \'right\'\n        color: 文字颜色 RGB\n        z: z-order\n    """\n    return {\n        \'font_family\': font_family,\n        \'font_size\': font_size,\n        \'font_weight\': font_weight,\n        \'align\': align,\n        \'color\': color,\n        \'z\': z,\n    }\n\n\n# ============================================\n# Transform 结构定义\n# ============================================\n\ndef make_transform(\n    translate=None,\n    scale=None,\n    rotate=None,\n    pivot=None,\n):\n    """\n    创建变换对象\n\n    执行顺序：局部点 → 缩放 → 旋转 → 平移 → 映射到 bounds\n\n    参数:\n        translate: [dx, dy] 平移\n        scale: [sx, sy] 缩放\n        rotate: 旋转角度（度）\n        pivot: [px, py] 变换枢轴点（归一化坐标）\n    """\n    return {\n        \'translate\': translate,\n        \'scale\': scale,\n        \'rotate\': rotate,\n        \'pivot\': pivot,\n    }\n\n\n# ============================================\n# 渐变定义\n# ============================================\n\ndef linear_gradient(stops, angle=0, steps=36):\n    """\n    创建线性渐变\n\n    参数:\n        stops: 颜色断点列表 [[(r,g,b), position], ...]\n               position: 0.0-1.0\n        angle: 渐变角度（度）0=左到右，90=上到下\n        steps: 渐变步数\n    """\n    return {\n        \'type\': \'linear\',\n        \'stops\': stops,\n        \'angle\': angle,\n        \'steps\': steps,\n    }\n\n\ndef radial_gradient(stops, center=None, steps=32):\n    """\n    创建径向渐变\n\n    参数:\n        stops: 颜色断点列表 [[(r,g,b), position], ...]\n               position: 0.0-1.0\n        center: 圆心位置 [x, y]，归一化坐标，默认 [0.5, 0.5]\n        steps: 渐变步数\n    """\n    return {\n        \'type\': \'radial\',\n        \'stops\': stops,\n        \'center\': center if center else [0.5, 0.5],\n        \'steps\': steps,\n    }\n\n\n# ============================================\n# 中国传统配色\n# ============================================\n\ndef rgb(r, g, b):\n    """创建 RGB 颜色"""\n    return (r, g, b)\n\n\nCOLORS = {\n    # 城市主题色\n    \'北京红\': rgb(201, 48, 44),\n    \'天津褐\': rgb(139, 69, 19),\n    \'扬州青\': rgb(46, 139, 87),\n    \'苏州蓝\': rgb(65, 105, 225),\n    \'杭州绿\': rgb(107, 142, 35),\n\n    # 通用色\n    \'墨黑\':   rgb(26, 26, 26),\n    \'宣纸白\': rgb(245, 240, 220),\n    \'古铜金\': rgb(184, 134, 11),\n    \'青灰\':   rgb(112, 128, 144),\n\n    # 食物色\n    \'烤鸭红\': rgb(139, 69, 19),\n    \'月饼金\': rgb(218, 165, 32),\n    \'包子白\': rgb(255, 250, 240),\n    \'粽子绿\': rgb(46, 139, 87),\n    \'茶汤绿\': rgb(143, 188, 143),\n}\n\n\n# ============================================\n# 主题配置\n# ============================================\n\nTHEME = {\n    \'colors\': COLORS,\n\n    \'spacing\': {\n        \'xs\': 5,\n        \'sm\': 10,\n        \'md\': 20,\n        \'lg\': 40,\n        \'xl\': 60,\n    },\n\n    \'font\': {\n        \'title\': 36,\n        \'heading\': 24,\n        \'body\': 16,\n        \'caption\': 12,\n    },\n\n    \'canvas\': {\n        \'width\': 1200,\n        \'height\': 800,\n        \'background\': COLORS[\'宣纸白\'],\n        \'margin\': 40,\n    },\n\n    # 字体回退列表\n    \'font_families\': {\n        \'default\': [\'Microsoft YaHei\', \'PingFang SC\', \'Hiragino Sans GB\', \'sans-serif\'],\n        \'title\': [\'STKaiti\', \'KaiTi\', \'Microsoft YaHei\', \'sans-serif\'],\n    },\n}\n\n\n# ============================================\n# 画布常量\n# ============================================\n\nCANVAS_WIDTH = THEME[\'canvas\'][\'width\']\nCANVAS_HEIGHT = THEME[\'canvas\'][\'height\']\nCANVAS_MARGIN = THEME[\'canvas\'][\'margin\']\nCANVAS_BG = THEME[\'canvas\'][\'background\']\n', 'canal_delights.content.__init__': '"""\n内容模块 - 城市、美食数据\n"""\n', 'canal_delights.content.catalog': '"""京杭大运河五城二十味的正式内容数据。"""\n\nfrom ..config import rgb\n\n\nCITIES = [\n    {\n        \'id\': \'beijing\', \'name\': \'北京\', \'theme\': rgb(201, 48, 44),\n        \'cuisine\': \'京菜 · 宫廷与市井的交融\',\n        \'description\': \'皇城礼序与胡同烟火在此相遇，炙烤、酱香与铜锅共同写下北方味觉。\',\n        \'foods\': [\n            {\'id\': \'roast_duck\', \'name\': \'烤鸭\',\n             \'intro\': \'皮色枣红油亮，酥脆如纸，肉嫩脂润，是北方炭火炙烤风味的巅峰。\',\n             \'story\': \'起源众说纷纭，一说源于南京，明成祖迁都北京后技艺北传，清代成为宫廷御膳，后分化出焖炉、挂炉两大流派，成为北京最具代表性的美食名片。\'},\n            {\'id\': \'mutton_hotpot\', \'name\': \'涮羊肉\',\n             \'intro\': \'薄切羊肉入沸汤即熟，鲜嫩无膻，佐以醇厚麻酱，是北方冬季的味觉图腾。\',\n             \'story\': \'传说源于元代忽必烈行军途中，厨师急智将羊肉切薄片涮煮，后随满族入关传入北京，清代成为宫廷宴席菜品，清末流入市井成为冬季全民美食。\'},\n            {\'id\': \'zhajiang_noodles\', \'name\': \'炸酱面\',\n             \'intro\': \'酱香浓郁、咸鲜醇厚，菜码缤纷，是老北京人刻在骨子里的家常味道。\',\n             \'story\': \'源于清代满族“以酱代菜”的饮食习惯，清末由隆福寺街饭馆的“凉烂肉面”改良而来，20世纪中叶后随着面粉供应充足进入鼎盛期，成为老北京饮食文化符号。\'},\n            {\'id\': \'luzhu\', \'name\': \'卤煮\',\n             \'intro\': \'汤汁浓稠厚重，食材软烂入味，是老北京市井烟火气的极致浓缩。\',\n             \'story\': \'前身是清代宫廷御膳“苏造肉”，光绪年间因五花肉价格昂贵，民间改用廉价猪下水替代，加入火烧同煮，逐渐演变为老北京最具烟火气的市井小吃。\'},\n        ],\n    },\n    {\n        \'id\': \'tianjin\', \'name\': \'天津\', \'theme\': rgb(139, 69, 19),\n        \'cuisine\': \'津菜 · 码头小吃的江湖\',\n        \'description\': \'漕运码头汇聚南北食风，热气腾腾的早点最能代表这座城市的爽利性情。\',\n        \'foods\': [\n            {\'id\': \'jianbing\', \'name\': \'煎饼果子\',\n             \'intro\': \'软韧与酥脆交织，酱香葱香交融，是天津清晨街巷最熟悉的味觉信号。\',\n             \'story\': \'源于明清时期天津漕运码头，最初是山东煎饼与江南油条结合的码头工人夜宵，20世纪中叶加入鸡蛋后转为早餐，如今是天津最具辨识度的城市名片。\'},\n            {\'id\': \'baozi\', \'name\': \'包子\',\n             \'intro\': \'皮薄韧有咬劲，馅鲜汁盈，一口咬下满嘴浓香，是天津面点工艺的集大成者。\',\n             \'story\': \'清末武清人高贵友在天津侯家后摆摊卖包子，因生意忙碌无暇应答顾客，被戏称“狗不理”，光绪年间袁世凯将其进献慈禧太后，从此名扬天下。\'},\n            {\'id\': \'mahua\', \'name\': \'麻花\',\n             \'intro\': \'金黄酥脆，甜香层叠，越嚼越香，是天津传统点心的标志性符号。\',\n             \'story\': \'1927年天津十八街巷弄里的刘老八创立“桂发祥”麻花铺，一次偶然将剩余点心渣混入面团炸制，意外创出夹馅麻花的工艺，成为天津三绝之一。\'},\n            {\'id\': \'guobacai\', \'name\': \'锅巴菜\',\n             \'intro\': \'软滑筋道，卤香醇厚，层次丰富，是天津独有的早餐味觉密码。\',\n             \'story\': \'源于山东煎饼吃法，清乾隆年间传入天津后改良为本地风味，相传乾隆南巡时曾品尝并赐名，光绪年间工艺定型，是天津独有的早餐品类。\'},\n        ],\n    },\n    {\n        \'id\': \'yangzhou\', \'name\': \'扬州\', \'theme\': rgb(46, 139, 87),\n        \'cuisine\': \'淮扬菜 · 刀工雅馔的巅峰\',\n        \'description\': \'盐商宴饮与水乡物产相映成趣，细密刀工和清鲜汤功藏着扬州的从容。\',\n        \'foods\': [\n            {\'id\': \'lion_head\', \'name\': \'狮子头\',\n             \'intro\': \'形如狮首，入口即化，肥而不腻，是淮扬菜“以柔克刚”风味的代表。\',\n             \'story\': \'原名“葵花斩肉”，相传隋炀帝南巡扬州时御厨以葵花岗为名创制，唐代郇国公宴客时宾客见肉丸形似狮首，遂改名为狮子头，是淮扬三头宴之首。\'},\n            {\'id\': \'boiled_shredded_tofu\', \'name\': \'大煮干丝\',\n             \'intro\': \'干丝绵软，汤汁清鲜，看似朴素却极见功夫，是淮扬菜刀工与汤功的双重考验。\',\n             \'story\': \'源于清乾隆年间扬州接驾宴席的“九丝汤”，晚清民国时期简化配料后定名为大煮干丝，凭借极致的刀工和汤头工艺成为淮扬菜的代表菜式。\'},\n            {\'id\': \'soup_dumpling\', \'name\': \'汤包\',\n             \'intro\': \'皮薄如纱，汤满如泉，鲜美醇厚，是扬州早茶文化中最动人的味觉惊喜。\',\n             \'story\': \'清代扬州茶肆已盛行制作灌汤包，利用冬季肉汤易凝的特点将凝汤包入馅料，蒸熟后汤汁融化，是扬州“早上皮包水”早茶文化的标志性点心。\'},\n            {\'id\': \'fried_rice\', \'name\': \'炒饭\',\n             \'intro\': \'粒粒金黄分明，配料丰富，香气四溢，是中国炒饭走向世界的第一张名片。\',\n             \'story\': \'雏形可追溯至隋代越国公杨素创制的“碎金饭”，清嘉庆年间扬州太守伊秉绶在蛋炒饭基础上加入多种配料，奠定了现代扬州炒饭的格局，传遍海内外。\'},\n        ],\n    },\n    {\n        \'id\': \'suzhou\', \'name\': \'苏州\', \'theme\': rgb(65, 105, 225),\n        \'cuisine\': \'苏帮菜 · 河鲜甜韵的极致\',\n        \'description\': \'粉墙黛瓦之间讲究不时不食，河鲜、面汤与糕团共同组成精巧的四季。\',\n        \'foods\': [\n            {\'id\': \'squirrel_fish\', \'name\': \'松鼠鳜鱼\',\n             \'intro\': \'形似松鼠蓬松翘立，外酥里嫩，酸甜鲜香，是苏帮菜色香味形的集大成者。\',\n             \'story\': \'相传清代乾隆皇帝微服到苏州松鹤楼，店主为避宰杀供桌神鱼的罪责，将鱼烹制成松鼠状，乾隆食后大悦，此菜由此名扬苏州，成为苏帮菜头牌。\'},\n            {\'id\': \'suzhou_noodles\', \'name\': \'苏式汤面\',\n             \'intro\': \'汤清面爽，浇头百变，一碗面里藏着苏州人“不时不食”的生活哲学。\',\n             \'story\': \'历史可追溯至唐宋时期，清代形成完整的制作技艺体系，苏州人讲究“不时不食”，不同季节搭配不同浇头，是苏州人日常饮食的重要组成部分。\'},\n            {\'id\': \'eel_paste\', \'name\': \'鳝糊\',\n             \'intro\': \'鲜嫩滑爽，酱香蒜香交织，热油一淋香气炸裂，是苏帮菜河鲜风味的代表。\',\n             \'story\': \'起源于明清时期苏州水乡，依托当地盛产黄鳝的地理条件创制，夏季黄鳝最为肥美，这道菜成为苏州夏令时节的应季佳肴，体现苏帮菜的时令理念。\'},\n            {\'id\': \'rice_cake\', \'name\': \'糕团\',\n             \'intro\': \'软糯香甜，造型精巧，四季品类各异，是苏州人岁时节庆不可或缺的甜蜜符号。\',\n             \'story\': \'传说源于春秋时期伍子胥建阖闾大城时用糯米粉做城砖救城的典故，苏州人春节吃年糕纪念伍子胥的习俗流传至今，糕团也成为苏州时令点心的代表。\'},\n        ],\n    },\n    {\n        \'id\': \'hangzhou\', \'name\': \'杭州\', \'theme\': rgb(107, 142, 35),\n        \'cuisine\': \'杭帮菜 · 清鲜雅致的典范\',\n        \'description\': \'西湖山水、龙井茶香与南宋旧事入馔，味道清鲜，也带着文人的温雅。\',\n        \'foods\': [\n            {\'id\': \'west_lake_fish\', \'name\': \'西湖醋鱼\',\n             \'intro\': \'肉质鲜嫩，酸甜清爽，带有独特的“赛蟹”风味，是杭帮菜的头号名片。\',\n             \'story\': \'源于南宋“宋嫂鱼羹”，民间流传“叔嫂传珍”的典故，清代演变为“醋搂鱼”，20世纪30年代定型为现在的做法，是杭帮菜的头号名片。\'},\n            {\'id\': \'dongpo_pork\', \'name\': \'东坡肉\',\n             \'intro\': \'色泽红亮如琥珀，酥烂醇香，肥而不腻，是文人美食的千古典范。\',\n             \'story\': \'北宋苏轼任杭州知州时，组织民工疏浚西湖，百姓赠猪肉致谢，苏轼命人按黄州旧法烹制后分送民工，百姓感念其德，将其命名为“东坡肉”。\'},\n            {\'id\': \'longjing_shrimp\', \'name\': \'龙井虾仁\',\n             \'intro\': \'虾仁晶莹，茶芽翠绿，清鲜雅致，是杭州茶文化与饮食文化最诗意的结合。\',\n             \'story\': \'相传乾隆下江南时，店主误将龙井茶叶当作葱花撒入炒虾仁中，乾隆品尝后赞不绝口，赐名“龙井虾仁”，是杭州茶文化与饮食文化结合的经典。\'},\n            {\'id\': \'pianerchuan\', \'name\': \'片儿川\',\n             \'intro\': \'汤浓面滑，咸鲜适口，雪菜笋片瘦肉三鲜交融，是杭州市井早餐的灵魂。\',\n             \'story\': \'源于清末杭州奎元馆，最初为招徕赶考学子推出，添加三颗鸡蛋寓意“连中三元”，后高中解元的书生题写店名，从此名声大振，成为杭州面条的代表。\'},\n        ],\n    },\n]\n\n\ndef get_city(index: int) -> dict:\n    """获取城市数据。"""\n    return CITIES[index % len(CITIES)]\n\n\ndef get_food(city_index: int, food_index: int) -> dict:\n    """获取美食数据。"""\n    city = get_city(city_index)\n    return city[\'foods\'][food_index % len(city[\'foods\'])]\n\n\ndef get_all_cities() -> list:\n    """获取所有城市。"""\n    return CITIES\n', 'canal_delights.content.foods.__init__': '"""\n美食绘图数据模块\n"""\n', 'canal_delights.content.foods.prototype': '"""\n五城二十味矢量绘图数据\n"""\n\nfrom ...config import rgb, make_style, linear_gradient, radial_gradient\n\n\n# 通用盘子\ndef plate_drawing(cx, cy, r):\n    return [\n        # Layered ceramic plate: shadow, warm rim, inner well and highlight.\n        [\'E\', [cx, cy - 0.025, r * 1.22, r * 0.32], {\'fill\': rgb(177, 166, 151)}],\n        [\'C\', [cx, cy, r * 1.04], {\'fill\': rgb(226, 220, 204), \'stroke\': rgb(177, 153, 119), \'stroke_width\': 1}],\n        [\'C\', [cx, cy, r], {\'fill\': rgb(248, 245, 232), \'stroke\': rgb(196, 186, 166), \'stroke_width\': 2}],\n        [\'C\', [cx, cy + 0.005, r * 0.88], {\'stroke\': rgb(218, 205, 179), \'stroke_width\': 1}],\n        [\'E\', [cx - r * .32, cy + r * .28, r * .18, r * .055], {\'fill\': rgb(255, 252, 241)}],\n    ]\n\n\n# 北京烤鸭\nROAST_DUCK = [\n    *plate_drawing(0.5, 0.45, 0.18),\n    # 鸭身\n    [\'E\', [0.5, 0.45, 0.15, 0.1], {\'fill\': rgb(139, 69, 19)}],\n    [\'E\', [0.5, 0.47, 0.13, 0.08], {\'fill\': rgb(160, 82, 45)}],\n    # 高光\n    [\'E\', [0.45, 0.48, 0.04, 0.02], {\'fill\': rgb(205, 133, 63)}],\n    # 切片线条\n    [\'L\', [[0.42, 0.42], [0.42, 0.52]], {\'stroke\': rgb(100, 50, 20), \'stroke_width\': 1}],\n    [\'L\', [[0.47, 0.41], [0.47, 0.53]], {\'stroke\': rgb(100, 50, 20), \'stroke_width\': 1}],\n    [\'L\', [[0.52, 0.41], [0.52, 0.53]], {\'stroke\': rgb(100, 50, 20), \'stroke_width\': 1}],\n    [\'L\', [[0.57, 0.42], [0.57, 0.52]], {\'stroke\': rgb(100, 50, 20), \'stroke_width\': 1}],\n]\n\n\n# 月饼\nMOONCAKE = [\n    *plate_drawing(0.5, 0.45, 0.15),\n    # 月饼主体\n    [\'C\', [0.5, 0.45, 0.1], {\'fill\': rgb(218, 165, 32)}],\n    [\'C\', [0.5, 0.45, 0.09], {\'fill\': rgb(205, 133, 0)}],\n    # 花纹\n    [\'RG\', [0.5, 0.45, 0.06, 0.08], {\'stroke\': rgb(184, 134, 11), \'stroke_width\': 1}],\n    [\'C\', [0.5, 0.45, 0.04], {\'fill\': rgb(255, 215, 0)}],\n]\n\n\n# 包子\nBAOZI = [\n    *plate_drawing(0.5, 0.45, 0.15),\n    # 包子主体\n    [\'C\', [0.5, 0.45, 0.1], {\'fill\': rgb(255, 250, 240)}],\n    # 褶子\n    [\'A\', [0.5, 0.45, 0.08, 0, 360], {\'stroke\': rgb(220, 210, 200), \'stroke_width\': 1}],\n    # 顶部\n    [\'C\', [0.5, 0.48, 0.02], {\'fill\': rgb(240, 230, 220)}],\n    # 蒸汽\n    [\'A\', [0.45, 0.55, 0.02, 0, 180], {\'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n    [\'A\', [0.5, 0.57, 0.02, 0, 180], {\'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n    [\'A\', [0.55, 0.55, 0.02, 0, 180], {\'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n]\n\n\n# 麻花\nMAHUA = [\n    *plate_drawing(0.5, 0.45, 0.18),\n    # 麻花主体 - 交叉的条\n    [\'B\', [[0.35, 0.4], [0.45, 0.5], [0.55, 0.4], [0.65, 0.5]], {\'stroke\': rgb(205, 133, 0), \'stroke_width\': 8}],\n    [\'B\', [[0.35, 0.5], [0.45, 0.4], [0.55, 0.5], [0.65, 0.4]], {\'stroke\': rgb(184, 134, 11), \'stroke_width\': 8}],\n    # 芝麻点\n    [\'P\', [0.4, 0.45, 2], {\'fill\': rgb(255, 255, 200)}],\n    [\'P\', [0.5, 0.43, 2], {\'fill\': rgb(255, 255, 200)}],\n    [\'P\', [0.6, 0.47, 2], {\'fill\': rgb(255, 255, 200)}],\n]\n\n\n# 狮子头\nLION_HEAD = [\n    *plate_drawing(0.5, 0.45, 0.18),\n    # 汤汁\n    [\'E\', [0.5, 0.45, 0.15, 0.1], {\'fill\': rgb(255, 245, 220)}],\n    # 狮子头\n    [\'C\', [0.5, 0.45, 0.08], {\'fill\': rgb(160, 82, 45)}],\n    [\'C\', [0.5, 0.45, 0.07], {\'fill\': rgb(139, 69, 19)}],\n    # 纹理\n    [\'P\', [0.47, 0.43, 2], {\'fill\': rgb(100, 50, 20)}],\n    [\'P\', [0.52, 0.46, 2], {\'fill\': rgb(100, 50, 20)}],\n    [\'P\', [0.48, 0.48, 2], {\'fill\': rgb(100, 50, 20)}],\n    # 青菜\n    [\'E\', [0.38, 0.45, 0.03, 0.02], {\'fill\': rgb(34, 139, 34)}],\n    [\'E\', [0.62, 0.45, 0.03, 0.02], {\'fill\': rgb(34, 139, 34)}],\n]\n\n\n# 汤包\nSOUP_DUMPLING = [\n    *plate_drawing(0.5, 0.45, 0.15),\n    # 汤包主体\n    [\'C\', [0.5, 0.45, 0.08], {\'fill\': rgb(255, 250, 240)}],\n    # 褶子顶部\n    [\'A\', [0.5, 0.45, 0.06, 0, 360], {\'stroke\': rgb(220, 210, 200), \'stroke_width\': 1}],\n    [\'C\', [0.5, 0.47, 0.015], {\'fill\': rgb(200, 180, 160)}],\n    # 醋碟\n    [\'C\', [0.65, 0.5, 0.04], {\'fill\': rgb(240, 240, 240), \'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n    [\'C\', [0.65, 0.5, 0.03], {\'fill\': rgb(139, 69, 19)}],\n]\n\n\n# 桂花糕\nOSMANTHUS_CAKE = [\n    *plate_drawing(0.5, 0.45, 0.18),\n    # 糕体\n    [\'R\', [0.4, 0.4, 0.2, 0.1], {\'fill\': rgb(255, 245, 220)}],\n    [\'R\', [0.41, 0.41, 0.18, 0.08], {\'fill\': rgb(255, 235, 205)}],\n    # 桂花点缀\n    [\'P\', [0.43, 0.43, 3], {\'fill\': rgb(255, 165, 0)}],\n    [\'P\', [0.48, 0.45, 3], {\'fill\': rgb(255, 140, 0)}],\n    [\'P\', [0.53, 0.42, 3], {\'fill\': rgb(255, 165, 0)}],\n    [\'P\', [0.57, 0.46, 3], {\'fill\': rgb(255, 140, 0)}],\n]\n\n\n# 松鼠桂鱼\nSQUIRREL_FISH = [\n    *plate_drawing(0.5, 0.45, 0.2),\n    # 鱼身\n    [\'E\', [0.5, 0.45, 0.15, 0.08], {\'fill\': rgb(205, 133, 0)}],\n    # 菱形刀花\n    [\'L\', [[0.4, 0.42], [0.6, 0.42]], {\'stroke\': rgb(184, 134, 11), \'stroke_width\': 1}],\n    [\'L\', [[0.4, 0.45], [0.6, 0.45]], {\'stroke\': rgb(184, 134, 11), \'stroke_width\': 1}],\n    [\'L\', [[0.4, 0.48], [0.6, 0.48]], {\'stroke\': rgb(184, 134, 11), \'stroke_width\': 1}],\n    # 酱汁\n    [\'E\', [0.5, 0.45, 0.12, 0.06], {\'fill\': rgb(220, 20, 60)}],\n    # 松仁\n    [\'P\', [0.45, 0.5, 2], {\'fill\': rgb(255, 228, 196)}],\n    [\'P\', [0.5, 0.51, 2], {\'fill\': rgb(255, 228, 196)}],\n    [\'P\', [0.55, 0.5, 2], {\'fill\': rgb(255, 228, 196)}],\n]\n\n\n# 龙井茶\nLONGJING_TEA = [\n    *plate_drawing(0.5, 0.45, 0.12),\n    # 茶杯\n    [\'R\', [0.42, 0.4, 0.16, 0.12], {\'fill\': rgb(240, 240, 240), \'stroke\': rgb(200, 200, 200), \'stroke_width\': 2}],\n    # 茶水\n    [\'R\', [0.44, 0.42, 0.12, 0.08], {\'fill\': rgb(144, 238, 144)}],\n    # 茶叶\n    [\'L\', [[0.47, 0.44], [0.47, 0.48]], {\'stroke\': rgb(34, 139, 34), \'stroke_width\': 1}],\n    [\'L\', [[0.5, 0.43], [0.5, 0.47]], {\'stroke\': rgb(34, 139, 34), \'stroke_width\': 1}],\n    [\'L\', [[0.53, 0.45], [0.53, 0.49]], {\'stroke\': rgb(34, 139, 34), \'stroke_width\': 1}],\n    # 茶汽\n    [\'A\', [0.47, 0.52, 0.02, 0, 180], {\'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n    [\'A\', [0.53, 0.53, 0.02, 0, 180], {\'stroke\': rgb(200, 200, 200), \'stroke_width\': 1}],\n]\n\n\n# 西湖醋鱼\nWEST_LAKE_FISH = [\n    *plate_drawing(0.5, 0.45, 0.2),\n    # 鱼身\n    [\'E\', [0.5, 0.45, 0.15, 0.07], {\'fill\': rgb(160, 82, 45)}],\n    # 鱼尾\n    [\'G\', [[0.65, 0.45], [0.7, 0.42], [0.7, 0.48]], {\'fill\': rgb(139, 69, 19)}],\n    # 酱汁\n    [\'E\', [0.5, 0.45, 0.12, 0.05], {\'fill\': rgb(139, 0, 0)}],\n    # 姜丝\n    [\'L\', [[0.45, 0.44], [0.48, 0.44]], {\'stroke\': rgb(255, 255, 0), \'stroke_width\': 1}],\n    [\'L\', [[0.5, 0.46], [0.53, 0.46]], {\'stroke\': rgb(255, 255, 0), \'stroke_width\': 1}],\n    # 葱丝\n    [\'L\', [[0.47, 0.47], [0.5, 0.47]], {\'stroke\': rgb(0, 255, 0), \'stroke_width\': 1}],\n]\n\n\n# 二期新增菜品共用一套克制的矢量餐具语言，但保留各自轮廓与配色。\nNOODLE_BOWL = [\n    *plate_drawing(0.5, 0.40, 0.18),\n    [\'G\', [[.34,.48],[.66,.48],[.60,.34],[.40,.34]],\n     {\'fill\': rgb(238, 231, 208), \'stroke\': rgb(120, 91, 61), \'stroke_width\': 2}],\n    [\'E\', [.50,.48,.16,.045], {\'fill\': rgb(132, 75, 34)}],\n    [\'B\', [[.39,.49],[.45,.45],[.54,.52],[.62,.47]], {\'stroke\': rgb(238, 195, 92), \'stroke_width\': 3}],\n    [\'L\', [[.42,.54],[.64,.62]], {\'stroke\': rgb(103, 65, 39), \'stroke_width\': 2}],\n]\n\nHOTPOT = [\n    *plate_drawing(0.5, 0.40, 0.19),\n    [\'E\', [.50,.45,.17,.10], {\'fill\': rgb(151, 65, 42), \'stroke\': rgb(91, 50, 36), \'stroke_width\': 2}],\n    [\'E\', [.50,.48,.145,.066], {\'fill\': rgb(213, 114, 62)}],\n    [\'R\', [.47,.47,.06,.13], {\'fill\': rgb(176, 147, 92), \'stroke\': rgb(93, 67, 45), \'stroke_width\': 1}],\n    [\'B\', [[.41,.55],[.39,.59],[.42,.63],[.40,.67]], {\'stroke\': rgb(204, 199, 182), \'stroke_width\': 2}],\n    [\'B\', [[.58,.55],[.56,.59],[.59,.63],[.57,.67]], {\'stroke\': rgb(204, 199, 182), \'stroke_width\': 2}],\n]\n\nSTEW_BOWL = [\n    *plate_drawing(0.5, 0.40, 0.18),\n    [\'G\', [[.34,.48],[.66,.48],[.60,.34],[.40,.34]], {\'fill\': rgb(225, 211, 181), \'stroke\': rgb(112, 77, 49), \'stroke_width\': 2}],\n    [\'E\', [.50,.48,.16,.05], {\'fill\': rgb(105, 59, 34)}],\n    [\'C\', [.44,.49,.035], {\'fill\': rgb(170, 101, 55)}],\n    [\'C\', [.53,.47,.040], {\'fill\': rgb(189, 125, 64)}],\n    [\'R\', [.56,.47,.055,.025], {\'fill\': rgb(218, 187, 124)}],\n]\n\nJIANBING = [\n    *plate_drawing(0.5, 0.43, 0.19),\n    [\'G\', [[.34,.39],[.61,.35],[.67,.50],[.40,.55]], {\'fill\': rgb(222, 166, 61), \'stroke\': rgb(133, 81, 33), \'stroke_width\': 2}],\n    [\'G\', [[.43,.39],[.60,.37],[.64,.47],[.47,.50]], {\'fill\': rgb(235, 205, 109)}],\n    [\'L\', [[.37,.47],[.64,.42]], {\'stroke\': rgb(132, 52, 32), \'stroke_width\': 2}],\n    [\'L\', [[.45,.52],[.57,.38]], {\'stroke\': rgb(65, 126, 69), \'stroke_width\': 2}],\n]\n\nTOFU_SILK = [\n    *plate_drawing(0.5, 0.41, 0.18),\n    [\'E\', [.50,.45,.16,.095], {\'fill\': rgb(229, 199, 121), \'stroke\': rgb(126, 89, 49), \'stroke_width\': 2}],\n    *[[\'L\', [[x,.40],[x+.035,.51]], {\'stroke\': rgb(250, 239, 194), \'stroke_width\': 2}]\n      for x in (.39,.43,.47,.51,.55,.59)],\n    [\'E\', [.45,.50,.025,.012], {\'fill\': rgb(197, 80, 47)}],\n    [\'E\', [.57,.43,.028,.012], {\'fill\': rgb(72, 135, 71)}],\n]\n\nFRIED_RICE = [\n    *plate_drawing(0.5, 0.42, 0.18),\n    [\'E\', [.50,.45,.145,.09], {\'fill\': rgb(239, 190, 73)}],\n    *[[\'C\', [x,y,.012], {\'fill\': color}] for x, y, color in (\n        (.43,.46,rgb(91,145,74)), (.48,.50,rgb(213,91,54)),\n        (.54,.44,rgb(242,221,132)), (.59,.49,rgb(91,145,74)),\n        (.49,.41,rgb(213,91,54)),\n    )],\n]\n\nEEL_PASTE = [\n    *plate_drawing(0.5, 0.42, 0.18),\n    [\'E\', [.50,.45,.15,.085], {\'fill\': rgb(97, 50, 31)}],\n    [\'B\', [[.39,.44],[.45,.53],[.53,.37],[.62,.48]], {\'stroke\': rgb(185, 103, 47), \'stroke_width\': 6}],\n    [\'L\', [[.47,.55],[.54,.37]], {\'stroke\': rgb(244, 224, 154), \'stroke_width\': 2}],\n]\n\nRICE_CAKE = [\n    *plate_drawing(0.5, 0.42, 0.18),\n    [\'R\', [.38,.39,.11,.10], {\'fill\': rgb(244, 226, 210), \'stroke\': rgb(185, 133, 95), \'stroke_width\': 1}],\n    [\'R\', [.51,.42,.11,.10], {\'fill\': rgb(225, 206, 173), \'stroke\': rgb(185, 133, 95), \'stroke_width\': 1}],\n    [\'C\', [.43,.45,.018], {\'fill\': rgb(196, 78, 70)}],\n    [\'C\', [.56,.48,.018], {\'fill\': rgb(107, 145, 76)}],\n]\n\nDONGPO_PORK = [\n    *plate_drawing(0.5, 0.42, 0.18),\n    [\'R\', [.39,.36,.22,.16], {\'fill\': rgb(126, 48, 31), \'stroke\': rgb(83, 42, 30), \'stroke_width\': 2}],\n    [\'R\', [.40,.44,.20,.065], {\'fill\': rgb(188, 75, 43)}],\n    [\'R\', [.40,.405,.20,.035], {\'fill\': rgb(229, 157, 94)}],\n    [\'E\', [.46,.49,.045,.015], {\'fill\': rgb(236, 174, 111)}],\n]\n\nLONGJING_SHRIMP = [\n    *plate_drawing(0.5, 0.42, 0.19),\n    *[[\'A\', [x,y,.035,20,300], {\'stroke\': rgb(239, 167, 153), \'stroke_width\': 5}]\n      for x, y in ((.40,.43),(.47,.49),(.54,.42),(.60,.48))],\n    [\'L\', [[.42,.51],[.45,.55]], {\'stroke\': rgb(62, 132, 67), \'stroke_width\': 2}],\n    [\'L\', [[.55,.51],[.58,.56]], {\'stroke\': rgb(62, 132, 67), \'stroke_width\': 2}],\n]\n\n\n# 食物绘图数据映射\nFOOD_DRAWINGS = {\n    \'beijing_roast_duck\': ROAST_DUCK,\n    \'beijing_mutton_hotpot\': HOTPOT,\n    \'beijing_zhajiang_noodles\': NOODLE_BOWL,\n    \'beijing_luzhu\': STEW_BOWL,\n    \'tianjin_jianbing\': JIANBING,\n    \'tianjin_baozi\': BAOZI,\n    \'tianjin_mahua\': MAHUA,\n    \'tianjin_guobacai\': STEW_BOWL,\n    \'yangzhou_lion_head\': LION_HEAD,\n    \'yangzhou_boiled_shredded_tofu\': TOFU_SILK,\n    \'yangzhou_soup_dumpling\': SOUP_DUMPLING,\n    \'yangzhou_fried_rice\': FRIED_RICE,\n    \'suzhou_squirrel_fish\': SQUIRREL_FISH,\n    \'suzhou_suzhou_noodles\': NOODLE_BOWL,\n    \'suzhou_eel_paste\': EEL_PASTE,\n    \'suzhou_rice_cake\': RICE_CAKE,\n    \'hangzhou_west_lake_fish\': WEST_LAKE_FISH,\n    \'hangzhou_dongpo_pork\': DONGPO_PORK,\n    \'hangzhou_longjing_shrimp\': LONGJING_SHRIMP,\n    \'hangzhou_pianerchuan\': NOODLE_BOWL,\n}\n\n\ndef get_food_drawing(city_id: str, food_id: str) -> list:\n    """获取食物的绘图数据"""\n    key = f"{city_id}_{food_id}"\n    return FOOD_DRAWINGS.get(key, [])\n', 'canal_delights.content.scenes': '"""Distinct city silhouettes used behind discoverable food markers."""\n\nimport math\n\nfrom ..config import linear_gradient, rgb\n\n\nFOOD_POSITIONS = {\n    \'beijing\': ((.18, .34), (.39, .47), (.61, .36), (.80, .51)),\n    \'tianjin\': ((.18, .50), (.39, .35), (.61, .49), (.80, .34)),\n    \'yangzhou\': ((.18, .35), (.39, .52), (.61, .35), (.80, .54)),\n    \'suzhou\': ((.18, .52), (.39, .35), (.61, .53), (.80, .35)),\n    \'hangzhou\': ((.18, .37), (.39, .52), (.61, .36), (.80, .53)),\n}\n\n\ndef _water(phase: float) -> list:\n    shimmer = .004 * math.sin(phase * 1.8)\n    data = [\n        [\'R\', [.065, .205, .87, .17], {\'fill\': rgb(174, 207, 204)}],\n        [\'B\', [[.08, .31 + shimmer], [.31, .34 - shimmer], [.63, .28 + shimmer], [.92, .32]],\n         {\'stroke\': rgb(222, 236, 225), \'stroke_width\': 2}],\n        [\'B\', [[.12, .25 - shimmer], [.36, .28 + shimmer], [.67, .23], [.88, .27 + shimmer]],\n         {\'stroke\': rgb(131, 177, 180), \'stroke_width\': 2}],\n    ]\n    return data\n\n\ndef _atmosphere(city_id: str, phase: float) -> list:\n    """Low-contrast depth layers shared by every city vignette."""\n    haze = .0025 * math.sin(phase * .7)\n    palettes = {\n        \'beijing\': (rgb(177, 153, 135), rgb(126, 101, 91)),\n        \'tianjin\': (rgb(166, 178, 180), rgb(102, 122, 130)),\n        \'yangzhou\': (rgb(179, 177, 143), rgb(112, 130, 104)),\n        \'suzhou\': (rgb(168, 181, 171), rgb(91, 113, 108)),\n        \'hangzhou\': (rgb(174, 188, 157), rgb(95, 128, 103)),\n    }\n    far, near = palettes[city_id]\n    data = [\n        [\'B\', [[.07,.39+haze],[.20,.33],[.34,.385],[.48,.31],[.63,.37],[.79,.30],[.93,.36]],\n         {\'stroke\': far, \'stroke_width\': 18}],\n        [\'R\', [.09,.345,.82,.028], {\'fill\': near}],\n        [\'R\', [.10,.355,.80,.012], {\'fill\': rgb(205, 203, 177)}],\n    ]\n    # A few quiet window lights give the skyline scale without competing with\n    # the food markers in the foreground.\n    for x, y in ((.16,.365),(.23,.35),(.31,.37),(.72,.35),(.80,.365),(.87,.345)):\n        data.append([\'R\', [x, y, .014, .010], {\'fill\': rgb(224, 189, 111)}])\n    return data\n\n\ndef _beijing(theme, phase):\n    roof = rgb(137, 48, 39)\n    gold = rgb(202, 159, 62)\n    data = [\n        [\'R\', [.18, .35, .64, .16], {\'fill\': rgb(174, 72, 54), \'stroke\': rgb(105, 52, 39), \'stroke_width\': 2}],\n        [\'R\', [.25, .51, .50, .11], {\'fill\': rgb(190, 79, 54), \'stroke\': rgb(105, 52, 39), \'stroke_width\': 2}],\n        [\'G\', [[.20,.51],[.80,.51],[.73,.59],[.27,.59]], {\'fill\': roof, \'stroke\': gold, \'stroke_width\': 2}],\n        [\'G\', [[.27,.62],[.73,.62],[.67,.69],[.33,.69]], {\'fill\': roof, \'stroke\': gold, \'stroke_width\': 2}],\n        [\'R\', [.45,.35,.10,.18], {\'fill\': rgb(76, 49, 37)}],\n        [\'C\', [.50,.61,.018], {\'fill\': gold}],\n    ]\n    for x in (.29, .38, .62, .71):\n        data.extend([\n            [\'R\', [x, .37, .035, .115], {\'fill\': rgb(113, 50, 39)}],\n            [\'C\', [x + .0175, .465, .010], {\'fill\': gold}],\n        ])\n    data.extend([\n        [\'L\', [[.18,.535],[.82,.535]], {\'stroke\': gold, \'stroke_width\': 2}],\n        [\'L\', [[.25,.645],[.75,.645]], {\'stroke\': gold, \'stroke_width\': 2}],\n        [\'C\', [.35,.545,.009], {\'fill\': rgb(232, 181, 72)}],\n        [\'C\', [.65,.545,.009], {\'fill\': rgb(232, 181, 72)}],\n    ])\n    return data\n\n\ndef _tianjin(theme, phase):\n    steel = rgb(69, 91, 103)\n    spokes = []\n    for index in range(12):\n        angle = math.tau * index / 12 + phase * .08\n        spokes.append([\'L\', [[.70,.53],[.70 + .105*math.cos(angle), .53 + .105*math.sin(angle)]],\n                       {\'stroke\': rgb(116, 139, 145), \'stroke_width\': 1}])\n    cabins = []\n    for index in range(8):\n        angle = math.tau * index / 8 + phase * .08\n        cabins.append([\'C\', [.70 + .105*math.cos(angle), .53 + .105*math.sin(angle), .009],\n                       {\'fill\': rgb(225, 196, 132), \'stroke\': steel, \'stroke_width\': 1}])\n    return [\n        [\'A\', [.70,.53,.11,0,360], {\'stroke\': steel, \'stroke_width\': 4}],\n        *spokes,\n        *cabins,\n        [\'L\', [[.59,.36],[.70,.53],[.81,.36]], {\'stroke\': steel, \'stroke_width\': 4}],\n        [\'B\', [[.10,.39],[.30,.50],[.48,.34],[.61,.42]], {\'stroke\': rgb(94, 78, 65), \'stroke_width\': 7}],\n        [\'L\', [[.14,.39],[.58,.42]], {\'stroke\': rgb(211, 169, 93), \'stroke_width\': 2}],\n        [\'L\', [[.18,.405],[.19,.46]], {\'stroke\': steel, \'stroke_width\': 2}],\n        [\'L\', [[.28,.412],[.29,.47]], {\'stroke\': steel, \'stroke_width\': 2}],\n        [\'L\', [[.39,.416],[.40,.46]], {\'stroke\': steel, \'stroke_width\': 2}],\n        [\'L\', [[.50,.419],[.51,.455]], {\'stroke\': steel, \'stroke_width\': 2}],\n    ]\n\n\ndef _yangzhou(theme, phase):\n    willow = rgb(74, 125, 80)\n    sway = .006 * math.sin(phase * 1.2)\n    return [\n        [\'R\', [.58,.38,.19,.12], {\'fill\': rgb(203, 184, 146), \'stroke\': rgb(83, 71, 55), \'stroke_width\': 2}],\n        [\'G\', [[.54,.50],[.81,.50],[.73,.58],[.62,.58]], {\'fill\': rgb(60, 87, 77), \'stroke\': rgb(184, 134, 65), \'stroke_width\': 2}],\n        [\'L\', [[.675,.58],[.675,.67]], {\'stroke\': rgb(80, 59, 40), \'stroke_width\': 3}],\n        [\'G\', [[.62,.67],[.73,.67],[.69,.72],[.65,.72]], {\'fill\': rgb(60, 87, 77)}],\n        [\'B\', [[.12,.37],[.25,.56],[.39,.56],[.53,.37]], {\'stroke\': rgb(210, 203, 178), \'stroke_width\': 13}],\n        [\'B\', [[.13,.37],[.25,.52],[.39,.52],[.52,.37]], {\'stroke\': rgb(93, 85, 69), \'stroke_width\': 2}],\n        [\'L\', [[.19,.72],[.18,.42]], {\'stroke\': rgb(87, 72, 48), \'stroke_width\': 5}],\n        [\'B\', [[.19,.67],[.12,.60],[.16,.50],[.10,.42]], {\'stroke\': willow, \'stroke_width\': 3}],\n        [\'B\', [[.20,.64],[.28,.58],[.23,.48],[.29,.40]], {\'stroke\': willow, \'stroke_width\': 3}],\n        [\'R\', [.61,.395,.025,.095], {\'fill\': rgb(95, 70, 48)}],\n        [\'R\', [.72,.395,.025,.095], {\'fill\': rgb(95, 70, 48)}],\n        [\'L\', [[.59,.455],[.76,.455]], {\'stroke\': rgb(222, 190, 122), \'stroke_width\': 2}],\n        [\'E\', [.115+sway,.535,.016,.007], {\'fill\': rgb(101, 151, 91)}],\n        [\'E\', [.275+sway,.505,.018,.008], {\'fill\': rgb(101, 151, 91)}],\n        [\'E\', [.135-sway,.455,.014,.006], {\'fill\': rgb(126, 166, 98)}],\n        [\'L\', [[.17,.395],[.46,.395]], {\'stroke\': rgb(151, 139, 112), \'stroke_width\': 2}],\n    ]\n\n\ndef _suzhou(theme, phase):\n    ink = rgb(61, 66, 65)\n    return [\n        [\'R\', [.12,.36,.72,.20], {\'fill\': rgb(239, 236, 218), \'stroke\': ink, \'stroke_width\': 2}],\n        [\'G\', [[.10,.56],[.39,.56],[.34,.62],[.16,.62]], {\'fill\': ink}],\n        [\'G\', [[.38,.56],[.86,.56],[.78,.64],[.48,.64]], {\'fill\': ink}],\n        [\'C\', [.31,.43,.055], {\'fill\': ink}],\n        [\'R\', [.255,.36,.11,.08], {\'fill\': ink}],\n        [\'B\', [[.48,.36],[.59,.55],[.72,.55],[.84,.36]], {\'stroke\': rgb(223, 218, 196), \'stroke_width\': 17}],\n        [\'B\', [[.48,.36],[.59,.52],[.72,.52],[.84,.36]], {\'stroke\': ink, \'stroke_width\': 2}],\n        [\'L\', [[.18,.48],[.25,.48]], {\'stroke\': rgb(142, 73, 53), \'stroke_width\': 3}],\n        [\'R\', [.16,.405,.065,.085], {\'fill\': rgb(90, 105, 101), \'stroke\': ink, \'stroke_width\': 1}],\n        [\'L\', [[.192,.405],[.192,.49]], {\'stroke\': rgb(226, 217, 190), \'stroke_width\': 1}],\n        [\'L\', [[.16,.447],[.225,.447]], {\'stroke\': rgb(226, 217, 190), \'stroke_width\': 1}],\n        [\'C\', [.66,.445,.035], {\'fill\': ink}],\n        [\'R\', [.625,.36,.07,.085], {\'fill\': ink}],\n        [\'B\', [[.09,.29],[.30,.305],[.52,.275],[.91,.30]], {\'stroke\': rgb(224, 237, 228), \'stroke_width\': 2}],\n    ]\n\n\ndef _hangzhou(theme, phase):\n    hill = rgb(93, 132, 94)\n    return [\n        [\'B\', [[.08,.39],[.22,.64],[.38,.48],[.53,.61]], {\'stroke\': rgb(140, 163, 121), \'stroke_width\': 36}],\n        [\'B\', [[.42,.42],[.58,.65],[.74,.49],[.92,.59]], {\'stroke\': hill, \'stroke_width\': 40}],\n        [\'R\', [.64,.38,.10,.22], {\'fill\': rgb(196, 170, 112), \'stroke\': rgb(85, 67, 49), \'stroke_width\': 2}],\n        [\'G\', [[.61,.60],[.77,.60],[.73,.65],[.65,.65]], {\'fill\': rgb(103, 74, 50)}],\n        [\'G\', [[.62,.53],[.76,.53],[.73,.58],[.65,.58]], {\'fill\': rgb(103, 74, 50)}],\n        [\'G\', [[.63,.46],[.75,.46],[.72,.51],[.66,.51]], {\'fill\': rgb(103, 74, 50)}],\n        [\'C\', [.18,.62,.034], {\'fill\': rgb(231, 188, 101)}],\n        [\'L\', [[.65,.49],[.73,.49]], {\'stroke\': rgb(226, 203, 151), \'stroke_width\': 2}],\n        [\'L\', [[.65,.56],[.73,.56]], {\'stroke\': rgb(226, 203, 151), \'stroke_width\': 2}],\n        [\'R\', [.68,.40,.022,.035], {\'fill\': rgb(74, 58, 45)}],\n        [\'G\', [[.22,.31],[.28,.34],[.34,.31]], {\'fill\': rgb(111, 70, 42)}],\n        [\'L\', [[.28,.34],[.28,.39]], {\'stroke\': rgb(83, 59, 40), \'stroke_width\': 2}],\n        [\'G\', [[.28,.39],[.32,.37],[.28,.35]], {\'fill\': rgb(214, 177, 101)}],\n        [\'B\', [[.11,.235],[.29,.26],[.48,.225],[.62,.25]], {\'stroke\': rgb(218, 236, 226), \'stroke_width\': 2}],\n    ]\n\n\nSCENE_BUILDERS = {\n    \'beijing\': _beijing,\n    \'tianjin\': _tianjin,\n    \'yangzhou\': _yangzhou,\n    \'suzhou\': _suzhou,\n    \'hangzhou\': _hangzhou,\n}\n\n\ndef get_city_scene(city_id: str, theme, phase: float, gradient_steps: int = 12) -> list:\n    data = [\n        [\'E\', [.50,.195,.445,.032], {\'fill\': rgb(205, 191, 160)}],\n        [\'RR\', [.06,.20,.88,.59,.030], {\'fill\': rgb(235, 226, 200), \'stroke\': theme, \'stroke_width\': 2}],\n        [\'R\', [.065,.375,.87,.41], {\'gradient\': linear_gradient([\n            [rgb(224, 232, 218), 0.0], [rgb(244, 225, 191), .62], [rgb(234, 210, 174), 1.0],\n        ], angle=90, steps=gradient_steps)}],\n        [\'C\', [.84,.69,.045], {\'fill\': rgb(232, 192, 113)}],\n        [\'B\', [[.10,.68],[.19,.73],[.25,.65],[.34,.69]], {\'stroke\': rgb(207, 207, 185), \'stroke_width\': 5}],\n        [\'B\', [[.68,.73],[.75,.77],[.82,.70],[.90,.74]], {\'stroke\': rgb(215, 209, 185), \'stroke_width\': 4}],\n    ]\n    data.extend(_atmosphere(city_id, phase))\n    data.extend(_water(phase))\n    data.extend(SCENE_BUILDERS[city_id](theme, phase))\n    # Foreground reeds and ripple strokes add a final depth plane.\n    sway = .008 * math.sin(phase * 1.5)\n    data.extend([\n        [\'B\', [[.085,.21],[.080+sway,.29],[.095+sway,.34],[.090,.39]], {\'stroke\': rgb(85, 126, 81), \'stroke_width\': 3}],\n        [\'B\', [[.915,.21],[.920-sway,.28],[.905-sway,.34],[.910,.40]], {\'stroke\': rgb(85, 126, 81), \'stroke_width\': 3}],\n        [\'E\', [.11,.225,.050,.008], {\'stroke\': rgb(114, 161, 158), \'stroke_width\': 1}],\n        [\'E\', [.87,.255,.060,.009], {\'stroke\': rgb(114, 161, 158), \'stroke_width\': 1}],\n    ])\n    return data\n', 'canal_delights.core.__init__': '"""\n核心模块 - 绘图引擎、解析器、几何、样式\n"""\n', 'canal_delights.core.accelerated': '"""Accelerated renderer using Turtle\'s own Tk canvas as a batch backend.\n\nThe application still owns a ``turtle.Screen`` and uses Turtle for window,\nevents and lifecycle.  Unlike the pure backend, a sampled curve or filled\nshape is submitted as one retained Canvas item instead of many pen movements.\n"""\n\nimport math\nfrom typing import List, Tuple\n\nfrom .engine import DrawingEngine\nfrom .styles import RGB, rgb_to_hex\n\n\nPoint = Tuple[float, float]\n\n\nclass AcceleratedDrawingEngine(DrawingEngine):\n    """Drop-in ``DrawingEngine`` with batched Canvas drawing operations."""\n\n    def __init__(self, width: int = 1200, height: int = 800):\n        super().__init__(width, height)\n        self.supports_acceleration = True\n        self.acceleration_enabled = True\n        self.mode_name = \'accelerated\'\n        self._canvas_items_by_layer = {\'content\': []}\n        self.screen.title("运河风物志 Canal Delights（加速模式）")\n\n    @property\n    def _canvas_items(self) -> List[int]:\n        """Items in the active layer (kept for diagnostics and tests)."""\n        return self._canvas_items_by_layer.setdefault(self._active_layer, [])\n\n    def _remember(self, item: int) -> int:\n        self._canvas_items.append(item)\n        return item\n\n    def set_acceleration(self, enabled: bool):\n        """Switch between batch Canvas and genuine Turtle drawing in-place."""\n        enabled = bool(enabled)\n        if enabled == self.acceleration_enabled:\n            return\n        self.clear()\n        self.acceleration_enabled = enabled\n        self.mode_name = \'accelerated\' if enabled else \'pure\'\n        suffix = \'加速模式\' if enabled else \'纯 Turtle 模式\'\n        self.screen.title(f"运河风物志 Canal Delights（{suffix}）")\n\n    def clear(self, layer=None):\n        """Delete retained accelerated items in one layer or in all layers."""\n        names = [layer] if layer is not None else list(self._canvas_items_by_layer)\n        for name in names:\n            for item in self._canvas_items_by_layer.get(name, []):\n                self.screen._delete(item)\n            self._canvas_items_by_layer.setdefault(name, []).clear()\n        super().clear(layer)\n\n    def draw_point(self, x: float, y: float, size: float, color: RGB):\n        if not self.acceleration_enabled:\n            return super().draw_point(x, y, size, color)\n        # Use a compact polygon rather than a Turtle dot operation.  At normal\n        # UI sizes 16 sides are visually indistinguishable from an oval.\n        radius = max(0.5, size / 2)\n        points = [\n            (x + radius * math.cos(i * math.tau / 16),\n             y + radius * math.sin(i * math.tau / 16))\n            for i in range(16)\n        ]\n        self._fill_polygon(points, color)\n\n    def draw_line(\n        self, x1: float, y1: float, x2: float, y2: float,\n        color: RGB, width: float = 1.0,\n    ):\n        if not self.acceleration_enabled:\n            return super().draw_line(x1, y1, x2, y2, color, width)\n        self.draw_polyline([(x1, y1), (x2, y2)], color, width)\n\n    def draw_polyline(\n        self, points: List[Point], color: RGB,\n        width: float = 1.0, close: bool = False,\n    ):\n        if not self.acceleration_enabled:\n            return super().draw_polyline(points, color, width, close)\n        if not points:\n            return\n        coords = list(points)\n        if close and len(coords) > 2 and coords[-1] != coords[0]:\n            coords.append(coords[0])\n        item = self.screen._createline()\n        self.screen._drawline(\n            item, coords, fill=rgb_to_hex(color), width=max(1, width), top=True,\n        )\n        self._remember(item)\n\n    def _fill_polygon(self, points: List[Point], color: RGB):\n        if not self.acceleration_enabled:\n            return super()._fill_polygon(points, color)\n        if not points:\n            return\n        item = self.screen._createpoly()\n        hex_color = rgb_to_hex(color)\n        self.screen._drawpoly(\n            item, points, fill=hex_color, outline=hex_color, width=1, top=True,\n        )\n        self._remember(item)\n\n    def draw_text(\n        self, text: str, x: float, y: float, font_size: int, color: RGB,\n        font_family: str = \'Microsoft YaHei\', align: str = \'center\',\n        weight: str = \'normal\',\n    ):\n        if not self.acceleration_enabled:\n            return super().draw_text(\n                text, x, y, font_size, color, font_family, align, weight,\n            )\n        turtle_align = align if align in {\'left\', \'center\', \'right\'} else \'center\'\n        item, _ = self.screen._write(\n            (x, y), text, turtle_align,\n            (font_family, font_size, weight), rgb_to_hex(color),\n        )\n        self._remember(item)\n', 'canal_delights.core.animation': '"""Small backend-independent animation clock and easing primitives."""\n\nfrom dataclasses import dataclass\nfrom time import perf_counter\nfrom typing import Callable, List, Optional\nimport math\n\n\ndef clamp01(value: float) -> float:\n    return max(0.0, min(1.0, value))\n\n\ndef ease_out_cubic(t: float) -> float:\n    t = clamp01(t)\n    return 1 - (1 - t) ** 3\n\n\ndef ease_in_out_cubic(t: float) -> float:\n    t = clamp01(t)\n    return 4 * t ** 3 if t < 0.5 else 1 - (-2 * t + 2) ** 3 / 2\n\n\n@dataclass\nclass Tween:\n    """Deterministic scalar tween; scene code decides what the value drives."""\n\n    start: float\n    end: float\n    duration: float\n    easing: Callable[[float], float] = ease_out_cubic\n    elapsed: float = 0.0\n\n    @property\n    def done(self) -> bool:\n        return self.elapsed >= self.duration\n\n    def step(self, delta_seconds: float) -> float:\n        self.elapsed = min(self.duration, self.elapsed + max(0.0, delta_seconds))\n        progress = 1.0 if self.duration <= 0 else self.elapsed / self.duration\n        eased = self.easing(progress)\n        return self.start + (self.end - self.start) * eased\n\n\nclass SceneTransition:\n    """Two-phase transition with one scene switch at maximum coverage."""\n\n    def __init__(self, duration: float = .62):\n        self.duration = duration\n        self.elapsed = 0.0\n        self.active = False\n        self.switched = False\n        self._on_switch: Optional[Callable[[], None]] = None\n\n    @property\n    def progress(self) -> float:\n        return 1.0 if self.duration <= 0 else clamp01(self.elapsed / self.duration)\n\n    @property\n    def cover(self) -> float:\n        """0 → 1 → 0 eased curtain coverage."""\n        if not self.active:\n            return 0.0\n        return math.sin(math.pi * self.progress) ** .72\n\n    def start(self, on_switch: Callable[[], None]) -> bool:\n        if self.active:\n            return False\n        self.elapsed = 0.0\n        self.active = True\n        self.switched = False\n        self._on_switch = on_switch\n        return True\n\n    def step(self, delta_seconds: float):\n        if not self.active:\n            return\n        self.elapsed = min(self.duration, self.elapsed + max(0.0, delta_seconds))\n        if not self.switched and self.progress >= .5:\n            self.switched = True\n            if self._on_switch:\n                self._on_switch()\n        if self.progress >= 1:\n            self.active = False\n            self._on_switch = None\n\n\nclass AnimationClock:\n    """Schedule delta-time animation callbacks through ``turtle.Screen``."""\n\n    def __init__(self, screen, fps: int = 30):\n        self.screen = screen\n        self.frame_ms = max(1, round(1000 / fps))\n        self.callbacks: List[Callable[[float], bool]] = []\n        self.running = False\n        self._last_time = None\n\n    def add(self, callback: Callable[[float], bool]):\n        """Add a callback. Return ``False`` from it to remove it."""\n        self.callbacks.append(callback)\n        if not self.running:\n            self.start()\n\n    def set_fps(self, fps: int):\n        """Update the cadence used for subsequent timer ticks."""\n        self.frame_ms = max(1, round(1000 / fps))\n\n    def start(self):\n        if self.running:\n            return\n        self.running = True\n        self._last_time = perf_counter()\n        self.screen.ontimer(self._tick, self.frame_ms)\n\n    def stop(self):\n        self.running = False\n        self._last_time = None\n\n    def _tick(self):\n        if not self.running:\n            return\n        now = perf_counter()\n        delta = min(0.1, now - self._last_time) if self._last_time else 0.0\n        self._last_time = now\n        self.callbacks = [callback for callback in self.callbacks if callback(delta) is not False]\n        self.screen.update()\n        if self.callbacks:\n            self.screen.ontimer(self._tick, self.frame_ms)\n        else:\n            self.stop()\n', 'canal_delights.core.audio_codec': '"""WAV <-> zlib <-> Base64 codec used for single-file audio packaging."""\nfrom __future__ import annotations\n\nimport base64\nimport binascii\nimport zlib\n\n\ndef encode_wav(wav_bytes: bytes, level: int = 9) -> str:\n    """Compress a complete WAV payload and return an ASCII-safe constant."""\n    if (not isinstance(wav_bytes, (bytes, bytearray))\n            or bytes(wav_bytes)[:4] != b\'RIFF\'\n            or bytes(wav_bytes)[8:12] != b\'WAVE\'):\n        raise ValueError(\'expected a RIFF/WAV byte payload\')\n    return base64.b64encode(zlib.compress(bytes(wav_bytes), level)).decode(\'ascii\')\n\n\ndef decode_wav(encoded: str) -> bytes:\n    """Decode and validate an embedded Base64(zlib(WAV)) payload."""\n    if not encoded:\n        return b\'\'\n    try:\n        payload = zlib.decompress(base64.b64decode(encoded, validate=True))\n    except (binascii.Error, zlib.error, ValueError) as exc:\n        raise ValueError(\'invalid embedded audio payload\') from exc\n    if payload[:4] != b\'RIFF\' or payload[8:12] != b\'WAVE\':\n        raise ValueError(\'embedded payload is not a WAV file\')\n    return payload\n', 'canal_delights.core.backend': '"""Renderer selection shared by the CLI and application."""\n\nfrom enum import Enum\nfrom typing import Union\n\nfrom .engine import DrawingEngine\n\n\nclass RenderMode(str, Enum):\n    PURE = \'pure\'\n    ACCELERATED = \'accelerated\'\n\n    @classmethod\n    def parse(cls, value: Union[\'RenderMode\', str]) -> \'RenderMode\':\n        if isinstance(value, cls):\n            return value\n        try:\n            return cls(str(value).strip().lower())\n        except ValueError as exc:\n            choices = \', \'.join(mode.value for mode in cls)\n            raise ValueError(f"未知渲染模式 {value!r}，可选值：{choices}") from exc\n\n\ndef create_engine(\n    mode: Union[RenderMode, str] = RenderMode.ACCELERATED,\n    width: int = 1200,\n    height: int = 800,\n) -> DrawingEngine:\n    selected = RenderMode.parse(mode)\n    if selected is RenderMode.PURE:\n        return DrawingEngine(width, height)\n\n    # Keep the optional backend import out of pure mode\'s initialization path.\n    from .accelerated import AcceleratedDrawingEngine\n    return AcceleratedDrawingEngine(width, height)\n', 'canal_delights.core.engine': '"""\n绘图引擎 - 封装 Turtle 操作，实现所有 primitive 绘制\n\n职责：\n- 对 Turtle 的低层绘制封装\n- 基础图形、渐变填充、贝塞尔曲线、复合路径\n- 不负责业务状态与城市逻辑\n"""\n\nimport turtle\nimport math\nfrom typing import List, Tuple, Optional, Union\n\nfrom .styles import (\n    RGB, Color, rgb_to_hex, rgb_to_turtle,\n    validate_rgb, interpolate_gradient_stops,\n)\nfrom .geometry import (\n    sample_ellipse, sample_cubic_bezier, sample_quadratic_bezier,\n    polygon_bounds, clip_polygon_by_line, line_intersection,\n    clip_polygon_to_projection_band,\n)\n\n\nclass DrawingEngine:\n    """\n    绘图引擎\n\n    职责：\n    - 对 Turtle 的低层绘制封装\n    - 所有 primitive 的实际绘制\n    """\n\n    def __init__(self, width: int = 1200, height: int = 800):\n        self.mode_name = \'pure\'\n        self.supports_acceleration = False\n        self.width = width\n        self.height = height\n\n        # 初始化 Turtle 屏幕\n        self.screen = turtle.Screen()\n        self.screen.setup(width, height)\n        self.screen.title("运河风物志 Canal Delights")\n        self.screen.tracer(0, 0)  # 关闭自动刷新，手动控制\n\n        # 设置坐标系：(0,0) 在左下角，(width,height) 在右上角\n        self.screen.setworldcoordinates(0, 0, width, height)\n\n        # 初始化画笔\n        self.pen = turtle.Turtle()\n        self.pen.hideturtle()\n        self.pen.speed(0)\n        self.pen.up()\n        self._active_layer = \'content\'\n        self._pens = {\'content\': self.pen}\n\n        # 设置背景色\n        from ..config import CANVAS_BG\n        self.set_bgcolor(CANVAS_BG)\n\n    # ============================================\n    # 基础控制\n    # ============================================\n\n    def set_layer(self, name: str):\n        """Select a retained drawing layer, creating its Turtle lazily."""\n        if not name:\n            raise ValueError(\'图层名不能为空\')\n        if name not in self._pens:\n            pen = turtle.Turtle()\n            pen.hideturtle()\n            pen.speed(0)\n            pen.up()\n            self._pens[name] = pen\n        self._active_layer = name\n        self.pen = self._pens[name]\n\n    def clear(self, layer: Optional[str] = None):\n        """Clear one retained layer, or every layer when omitted."""\n        pens = [self._pens[layer]] if layer in self._pens else []\n        if layer is None:\n            pens = list(self._pens.values())\n        for pen in pens:\n            pen.clear()\n            pen.up()\n\n    def update(self):\n        """手动刷新屏幕"""\n        self.screen.update()\n\n    def set_bgcolor(self, color: RGB):\n        """设置背景色"""\n        self.screen.bgcolor(rgb_to_hex(color))\n\n    def exitonclick(self):\n        """点击退出"""\n        self.screen.exitonclick()\n\n    def mainloop(self):\n        """进入主循环"""\n        self.screen.mainloop()\n\n    def onkey(self, callback, key: str):\n        """绑定键盘事件"""\n        self.screen.onkey(callback, key)\n\n    def listen(self):\n        """开始监听键盘"""\n        self.screen.listen()\n\n    def on_motion(self, callback):\n        """Bind pointer movement using the same world coordinates as Turtle."""\n        def event_handler(event):\n            x = self.screen.cv.canvasx(event.x) / self.screen.xscale\n            y = -self.screen.cv.canvasy(event.y) / self.screen.yscale\n            callback(x, y)\n        self.screen.cv.bind(\'<Motion>\', event_handler)\n\n    def _world_pointer(self, event):\n        """Convert a Tk pointer event to Turtle\'s world coordinates."""\n        x = self.screen.cv.canvasx(event.x) / self.screen.xscale\n        y = -self.screen.cv.canvasy(event.y) / self.screen.yscale\n        return x, y\n\n    def on_pointer_press(self, callback):\n        """Bind a press without replacing Turtle\'s existing click callback."""\n        self.screen.cv.bind(\n            \'<ButtonPress-1>\',\n            lambda event: callback(*self._world_pointer(event)),\n            add=\'+\',\n        )\n\n    def on_pointer_release(self, callback):\n        """Bind pointer release for press-and-hold controls."""\n        self.screen.cv.bind(\n            \'<ButtonRelease-1>\',\n            lambda event: callback(*self._world_pointer(event)),\n            add=\'+\',\n        )\n\n    def set_cursor(self, cursor: str = \'\'):\n        """Set the window cursor; supported identically by both backends."""\n        self.screen.cv.configure(cursor=cursor)\n\n    # ============================================\n    # 基础图形\n    # ============================================\n\n    def draw_point(self, x: float, y: float, size: float, color: RGB):\n        """绘制点"""\n        self.pen.up()\n        self.pen.goto(x, y)\n        self.pen.dot(size, rgb_to_hex(color))\n\n    def draw_line(\n        self,\n        x1: float, y1: float,\n        x2: float, y2: float,\n        color: RGB,\n        width: float = 1.0,\n    ):\n        """绘制线段"""\n        self.pen.up()\n        self.pen.goto(x1, y1)\n        self.pen.down()\n        self.pen.pensize(max(1, width))\n        self.pen.pencolor(rgb_to_hex(color))\n        self.pen.goto(x2, y2)\n        self.pen.up()\n\n    def draw_polyline(\n        self,\n        points: List[Tuple[float, float]],\n        color: RGB,\n        width: float = 1.0,\n        close: bool = False,\n    ):\n        """绘制折线"""\n        if not points:\n            return\n\n        self.pen.up()\n        self.pen.goto(points[0])\n        self.pen.down()\n        self.pen.pensize(max(1, width))\n        self.pen.pencolor(rgb_to_hex(color))\n\n        for p in points[1:]:\n            self.pen.goto(p)\n\n        if close and len(points) > 2:\n            self.pen.goto(points[0])\n\n        self.pen.up()\n\n    # ============================================\n    # 填充图形\n    # ============================================\n\n    def draw_circle(\n        self,\n        cx: float, cy: float,\n        r: float,\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制圆形"""\n        # 转换为多边形以便统一处理渐变\n        points = sample_ellipse(cx, cy, r, r)\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    def draw_ellipse(\n        self,\n        cx: float, cy: float,\n        rx: float, ry: float,\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制椭圆"""\n        points = sample_ellipse(cx, cy, rx, ry)\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    def draw_rect(\n        self,\n        x: float, y: float,\n        w: float, h: float,\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制矩形"""\n        points = [(x, y), (x + w, y), (x + w, y + h), (x, y + h)]\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    def draw_rounded_rect(\n        self,\n        x: float, y: float,\n        w: float, h: float,\n        r: float,\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制圆角矩形 (y轴向上)"""\n        r = min(r, w / 2, h / 2)\n        points = []\n\n        # 四个圆角 - 逆时针方向 (y轴向上)\n        corners = [\n            # (center_x, center_y, start_angle, end_angle)\n            (x + w - r, y + r, 270, 360),     # 右下\n            (x + w - r, y + h - r, 0, 90),    # 右上\n            (x + r, y + h - r, 90, 180),      # 左上\n            (x + r, y + r, 180, 270),         # 左下\n        ]\n\n        for cx, cy, start, end in corners:\n            steps = 8\n            for i in range(steps + 1):\n                angle = math.radians(start + (end - start) * i / steps)\n                px = cx + r * math.cos(angle)\n                py = cy + r * math.sin(angle)\n                points.append((px, py))\n\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    def draw_polygon(\n        self,\n        points: List[Tuple[float, float]],\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制多边形"""\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    def draw_ring(\n        self,\n        cx: float, cy: float,\n        r_inner: float,\n        r_outer: float,\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制圆环"""\n        # 外圆顺时针，内圆逆时针\n        outer_points = sample_ellipse(cx, cy, r_outer, r_outer)\n        inner_points = sample_ellipse(cx, cy, r_inner, r_inner)\n        inner_points.reverse()\n\n        # 组合为环形多边形\n        points = outer_points + inner_points\n        self._draw_filled_polygon(points, fill, stroke, stroke_width)\n\n    # ============================================\n    # 弧形和曲线\n    # ============================================\n\n    def draw_arc(\n        self,\n        cx: float, cy: float,\n        r: float,\n        start_angle: float,\n        end_angle: float,\n        color: RGB,\n        width: float = 1.0,\n    ):\n        """绘制弧形"""\n        steps = 50\n        points = []\n        for i in range(steps + 1):\n            t = i / steps\n            angle = math.radians(start_angle + (end_angle - start_angle) * t)\n            px = cx + r * math.cos(angle)\n            py = cy + r * math.sin(angle)\n            points.append((px, py))\n\n        self.draw_polyline(points, color, width, close=False)\n\n    def draw_bezier(\n        self,\n        control_points: List[Tuple[float, float]],\n        color: RGB,\n        width: float = 1.0,\n    ):\n        """绘制三次贝塞尔曲线"""\n        if len(control_points) < 4:\n            return\n\n        points = sample_cubic_bezier(\n            control_points[0],\n            control_points[1],\n            control_points[2],\n            control_points[3],\n        )\n        self.draw_polyline(points, color, width, close=False)\n\n    def draw_quadratic(\n        self,\n        p0: Tuple[float, float],\n        p1: Tuple[float, float],\n        p2: Tuple[float, float],\n        color: RGB,\n        width: float = 1.0,\n    ):\n        """绘制二次贝塞尔曲线"""\n        points = sample_quadratic_bezier(p0, p1, p2)\n        self.draw_polyline(points, color, width, close=False)\n\n    def draw_path(\n        self,\n        commands: List[list],\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """\n        绘制复合路径\n\n        命令格式：\n        - [\'M\', x, y] - 移动到\n        - [\'L\', x, y] - 画线到\n        - [\'Q\', x1, y1, x2, y2] - 二次贝塞尔\n        - [\'C\', x1, y1, x2, y2, x3, y3] - 三次贝塞尔\n        - [\'Z\'] - 闭合路径\n        """\n        points = []\n        current_pos = (0, 0)\n        closed = False\n\n        for cmd in commands:\n            if not cmd:\n                continue\n\n            op = cmd[0]\n\n            if op == \'M\' and len(cmd) >= 3:\n                current_pos = (cmd[1], cmd[2])\n                points.append(current_pos)\n\n            elif op == \'L\' and len(cmd) >= 3:\n                current_pos = (cmd[1], cmd[2])\n                points.append(current_pos)\n\n            elif op == \'Q\' and len(cmd) >= 5:\n                p0 = current_pos\n                p1 = (cmd[1], cmd[2])\n                p2 = (cmd[3], cmd[4])\n                curve_points = sample_quadratic_bezier(p0, p1, p2)\n                points.extend(curve_points[1:])  # 跳过起点\n                current_pos = p2\n\n            elif op == \'C\' and len(cmd) >= 7:\n                p0 = current_pos\n                p1 = (cmd[1], cmd[2])\n                p2 = (cmd[3], cmd[4])\n                p3 = (cmd[5], cmd[6])\n                curve_points = sample_cubic_bezier(p0, p1, p2, p3)\n                points.extend(curve_points[1:])\n                current_pos = p3\n\n            elif op == \'Z\':\n                if points:\n                    points.append(points[0])\n                    closed = True\n\n        if points:\n            # An open PATH is a stroke, not a polygon.  The shared polygon\n            # helper always closes its outline, which used to add a spurious\n            # last-to-first segment to waterways and other open curves.\n            if fill and closed:\n                self._fill_polygon(points, fill)\n            if stroke:\n                self.draw_polyline(points, stroke, stroke_width, close=False)\n\n    # ============================================\n    # 文字\n    # ============================================\n\n    def draw_text(\n        self,\n        text: str,\n        x: float,\n        y: float,\n        font_size: int,\n        color: RGB,\n        font_family: str = \'Microsoft YaHei\',\n        align: str = \'center\',\n        weight: str = \'normal\',\n    ):\n        """绘制文字"""\n        self.pen.up()\n        self.pen.goto(x, y)\n        self.pen.pencolor(rgb_to_hex(color))\n\n        align_map = {\'left\': \'left\', \'center\': \'center\', \'right\': \'right\'}\n        turtle_align = align_map.get(align, \'center\')\n\n        self.pen.write(\n            text,\n            align=turtle_align,\n            font=(font_family, font_size, weight),\n        )\n\n    # ============================================\n    # 渐变填充\n    # ============================================\n\n    def draw_gradient_fill(\n        self,\n        polygon: List[Tuple[float, float]],\n        gradient: dict,\n        bounds: Tuple[float, float, float, float],\n    ):\n        """\n        绘制渐变填充\n\n        参数:\n            polygon: 目标多边形\n            gradient: 渐变定义\n            bounds: 绘制区域\n        """\n        if not polygon or not gradient:\n            return\n\n        gradient_type = gradient.get(\'type\', \'linear\')\n        stops = gradient.get(\'stops\', [])\n        steps = gradient.get(\'steps\', 36)\n\n        if not stops:\n            return\n\n        if gradient_type == \'linear\':\n            self._draw_linear_gradient(polygon, stops, gradient.get(\'angle\', 0), steps)\n        elif gradient_type == \'radial\':\n            self._draw_radial_gradient(polygon, stops, gradient.get(\'center\', [0.5, 0.5]), steps, bounds)\n\n    def _draw_linear_gradient(\n        self,\n        polygon: List[Tuple[float, float]],\n        stops: List[tuple],\n        angle: float,\n        steps: int,\n    ):\n        """Render clipped parallel color bands inside the target polygon."""\n        if len(polygon) < 3:\n            return\n        count = max(2, min(128, int(steps)))\n        radians = math.radians(angle)\n        axis = (math.cos(radians), math.sin(radians))\n        projections = [x * axis[0] + y * axis[1] for x, y in polygon]\n        low, high = min(projections), max(projections)\n        span = high - low\n        if span <= 1e-9:\n            self._fill_polygon(polygon, interpolate_gradient_stops(stops, 0.5))\n            return\n\n        # A tiny overlap prevents hairline gaps caused by Canvas rounding.\n        overlap = span / count * 0.015\n        for index in range(count):\n            t0 = index / count\n            t1 = (index + 1) / count\n            band = clip_polygon_to_projection_band(\n                polygon, axis, low + span * t0 - overlap, low + span * t1 + overlap,\n            )\n            if len(band) >= 3:\n                self._fill_polygon(band, interpolate_gradient_stops(stops, (t0 + t1) / 2))\n\n    def _draw_radial_gradient(\n        self,\n        polygon: List[Tuple[float, float]],\n        stops: List[tuple],\n        center: List[float],\n        steps: int,\n        bounds: Tuple[float, float, float, float],\n    ):\n        """Render a radial gradient as nested, silhouette-clipped polygons."""\n        if len(polygon) < 3:\n            return\n        count = max(2, min(128, int(steps)))\n        min_x, min_y, max_x, max_y = polygon_bounds(polygon)\n        fx = min_x + (max_x - min_x) * float(center[0])\n        fy = min_y + (max_y - min_y) * float(center[1])\n\n        self._fill_polygon(polygon, interpolate_gradient_stops(stops, 1.0))\n        for index in reversed(range(count)):\n            scale = (index + 1) / count\n            inset = [(fx + (x - fx) * scale, fy + (y - fy) * scale) for x, y in polygon]\n            self._fill_polygon(inset, interpolate_gradient_stops(stops, index / count))\n\n    def _clip_to_polygon(\n        self,\n        source: List[Tuple[float, float]],\n        target: List[Tuple[float, float]],\n    ) -> List[Tuple[float, float]]:\n        """\n        将 source 多边形裁切到 target 多边形内\n\n        简化实现：保留 target 内的 source 点\n        """\n        from .geometry import point_in_polygon\n\n        result = []\n        for p in source:\n            if point_in_polygon(p, target):\n                result.append(p)\n\n        # 如果裁切后点太少，返回 target\n        return result if len(result) >= 3 else target\n\n    # ============================================\n    # 内部辅助方法\n    # ============================================\n\n    def _draw_filled_polygon(\n        self,\n        points: List[Tuple[float, float]],\n        fill: Optional[RGB] = None,\n        stroke: Optional[RGB] = None,\n        stroke_width: float = 1.0,\n    ):\n        """绘制填充多边形"""\n        if not points:\n            return\n\n        if fill:\n            self._fill_polygon(points, fill)\n\n        if stroke:\n            self.draw_polyline(points, stroke, stroke_width, close=True)\n\n    def _fill_polygon(\n        self,\n        points: List[Tuple[float, float]],\n        color: RGB,\n    ):\n        """填充多边形"""\n        if not points:\n            return\n\n        hex_color = rgb_to_hex(color)\n        self.pen.up()\n        self.pen.goto(points[0])\n        self.pen.down()\n        self.pen.fillcolor(hex_color)\n        self.pen.pencolor(hex_color)  # 画笔颜色与填充一致，避免黑边\n        self.pen.begin_fill()\n\n        for p in points[1:]:\n            self.pen.goto(p)\n\n        self.pen.goto(points[0])\n        self.pen.end_fill()\n        self.pen.up()\n', 'canal_delights.core.geometry': '"""\n几何模块 - 变换、曲线采样、多边形裁切、命中测试\n"""\n\nimport math\nfrom typing import List, Tuple, Optional\n\n\nPoint = Tuple[float, float]\n\n\n# ============================================\n# 坐标转换\n# ============================================\n\ndef normalized_to_absolute(\n    x: float,\n    y: float,\n    bounds: Tuple[float, float, float, float],\n) -> Point:\n    """\n    归一化坐标转绝对坐标\n\n    参数:\n        x, y: 归一化坐标 0.0-1.0\n        bounds: (left, bottom, width, height)\n\n    返回:\n        绝对坐标 (x, y)\n    """\n    left, bottom, width, height = bounds\n    abs_x = left + x * width\n    abs_y = bottom + y * height\n    return (abs_x, abs_y)\n\n\ndef normalized_size_to_absolute(\n    size: float,\n    bounds: Tuple[float, float, float, float],\n) -> float:\n    """\n    归一化尺寸转绝对尺寸\n\n    使用 min(width, height) 作为基准，避免非等比拉伸\n    """\n    _, _, width, height = bounds\n    return size * min(width, height)\n\n\ndef normalized_points_to_absolute(\n    points: List[Point],\n    bounds: Tuple[float, float, float, float],\n) -> List[Point]:\n    """批量转换点坐标"""\n    return [normalized_to_absolute(p[0], p[1], bounds) for p in points]\n\n\n# ============================================\n# Transform 变换\n# ============================================\n\ndef apply_transform(\n    point: Point,\n    transform: dict,\n    bounds: Tuple[float, float, float, float],\n) -> Point:\n    """\n    应用变换到点\n\n    执行顺序：\n    1. 确定枢轴点\n    2. 缩放（围绕枢轴）\n    3. 旋转（围绕枢轴）\n    4. 平移\n\n    参数:\n        point: 原始点 (x, y) 归一化坐标\n        transform: 变换字典\n        bounds: 绘制区域\n\n    返回:\n        变换后的点\n    """\n    # A composed transform retains individual operations and pivots.  Merging\n    # the two dictionaries loses this information whenever transforms differ.\n    if transform and \'_chain\' in transform:\n        result = point\n        for step in transform[\'_chain\']:\n            result = apply_transform(result, step, bounds)\n        return result\n\n    x, y = point\n\n    # 确定枢轴点（默认为中心）\n    pivot = transform.get(\'pivot\')\n    if pivot:\n        px, py = pivot\n    else:\n        px, py = 0.5, 0.5\n\n    # 缩放\n    scale = transform.get(\'scale\')\n    if scale:\n        sx, sy = scale if len(scale) == 2 else (scale[0], scale[0])\n        # 围绕枢轴缩放\n        x = px + (x - px) * sx\n        y = py + (y - py) * sy\n\n    # 旋转\n    rotate = transform.get(\'rotate\')\n    if rotate:\n        angle_rad = math.radians(rotate)\n        cos_a = math.cos(angle_rad)\n        sin_a = math.sin(angle_rad)\n        # 围绕枢轴旋转\n        dx = x - px\n        dy = y - py\n        x = px + dx * cos_a - dy * sin_a\n        y = py + dx * sin_a + dy * cos_a\n\n    # 平移\n    translate = transform.get(\'translate\')\n    if translate:\n        x += translate[0]\n        y += translate[1]\n\n    return (x, y)\n\n\ndef transform_points(\n    points: List[Point],\n    transform: dict,\n    bounds: Tuple[float, float, float, float],\n) -> List[Point]:\n    """批量变换点"""\n    return [apply_transform(p, transform, bounds) for p in points]\n\n\ndef transform_scale(transform: Optional[dict]) -> Point:\n    """Return the accumulated x/y scale of a transform or transform chain."""\n    if not transform:\n        return 1.0, 1.0\n    if \'_chain\' in transform:\n        sx, sy = 1.0, 1.0\n        for step in transform[\'_chain\']:\n            step_x, step_y = transform_scale(step)\n            sx *= step_x\n            sy *= step_y\n        return sx, sy\n    scale = transform.get(\'scale\')\n    if not scale:\n        return 1.0, 1.0\n    if len(scale) == 1:\n        return float(scale[0]), float(scale[0])\n    return float(scale[0]), float(scale[1])\n\n\ndef compose_transforms(parent: dict, child: dict) -> dict:\n    """\n    组合父子变换\n\n    Child operations happen in local coordinates, followed by the parent.\n    A short chain is equivalent to matrix composition for points and preserves\n    distinct pivots without introducing a separate matrix representation.\n    """\n    return {\'_chain\': [child, parent]}\n\n\n# ============================================\n# 贝塞尔曲线\n# ============================================\n\ndef cubic_bezier_point(\n    p0: Point,\n    p1: Point,\n    p2: Point,\n    p3: Point,\n    t: float,\n) -> Point:\n    """\n    计算三次贝塞尔曲线上的点\n\n    参数:\n        p0, p1, p2, p3: 控制点\n        t: 参数 0.0-1.0\n\n    返回:\n        曲线上的点\n    """\n    t = max(0.0, min(1.0, t))\n    t2 = t * t\n    t3 = t2 * t\n    mt = 1 - t\n    mt2 = mt * mt\n    mt3 = mt2 * mt\n\n    x = mt3 * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t3 * p3[0]\n    y = mt3 * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t3 * p3[1]\n\n    return (x, y)\n\n\ndef quadratic_bezier_point(\n    p0: Point,\n    p1: Point,\n    p2: Point,\n    t: float,\n) -> Point:\n    """\n    计算二次贝塞尔曲线上的点\n\n    参数:\n        p0, p1, p2: 控制点\n        t: 参数 0.0-1.0\n\n    返回:\n        曲线上的点\n    """\n    t = max(0.0, min(1.0, t))\n    mt = 1 - t\n\n    x = mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0]\n    y = mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1]\n\n    return (x, y)\n\n\ndef sample_cubic_bezier(\n    p0: Point,\n    p1: Point,\n    p2: Point,\n    p3: Point,\n    steps: int = 50,\n) -> List[Point]:\n    """采样三次贝塞尔曲线"""\n    points = []\n    for i in range(steps + 1):\n        t = i / steps\n        points.append(cubic_bezier_point(p0, p1, p2, p3, t))\n    return points\n\n\ndef sample_quadratic_bezier(\n    p0: Point,\n    p1: Point,\n    p2: Point,\n    steps: int = 50,\n) -> List[Point]:\n    """采样二次贝塞尔曲线"""\n    points = []\n    for i in range(steps + 1):\n        t = i / steps\n        points.append(quadratic_bezier_point(p0, p1, p2, t))\n    return points\n\n\n# ============================================\n# 椭圆采样\n# ============================================\n\ndef sample_ellipse(\n    cx: float,\n    cy: float,\n    rx: float,\n    ry: float,\n    steps: int = 100,\n) -> List[Point]:\n    """采样椭圆为多边形"""\n    points = []\n    for i in range(steps + 1):\n        angle = 2 * math.pi * i / steps\n        x = cx + rx * math.cos(angle)\n        y = cy + ry * math.sin(angle)\n        points.append((x, y))\n    return points\n\n\n# ============================================\n# 多边形操作\n# ============================================\n\ndef polygon_area(points: List[Point]) -> float:\n    """计算多边形面积（有符号）"""\n    n = len(points)\n    if n < 3:\n        return 0.0\n\n    area = 0.0\n    for i in range(n):\n        j = (i + 1) % n\n        area += points[i][0] * points[j][1]\n        area -= points[j][0] * points[i][1]\n\n    return area / 2.0\n\n\ndef polygon_bounds(points: List[Point]) -> Tuple[float, float, float, float]:\n    """计算多边形边界框 (min_x, min_y, max_x, max_y)"""\n    if not points:\n        return (0, 0, 0, 0)\n\n    xs = [p[0] for p in points]\n    ys = [p[1] for p in points]\n\n    return (min(xs), min(ys), max(xs), max(ys))\n\n\ndef point_in_polygon(point: Point, polygon: List[Point]) -> bool:\n    """\n    判断点是否在多边形内（射线法）\n\n    参数:\n        point: 测试点\n        polygon: 多边形顶点列表\n\n    返回:\n        True 如果在内部\n    """\n    x, y = point\n    n = len(polygon)\n    inside = False\n\n    j = n - 1\n    for i in range(n):\n        xi, yi = polygon[i]\n        xj, yj = polygon[j]\n\n        if ((yi > y) != (yj > y)) and (x < (xj - xi) * (y - yi) / (yj - yi) + xi):\n            inside = not inside\n\n        j = i\n\n    return inside\n\n\n# ============================================\n# 多边形裁切（Sutherland-Hodgman）\n# ============================================\n\ndef clip_polygon_by_line(\n    polygon: List[Point],\n    line_start: Point,\n    line_end: Point,\n) -> List[Point]:\n    """\n    用直线裁切多边形（保留左侧）\n\n    Sutherland-Hodgman 算法的单边版本\n    """\n    if not polygon:\n        return []\n\n    result = []\n    n = len(polygon)\n\n    for i in range(n):\n        current = polygon[i]\n        next_pt = polygon[(i + 1) % n]\n\n        # 判断点在直线的哪一侧\n        def side(p):\n            return ((line_end[0] - line_start[0]) * (p[1] - line_start[1]) -\n                    (line_end[1] - line_start[1]) * (p[0] - line_start[0]))\n\n        current_side = side(current)\n        next_side = side(next_pt)\n\n        if current_side >= 0:  # 当前点在左侧\n            result.append(current)\n            if next_side < 0:  # 下一个点在右侧，计算交点\n                intersection = line_intersection(\n                    current, next_pt, line_start, line_end\n                )\n                if intersection:\n                    result.append(intersection)\n        elif next_side >= 0:  # 当前点在右侧，下一个点在左侧\n            intersection = line_intersection(\n                current, next_pt, line_start, line_end\n            )\n            if intersection:\n                result.append(intersection)\n\n    return result\n\n\ndef line_intersection(\n    p1: Point,\n    p2: Point,\n    p3: Point,\n    p4: Point,\n) -> Optional[Point]:\n    """计算两条直线的交点"""\n    x1, y1 = p1\n    x2, y2 = p2\n    x3, y3 = p3\n    x4, y4 = p4\n\n    denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)\n\n    if abs(denom) < 1e-10:\n        return None  # 平行\n\n    t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom\n\n    x = x1 + t * (x2 - x1)\n    y = y1 + t * (y2 - y1)\n\n    return (x, y)\n\n\ndef clip_polygon_to_projection_band(\n    polygon: List[Point],\n    axis: Point,\n    lower: float,\n    upper: float,\n) -> List[Point]:\n    """Clip a polygon to ``lower <= dot(point, axis) <= upper``.\n\n    This is the convex half-plane operation needed by linear-gradient bands.\n    It also behaves predictably for the concave shapes used by this project,\n    although a band may be returned as one connected polygon.\n    """\n    def projection(point: Point) -> float:\n        return point[0] * axis[0] + point[1] * axis[1]\n\n    def clip(points: List[Point], threshold: float, keep_greater: bool) -> List[Point]:\n        if not points:\n            return []\n        output = []\n        previous = points[-1]\n        previous_value = projection(previous)\n        previous_inside = previous_value >= threshold if keep_greater else previous_value <= threshold\n\n        for current in points:\n            current_value = projection(current)\n            current_inside = current_value >= threshold if keep_greater else current_value <= threshold\n            if current_inside != previous_inside:\n                denominator = current_value - previous_value\n                if abs(denominator) > 1e-12:\n                    ratio = (threshold - previous_value) / denominator\n                    output.append((\n                        previous[0] + (current[0] - previous[0]) * ratio,\n                        previous[1] + (current[1] - previous[1]) * ratio,\n                    ))\n            if current_inside:\n                output.append(current)\n            previous = current\n            previous_value = current_value\n            previous_inside = current_inside\n        return output\n\n    return clip(clip(list(polygon), lower, True), upper, False)\n\n\n# ============================================\n# 渐变裁切\n# ============================================\n\ndef clip_gradient_band(\n    polygon: List[Point],\n    band_start: Point,\n    band_end: Point,\n    angle: float,\n) -> List[Point]:\n    """\n    裁切渐变色的色带\n\n    参数:\n        polygon: 目标多边形\n        band_start, band_end: 色带边界线\n        angle: 渐变角度\n\n    返回:\n        裁切后的多边形\n    """\n    # 简化实现：用矩形边界裁切\n    # TODO: 实现完整的 Sutherland-Hodgman 多边形裁切\n\n    if not polygon:\n        return []\n\n    # 计算色带矩形\n    min_x = min(band_start[0], band_end[0])\n    max_x = max(band_start[0], band_end[0])\n    min_y = min(band_start[1], band_end[1])\n    max_y = max(band_start[1], band_end[1])\n\n    # 简单的边界框裁切\n    result = []\n    for p in polygon:\n        x, y = p\n        if min_x <= x <= max_x and min_y <= y <= max_y:\n            result.append(p)\n\n    return result if result else polygon\n\n\n# ============================================\n# 命中测试\n# ============================================\n\ndef hit_test_point(\n    point: Point,\n    target: Point,\n    radius: float,\n) -> bool:\n    """点命中测试（圆形区域）"""\n    dx = point[0] - target[0]\n    dy = point[1] - target[1]\n    return dx * dx + dy * dy <= radius * radius\n\n\ndef hit_test_polygon(\n    point: Point,\n    polygon: List[Point],\n) -> bool:\n    """多边形命中测试"""\n    return point_in_polygon(point, polygon)\n\n\ndef hit_test_rect(\n    point: Point,\n    rect: Tuple[float, float, float, float],\n) -> bool:\n    """矩形命中测试 (x, y, w, h)"""\n    x, y = point\n    rx, ry, rw, rh = rect\n    return rx <= x <= rx + rw and ry <= y <= ry + rh\n', 'canal_delights.core.music': '"""Self-contained, score-led multi-voice synthesizer; no audio files."""\nfrom __future__ import annotations\nfrom array import array\nfrom dataclasses import dataclass\nimport ctypes\nimport io, math, random, sys, threading, time, wave\nimport multiprocessing\nfrom .audio_codec import decode_wav\nfrom .embedded_bgm import BGM_WAV_ZLIB_BASE64\ntry:\n    from .embedded_mp3 import BGM_MP3_BASE64\nexcept ImportError:\n    BGM_MP3_BASE64 = \'\'\nimport base64\n\n\ndef _audio_process_main(payload, kind=\'wav\'):\n    """Own the blocking Windows call so the parent can terminate playback."""\n    import winsound\n    if kind == \'mp3\':\n        import tempfile\n        from pathlib import Path\n        path = Path(tempfile.gettempdir()) / \'canal_delights_bgm.mp3\'\n        path.write_bytes(payload)\n        winmm = ctypes.WinDLL(\'winmm\')\n        send = winmm.mciSendStringW\n        send(f\'open "{path}" type mpegvideo alias canal_delights\', None, 0, None)\n        send(\'play canal_delights repeat\', None, 0, None)\n        try:\n            while True:\n                time.sleep(.25)\n        finally:\n            send(\'close canal_delights\', None, 0, None)\n        return\n    while True:\n        winsound.PlaySound(payload, winsound.SND_MEMORY)\n\nSAMPLE_RATE, DEFAULT_BPM, FULL_SCALE = 11025, 120, 32767\n\n@dataclass(frozen=True)\nclass Voice:\n    name: str; timbre: str; volume: float; pan: float\n    attack: float; decay: float; sustain: float; release: float\n    vibrato_hz: float = 0.; vibrato_depth: float = 0.\n\n@dataclass(frozen=True)\nclass NoteEvent:\n    voice: str; note: str; start_beats: float; duration_beats: float\n    velocity: str = \'mf\'; articulation: str = \'legato\'\n\n@dataclass(frozen=True)\nclass ScorePosition:\n    bar: int\n    beat: float\n    seconds: float\n    cycle: int = 0\n\n# Five independent instruments: each owns timbre, gain and stereo position.\nVOICES = {\n    \'melody\': Voice(\'melody\',\'pluck\',.20,.62,.018,.13,.52,.20),\n    \'flute\': Voice(\'flute\',\'flute_fm\',.12,.34,.070,.18,.76,.30,5.2,.009),\n    \'harmony\': Voice(\'harmony\',\'pad\',.115,.46,.14,.30,.58,.42),\n    \'bass\': Voice(\'bass\',\'bass\',.15,.54,.025,.13,.64,.18),\n    \'drums\': Voice(\'drums\',\'percussion\',.045,.52,.006,.05,0.,.08),\n}\nNATURE_LAYERS = {\'stream\': .010, \'breeze\': .006, \'birds\': .016}\nVELOCITIES = {\'pp\': .52, \'mf\': .76, \'ff\': 1.}\n# I – V7 – vi7 – IVmaj7, explicitly containing both triads and sevenths.\nPROGRESSION = ((\'D3\',\'F#3\',\'A3\',\'C#4\'), (\'A2\',\'C#3\',\'E3\',\'G3\'),\n               (\'B2\',\'D3\',\'F#3\',\'A3\'), (\'G2\',\'B2\',\'D3\',\'F#3\'))\nMELODY_A = ((\'D5\',0,1),(\'F#5\',1,.5),(\'A5\',1.5,.5),(\'F#5\',2,1),(\'E5\',3,.75),\n (\'D5\',4,1),(\'A4\',5,.5),(\'D5\',5.5,.5),(\'F#5\',6,1),(\'E5\',7,1),\n (\'F#5\',8,.5),(\'A5\',8.5,.5),(\'B5\',9,1),(\'A5\',10,.75),(\'F#5\',11,1),\n (\'E5\',12,1),(\'D5\',13,1),(\'A4\',14,2))\nMELODY_B = ((\'A5\',0,.5),(\'B5\',.5,.5),(\'D6\',1,1),(\'A5\',2,.5),(\'F#5\',2.5,.5),(\'E5\',3,1),\n (\'F#5\',4,.5),(\'A5\',4.5,.5),(\'B5\',5,1),(\'D6\',6,.5),(\'B5\',6.5,.5),(\'A5\',7,1),\n (\'D6\',8,.5),(\'E6\',8.5,.5),(\'F#6\',9,1),(\'E6\',10,.5),(\'D6\',10.5,.5),(\'B5\',11,1),\n (\'A5\',12,.5),(\'F#5\',12.5,.5),(\'E5\',13,1),(\'D5\',14,2))\nCANAL_THEME = tuple((n,d) for n,_,d in MELODY_A)\n\ndef note_frequency(note: str) -> float:\n    if note == \'REST\': return 0.\n    names={\'C\':0,\'C#\':1,\'D\':2,\'D#\':3,\'E\':4,\'F\':5,\'F#\':6,\'G\':7,\'G#\':8,\'A\':9,\'A#\':10,\'B\':11}\n    cut = 2 if len(note)>2 and note[1]==\'#\' else 1\n    midi=(int(note[cut:])+1)*12+names[note[:cut]]\n    return 440. * 2 ** ((midi-69)/12)\n\ndef build_canal_score() -> tuple[NoteEvent,...]:\n    """128 beats/64 seconds at 120 BPM: an explicit eight-part river suite."""\n    events=[]\n    # A–B–A′–B′–A″–B″–bridge–finale: finite form, never an infinite loop.\n    for section, offset in enumerate(range(0, 128, 16)):\n        is_b=section % 2 == 1; vel=\'ff\' if section >= 6 else (\'mf\' if is_b else \'pp\')\n        for n,s,d in (MELODY_B if is_b else MELODY_A):\n            events.append(NoteEvent(\'melody\',n,offset+s,d,vel,\'staccato\' if is_b and d<=.5 else \'legato\'))\n        for ci,chord in enumerate(PROGRESSION):\n            base=offset+ci*4\n            if is_b: # contrasting broken-chord rhythm\n                for step in range(8): events.append(NoteEvent(\'harmony\',chord[step%4],base+step*.5,.42,vel,\'staccato\'))\n            else:\n                for n in chord: events.append(NoteEvent(\'harmony\',n,base,3.88,vel))\n            for beat,n,d in ((0,chord[0],1.15),(1.5,chord[2],.65),(2.5,chord[0],.9),(3.5,chord[2],.35)):\n                events.append(NoteEvent(\'bass\',n,base+beat,d,vel,\'staccato\' if beat==3.5 else \'legato\'))\n        step=.5 if is_b else 1.\n        for tick in range(int(16/step)):\n            events.append(NoteEvent(\'drums\',\'DRUM\',offset+tick*step,.12 if is_b else .17,\n                                    \'ff\' if section >= 6 and tick%4==0 else \'mf\',\'staccato\'))\n        if is_b:\n            for n,s,d in MELODY_A[::2]: events.append(NoteEvent(\'flute\',n,offset+s+.18,max(.35,d*.82),\'mf\' if section < 5 else \'ff\'))\n    return tuple(sorted(events,key=lambda e:e.start_beats))\nCANAL_SCORE=build_canal_score()\n\ndef _envelope(t,d,v,art):\n    gate=d*(.72 if art==\'staccato\' else .985); release=max(v.attack+v.decay,gate-v.release)\n    if t<v.attack: return t/max(v.attack,1e-6)\n    if t<v.attack+v.decay: return 1+(v.sustain-1)*(t-v.attack)/max(v.decay,1e-6)\n    if t<release: return v.sustain\n    if t<gate: return v.sustain*max(0.,(gate-t)/max(gate-release,1e-6))\n    return 0.\n\ndef _tone(t,f,v,bright,seed,sr):\n    phase=math.tau*f*t\n    if v.timbre==\'pluck\': return (math.sin(phase)+(.16+.12*bright)*math.sin(2*phase)+(.04+.05*bright)*math.sin(3*phase))/1.35\n    if v.timbre==\'flute_fm\':\n        c=phase*(1+v.vibrato_depth*math.sin(math.tau*v.vibrato_hz*t))\n        return (math.sin(c+.18*math.sin(math.tau*2.1*t))+.10*math.sin(2*c)+.035*math.sin(3*c))/1.14\n    if v.timbre==\'pad\': return (math.sin(phase)+.17*math.sin(2*phase)+.045*math.sin(3*phase))/1.22\n    if v.timbre==\'bass\': return (math.sin(phase)+.12*math.sin(2*phase)+.025*math.sin(3*phase))/1.15\n    # A soft wooden pulse replaces the earlier noisy synthetic percussion.\n    return .72*math.sin(math.tau*510*t)*math.exp(-24*t)+.28*math.sin(math.tau*760*t)*math.exp(-32*t)\n\ndef _add_event(left,right,event,bpm,sr,master,rng,seed):\n    v=VOICES[event.voice]; beat=60/bpm; onset=round(event.start_beats*beat*sr)\n    duration=max(.015,event.duration_beats*beat*(1+rng.uniform(-.08,.08))) # 5–15% humanize\n    count=min(round(duration*sr),len(left)-onset)\n    if count<=0:return\n    f=92. if event.note==\'DRUM\' else note_frequency(event.note); amp=v.volume*VELOCITIES[event.velocity]*master\n    lg,rg=math.sqrt(1-v.pan),math.sqrt(v.pan)\n    for i in range(count):\n        value=amp*_envelope(i/sr,duration,v,event.articulation)*_tone(i/sr,f,v,VELOCITIES[event.velocity],seed,sr)\n        left[onset+i]+=value*lg; right[onset+i]+=value*rg\n\ndef _effects(left,right,sr,preset):\n    taps=((.029,.18),(.047,.13),(.071,.09)) if preset==\'room\' else ((.041,.20),(.073,.15),(.119,.11),(.173,.07))\n    dl,dr=left[:],right[:]\n    for seconds,gain in taps:\n        delay=round(seconds*sr)\n        for i in range(delay,len(left)): left[i]+=dl[i-delay]*gain; right[i]+=dr[i-delay]*gain\n    for i in range(round(.024*sr),len(left)): # subtle modulated-delay chorus\n        delay=round((.018+.003*math.sin(math.tau*.27*i/sr))*sr)\n        if i>=delay: left[i]+=dl[i-delay]*.07; right[i]+=dr[i-delay]*.07\n\ndef _add_nature(left, right, sr, master):\n    """Add a quiet, low-passed waterside bed and four sparse bird calls."""\n    state = 0xC0FFEE\n    breeze = water = slow_water = 0.\n    for i in range(len(left)):\n        state = (1664525 * state + 1013904223) & 0xffffffff\n        noise = state / 2147483648. - 1.\n        breeze += .0015 * (noise - breeze)\n        water += .040 * (noise - water)\n        slow_water += .009 * (noise - slow_water)\n        stream = (water - slow_water) * NATURE_LAYERS[\'stream\'] * master\n        air = breeze * NATURE_LAYERS[\'breeze\'] * master\n        drift = .72 + .28 * math.sin(math.tau * .075 * i / sr)\n        left[i] += stream * .92 + air * drift\n        right[i] += stream * 1.08 + air * (1.0 - .12 * drift)\n    for call, start in enumerate((7.4, 22.8, 40.6, 57.2)):\n        onset, duration = round(start * sr), round(.42 * sr)\n        pan = .22 if call % 2 == 0 else .78\n        for i in range(min(duration, len(left) - onset)):\n            t = i / sr\n            env = math.sin(math.pi * t / .42) ** 2\n            frequency = 1450 + 520 * t / .42 + 90 * math.sin(math.tau * 6.2 * t)\n            chirp = math.sin(math.tau * frequency * t) * env * NATURE_LAYERS[\'birds\'] * master\n            left[onset+i] += chirp * math.sqrt(1-pan)\n            right[onset+i] += chirp * math.sqrt(pan)\n\ndef render_canal_suite(bpm=DEFAULT_BPM,volume=.7,sample_rate=SAMPLE_RATE,reverb=\'hall\') -> bytes:\n    """Render the fresh-light 64-second stereo suite and nature ambience."""\n    if bpm<=0: raise ValueError(\'bpm must be positive\')\n    if reverb not in {\'room\',\'hall\'}: raise ValueError("reverb must be \'room\' or \'hall\'")\n    frames=round((128*60/bpm+1.25)*sample_rate); left,right=[0.]*frames,[0.]*frames; rng=random.Random(20260913)\n    for seed,event in enumerate(CANAL_SCORE): _add_event(left,right,event,bpm,sample_rate,max(0.,min(1.,volume)),rng,seed)\n    _add_nature(left,right,sample_rate,max(0.,min(1.,volume)))\n    _effects(left,right,sample_rate,reverb); peak=max(max(map(abs,left)),max(map(abs,right)),1e-9); gain=min(1.,.90/peak)\n    pcm=array(\'h\')\n    for l,r in zip(left,right): pcm.extend((round(max(-.9,min(.9,l*gain))*FULL_SCALE),round(max(-.9,min(.9,r*gain))*FULL_SCALE)))\n    if sys.byteorder!=\'little\': pcm.byteswap()\n    stream=io.BytesIO()\n    with wave.open(stream,\'wb\') as w: w.setnchannels(2); w.setsampwidth(2); w.setframerate(sample_rate); w.writeframes(pcm.tobytes())\n    return stream.getvalue()\n\ndef synthesize_score(score=None,bpm=DEFAULT_BPM,volume=.7,sample_rate=SAMPLE_RATE) -> bytes:\n    """Compatibility entrypoint; the default is the full multi-voice suite."""\n    if score is None or score==CANAL_THEME: return render_canal_suite(bpm,volume,sample_rate)\n    # Existing callers get the canonical performance rather than asset playback.\n    return render_canal_suite(bpm,volume,sample_rate)\n\ndef score_position(elapsed, bpm=DEFAULT_BPM, beats_per_bar=4):\n    """Map monotonic elapsed time to an absolute bar/beat position."""\n    elapsed=max(0.,float(elapsed)); beat_seconds=60./bpm\n    total_beats=elapsed/beat_seconds\n    return ScorePosition(int(total_beats//beats_per_bar), total_beats%beats_per_bar, elapsed)\n\ndef looped_score_position(elapsed,duration,bpm=DEFAULT_BPM,beats_per_bar=4):\n    """Locate a repeating finite score without accumulating playback delay."""\n    if duration<=0:raise ValueError(\'duration must be positive\')\n    cycle=int(max(0.,elapsed)//duration)\n    position=score_position(max(0.,elapsed)%duration,bpm,beats_per_bar)\n    return ScorePosition(position.bar,position.beat,position.seconds,cycle)\n\ndef _wav_timeline(payload):\n    with wave.open(io.BytesIO(payload),\'rb\') as source:\n        return source.getparams(),source.readframes(source.getnframes())\n\ndef _wav_window(params,frames,offset_seconds,seconds=.5):\n    frame_size=params.nchannels*params.sampwidth\n    start=round(offset_seconds*params.framerate)*frame_size\n    size=round(seconds*params.framerate)*frame_size\n    stream=io.BytesIO()\n    with wave.open(stream,\'wb\') as target:\n        target.setparams(params); target.writeframes(frames[start:start+size])\n    return stream.getvalue()\n\nclass ScorePlayer:\n    """Perform from a monotonic-clock bar position, skipping time lost to lag."""\n    def __init__(self,volume=.7,sound_module=None):\n        if sound_module is None:\n            try: import winsound as sound_module\n            except ImportError: sound_module=None\n        self.sound=sound_module; self.volume=max(0.,min(1.,volume)); self.enabled=True; self.playing=False; self.current_position=ScorePosition(0,0.,0.); self._buffer=None; self._suite_cache=None; self._thread=None; self._process=None; self._stop_event=threading.Event()\n    @property\n    def available(self): return self.sound is not None\n    @staticmethod\n    def _set_output_volume(value):\n        """Apply live music gain without interrupting the contiguous PCM stream."""\n        if sys.platform != \'win32\':\n            return\n        level = max(0., min(1., float(value)))\n        packed = int(level * 0xffff) | (int(level * 0xffff) << 16)\n        try:\n            ctypes.windll.winmm.waveOutSetVolume(0, packed)\n        except (AttributeError, OSError):\n            pass\n    def _perform_suite(self):\n        try:\n            kind = \'wav\'\n            if BGM_MP3_BASE64:\n                payload = base64.b64decode(BGM_MP3_BASE64)\n                kind = \'mp3\'\n            else:\n                payload = self._suite_cache or self._load_payload()\n            self._suite_cache = payload\n            if kind == \'wav\':\n                params,frames=_wav_timeline(payload)\n                duration=len(frames)/(params.framerate*params.nchannels*params.sampwidth)\n            else:\n                duration=204.05\n            origin=time.monotonic()\n            if sys.platform == \'win32\' and self.sound is not False:\n                context = multiprocessing.get_context(\'spawn\')\n                self._process = context.Process(target=_audio_process_main, args=(payload, kind), daemon=True)\n                self._process.start()\n                while not self._stop_event.wait(.1):\n                    self.current_position=looped_score_position(time.monotonic()-origin,duration)\n                    if not self._process.is_alive(): break\n                if self._process.is_alive(): self._process.terminate()\n                self._process.join(timeout=1.)\n                self._process=None\n                return\n            # Feed the complete decoded PCM to the system in one call. Rebuilding\n            # 0.25 s WAV windows made Python the real-time producer and caused\n            # audible starvation under load. The audio device now owns timing.\n            while not self._stop_event.is_set():\n                elapsed=time.monotonic()-origin\n                self.current_position=looped_score_position(elapsed,duration)\n                timeline_seconds=self.current_position.seconds\n                self._buffer=payload\n                self.sound.PlaySound(payload,self.sound.SND_MEMORY)\n        except RuntimeError: pass\n        finally: self.playing=False\n    def start(self):\n        if not self.available or not self.enabled:return False\n        if self._thread and self._thread.is_alive():return True\n        self.playing=True; self._stop_event.clear(); self._thread=threading.Thread(target=self._perform_suite,name=\'canal-score-player\',daemon=True); self._thread.start(); return True\n    def stop(self):\n        self._stop_event.set(); self.playing=False\n        if self._process and self._process.is_alive():\n            self._process.terminate()\n            self._process.join(timeout=1.)\n            self._process=None\n        if self._thread and self._thread is not threading.current_thread(): self._thread.join(timeout=1.2)\n        self._thread=None\n    def set_volume(self,volume):\n        value=max(0.,min(1.,volume))\n        if value != self.volume:self._suite_cache=None\n        self.volume=value\n        if self.enabled:self._set_output_volume(value)\n    def _load_payload(self):\n        """Prefer the packaged composition; retain synthesis as dev fallback."""\n        if BGM_WAV_ZLIB_BASE64:\n            try:\n                return decode_wav(BGM_WAV_ZLIB_BASE64)\n            except ValueError:\n                pass\n        return render_canal_suite(volume=self.volume)\n    def prepare(self):\n        self._suite_cache = self._suite_cache or self._load_payload()\n    def set_enabled(self,enabled):\n        self.enabled=bool(enabled)\n        if not self.enabled:\n            self._set_output_volume(0.)\n            self.stop()\n        else:\n            self._set_output_volume(self.volume)\n            if not self.playing:self.start()\n', 'canal_delights.core.navigation': '"""One-dimensional boat physics projected onto the Grand Canal spline."""\n\nfrom dataclasses import dataclass\nimport math\nfrom typing import Optional\n\nfrom .geometry import cubic_bezier_point\n\n\nPoint = tuple[float, float]\n\n# The five city anchors are also the endpoints of four cubic spline spans.\nCITY_POINTS: tuple[Point, ...] = (\n    (.17, .78), (.30, .69), (.55, .43), (.80, .28), (.74, .14),\n)\n\nROUTE_SEGMENTS = (\n    (CITY_POINTS[0], (.1917, .7650), (.2367, .7483), CITY_POINTS[1]),\n    (CITY_POINTS[1], (.3633, .6317), (.4667, .4983), CITY_POINTS[2]),\n    (CITY_POINTS[2], (.6333, .3617), (.7683, .3283), CITY_POINTS[3]),\n    (CITY_POINTS[3], (.8317, .2317), (.7500, .1633), CITY_POINTS[4]),\n)\n\nCITY_STOPS = tuple(index / (len(CITY_POINTS) - 1) for index in range(len(CITY_POINTS)))\n\n\ndef route_point(progress: float) -> Point:\n    """Return a point on the route for normalized progress ``0..1``."""\n    progress = max(0.0, min(1.0, progress))\n    scaled = progress * len(ROUTE_SEGMENTS)\n    segment_index = min(len(ROUTE_SEGMENTS) - 1, int(scaled))\n    local_t = 1.0 if progress >= 1.0 else scaled - segment_index\n    return cubic_bezier_point(*ROUTE_SEGMENTS[segment_index], local_t)\n\n\ndef route_tangent(progress: float) -> Point:\n    """Numerically estimate a normalized tangent along the spline."""\n    epsilon = .001\n    before = route_point(max(0.0, progress - epsilon))\n    after = route_point(min(1.0, progress + epsilon))\n    dx, dy = after[0] - before[0], after[1] - before[1]\n    length = math.hypot(dx, dy) or 1.0\n    return dx / length, dy / length\n\n\ndef readable_boat_pose(tangent: Point, direction: float = 1.0,\n                       canvas_size: Point = (1200, 800)) -> tuple[float, bool]:\n    """Return an upright angle and whether the boat should be mirrored."""\n    width, height = canvas_size\n    sign = 1 if direction >= 0 else -1\n    angle = math.degrees(math.atan2(tangent[1] * sign * height,\n                                    tangent[0] * sign * width))\n    flipped = angle > 90 or angle < -90\n    if angle > 90:\n        angle -= 180\n    elif angle < -90:\n        angle += 180\n    return angle, flipped\n\n\n@dataclass\nclass BoatPhysics:\n    position: float = 0.0\n    velocity: float = 0.0\n    acceleration: float = 0.72\n    damping: float = 3.2\n    max_speed: float = 0.32\n    snap_strength: float = 2.4\n\n    def step(self, direction: float, delta_seconds: float) -> bool:\n        """Advance physics and return whether the boat visibly changed."""\n        dt = max(0.0, min(0.05, delta_seconds))\n        previous = self.position\n        self.velocity += max(-1.0, min(1.0, direction)) * self.acceleration * dt\n\n        if not direction:\n            nearest = min(CITY_STOPS, key=lambda stop: abs(stop - self.position))\n            if abs(nearest - self.position) < .055:\n                self.velocity += (nearest - self.position) * self.snap_strength * dt\n\n        self.velocity *= math.exp(-self.damping * dt)\n        self.velocity = max(-self.max_speed, min(self.max_speed, self.velocity))\n        self.position += self.velocity * dt\n\n        if self.position <= 0:\n            self.position, self.velocity = 0.0, max(0.0, self.velocity)\n        elif self.position >= 1:\n            self.position, self.velocity = 1.0, min(0.0, self.velocity)\n        if abs(self.velocity) < .0002:\n            self.velocity = 0.0\n        return abs(self.position - previous) > 1e-7\n\n    def nudge(self, direction: float):\n        self.velocity += max(-1.0, min(1.0, direction)) * .075\n        self.velocity = max(-self.max_speed, min(self.max_speed, self.velocity))\n\n    def nearby_city(self, radius: float = .037) -> Optional[int]:\n        index = min(range(len(CITY_STOPS)), key=lambda i: abs(CITY_STOPS[i] - self.position))\n        return index if abs(CITY_STOPS[index] - self.position) <= radius else None\n', 'canal_delights.core.renderer': '"""\n绘图数据解析器 - 将声明式 DSL 数据转换为实际绘制\n\n职责：\n- 校验 DSL schema\n- 转换坐标（归一化 → 绝对）\n- 应用 Transform\n- 解析 Style\n- 分发到 engine 绘制\n- 不负责业务状态\n"""\n\nfrom typing import List, Tuple, Optional, Any\n\nfrom .engine import DrawingEngine\nfrom .geometry import (\n    normalized_to_absolute,\n    normalized_size_to_absolute,\n    normalized_points_to_absolute,\n    apply_transform,\n    transform_points,\n    transform_scale,\n)\nfrom .styles import validate_rgb, parse_style, interpolate_gradient_stops\nfrom ..config import VALID_TYPE_CODES, CANVAS_BG\n\n\n# 类型别名\nBounds = Tuple[float, float, float, float]  # (left, bottom, width, height)\nDrawingData = List[list]\n\n\nclass DSLValidationError(Exception):\n    """DSL 校验错误"""\n    def __init__(self, index: int, type_code: str, message: str):\n        self.index = index\n        self.type_code = type_code\n        self.message = message\n        super().__init__(f"Item {index} ({type_code}): {message}")\n\n\nclass DrawingDataParser:\n    """\n    绘图数据解析器\n\n    职责：\n    - 校验 DSL schema\n    - 坐标转换和变换\n    - 分发到 engine 绘制\n    """\n\n    def __init__(self, engine: DrawingEngine):\n        self.engine = engine\n        self.background = CANVAS_BG\n\n    def parse(\n        self,\n        data: DrawingData,\n        bounds: Bounds,\n        parent_transform: Optional[dict] = None,\n    ):\n        """\n        解析并渲染绘图数据\n\n        参数:\n            data: 绘图数据列表\n            bounds: 绘制区域 (left, bottom, width, height)\n            parent_transform: 父级变换（用于 Group 嵌套）\n        """\n        if not data:\n            return\n\n        # 校验并收集所有项\n        items = []\n        for i, unit in enumerate(data):\n            try:\n                parsed = self._validate_and_parse(unit, i)\n                items.append(parsed)\n            except DSLValidationError as e:\n                # 记录错误但继续处理其他项\n                print(f"DSL 校验警告: {e}")\n                continue\n\n        # 按 z-order 排序（稳定排序）\n        items.sort(key=lambda x: x.get(\'style\', {}).get(\'z\', 0))\n\n        # 渲染\n        for item in items:\n            self._render_item(item, bounds, parent_transform)\n\n    def _validate_and_parse(self, unit: Any, index: int) -> dict:\n        """校验并解析单个单元"""\n        if not isinstance(unit, (list, tuple)) or len(unit) < 2:\n            raise DSLValidationError(index, \'?\', f"无效格式，需要 [type, geometry, ...]")\n\n        type_code = unit[0]\n\n        if type_code not in VALID_TYPE_CODES:\n            raise DSLValidationError(index, type_code, f"未知类型码: {type_code}")\n\n        geometry = unit[1]\n        style = unit[2] if len(unit) > 2 else {}\n\n        # 校验 geometry\n        self._validate_geometry(type_code, geometry, index)\n\n        return {\n            \'type\': type_code,\n            \'geometry\': geometry,\n            \'style\': style if isinstance(style, dict) else {},\n            \'index\': index,\n        }\n\n    def _validate_geometry(self, type_code: str, geometry: Any, index: int):\n        """校验 geometry 格式"""\n        validators = {\n            \'P\': self._validate_point,\n            \'L\': self._validate_line,\n            \'R\': self._validate_rect,\n            \'RR\': self._validate_rounded_rect,\n            \'C\': self._validate_circle,\n            \'E\': self._validate_ellipse,\n            \'G\': self._validate_polygon,\n            \'A\': self._validate_arc,\n            \'Q\': self._validate_quadratic,\n            \'B\': self._validate_bezier,\n            \'PATH\': self._validate_path,\n            \'RG\': self._validate_ring,\n            \'T\': self._validate_text,\n            \'GR\': self._validate_group,\n        }\n\n        validator = validators.get(type_code)\n        if validator:\n            validator(geometry, index)\n\n    def _validate_point(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 3:\n            raise DSLValidationError(idx, \'P\', "需要 [x, y, size]")\n\n    def _validate_line(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 2:\n            raise DSLValidationError(idx, \'L\', "需要点列表 [[x,y], ...]")\n\n    def _validate_rect(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 4:\n            raise DSLValidationError(idx, \'R\', "需要 [x, y, w, h]")\n\n    def _validate_rounded_rect(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 5:\n            raise DSLValidationError(idx, \'RR\', "需要 [x, y, w, h, radius]")\n\n    def _validate_circle(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 3:\n            raise DSLValidationError(idx, \'C\', "需要 [cx, cy, r]")\n\n    def _validate_ellipse(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 4:\n            raise DSLValidationError(idx, \'E\', "需要 [cx, cy, rx, ry]")\n\n    def _validate_polygon(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 3:\n            raise DSLValidationError(idx, \'G\', "需要至少 3 个点")\n\n    def _validate_arc(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 5:\n            raise DSLValidationError(idx, \'A\', "需要 [cx, cy, r, start, end]")\n\n    def _validate_quadratic(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 3:\n            raise DSLValidationError(idx, \'Q\', "需要 3 个控制点")\n\n    def _validate_bezier(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 4:\n            raise DSLValidationError(idx, \'B\', "需要 4 个控制点")\n\n    def _validate_path(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)):\n            raise DSLValidationError(idx, \'PATH\', "需要命令列表")\n\n    def _validate_ring(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 4:\n            raise DSLValidationError(idx, \'RG\', "需要 [cx, cy, r_inner, r_outer]")\n\n    def _validate_text(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)) or len(geo) < 3:\n            raise DSLValidationError(idx, \'T\', "需要 [x, y, text]")\n\n    def _validate_group(self, geo: Any, idx: int):\n        if not isinstance(geo, (list, tuple)):\n            raise DSLValidationError(idx, \'GR\', "需要子元素列表")\n\n    # ============================================\n    # 渲染方法\n    # ============================================\n\n    def _render_item(self, item: dict, bounds: Bounds, parent_transform: Optional[dict]):\n        """渲染单个项"""\n        type_code = item[\'type\']\n        geometry = item[\'geometry\']\n        style = item[\'style\']\n\n        # Compose a local transform with its inherited parent exactly once.\n        # Groups used to pass their own transform as both parent and child,\n        # doubling scale/translation and sending nested artwork off-canvas.\n        local_transform = style.get(\'transform\')\n        if parent_transform and local_transform:\n            from .geometry import compose_transforms\n            transform = compose_transforms(parent_transform, local_transform)\n        else:\n            transform = local_transform or parent_transform\n\n        # 分发到具体渲染方法\n        renderers = {\n            \'P\': self._render_point,\n            \'L\': self._render_line,\n            \'R\': self._render_rect,\n            \'RR\': self._render_rounded_rect,\n            \'C\': self._render_circle,\n            \'E\': self._render_ellipse,\n            \'G\': self._render_polygon,\n            \'A\': self._render_arc,\n            \'Q\': self._render_quadratic,\n            \'B\': self._render_bezier,\n            \'PATH\': self._render_path,\n            \'RG\': self._render_ring,\n            \'T\': self._render_text,\n            \'GR\': self._render_group,\n        }\n\n        renderer = renderers.get(type_code)\n        if renderer:\n            renderer(geometry, style, bounds, transform)\n\n    def _resolve_style(self, style: dict) -> dict:\n        """解析样式，处理预混色"""\n        return parse_style(style, self.background)\n\n    def _get_fill_and_stroke(self, style: dict):\n        """获取填充和描边颜色"""\n        resolved = self._resolve_style(style)\n\n        fill = resolved.get(\'fill\')\n        stroke = resolved.get(\'stroke\')\n        stroke_width = resolved.get(\'stroke_width\', 1.0)\n        gradient = resolved.get(\'gradient\')\n\n        # 如果有渐变，填充为 None（由渐变处理）\n        if gradient:\n            fill = None\n\n        return fill, stroke, stroke_width, gradient\n\n    def _transform_point(self, point: tuple, bounds: Bounds, transform: Optional[dict]) -> tuple:\n        """转换单个点"""\n        if transform:\n            point = apply_transform(point, transform, bounds)\n        return normalized_to_absolute(point[0], point[1], bounds)\n\n    def _transform_points(self, points: list, bounds: Bounds, transform: Optional[dict]) -> list:\n        """转换点列表"""\n        if transform:\n            points = transform_points(points, transform, bounds)\n        return normalized_points_to_absolute(points, bounds)\n\n    def _transform_size(self, size: float, bounds: Bounds) -> float:\n        """转换尺寸"""\n        return normalized_size_to_absolute(size, bounds)\n\n    def _scaled_size(self, size: float, bounds: Bounds, transform: Optional[dict], axis=None) -> float:\n        sx, sy = transform_scale(transform)\n        factor = abs(sx) if axis == \'x\' else abs(sy) if axis == \'y\' else min(abs(sx), abs(sy))\n        return self._transform_size(size, bounds) * factor\n\n    # ============================================\n    # 各类型渲染\n    # ============================================\n\n    def _render_point(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染点: [x, y, size]"""\n        x, y = self._transform_point((geo[0], geo[1]), bounds, transform)\n        # ``P`` is a texture dot and its size is specified in pixels.  Treating\n        # values such as 2 or 3 as normalized units created canvas-sized blobs.\n        sx, sy = transform_scale(transform)\n        size = float(geo[2]) * min(abs(sx), abs(sy))\n\n        fill, stroke, _, _ = self._get_fill_and_stroke(style)\n        color = fill or stroke or (0, 0, 0)\n\n        self.engine.draw_point(x, y, max(1, size), color)\n\n    def _render_line(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染线: [[x,y], ...]"""\n        points = self._transform_points(geo, bounds, transform)\n\n        _, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        color = stroke or (0, 0, 0)\n\n        self.engine.draw_polyline(points, color, max(1, stroke_width), close=False)\n\n    def _render_rect(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染矩形: [x, y, w, h]"""\n        # A transformed rectangle is no longer necessarily axis-aligned.\n        # Convert the original normalized corners once; the old implementation\n        # applied the transform to the origin and then to its corners again.\n        if transform:\n            points = self._transform_points([\n                (geo[0], geo[1]), (geo[0] + geo[2], geo[1]),\n                (geo[0] + geo[2], geo[1] + geo[3]), (geo[0], geo[1] + geo[3]),\n            ], bounds, transform)\n            self._render_polygon_with_style(points, style, bounds, None)\n            return\n\n        abs_x, abs_y = self._transform_point((geo[0], geo[1]), bounds, None)\n        # Width and height are axis-specific.  Using the short edge for both\n        # made every rectangle (including the scroll frame) too narrow on the\n        # 1200 × 800 canvas.\n        w = geo[2] * bounds[2]\n        h = geo[3] * bounds[3]\n\n        fill, stroke, stroke_width, gradient = self._get_fill_and_stroke(style)\n\n        if gradient:\n            points = [(abs_x, abs_y), (abs_x + w, abs_y),\n                      (abs_x + w, abs_y + h), (abs_x, abs_y + h)]\n            self.engine.draw_gradient_fill(points, gradient, bounds)\n            if stroke:\n                self.engine.draw_polyline(points, stroke, stroke_width, close=True)\n        else:\n            self.engine.draw_rect(abs_x, abs_y, w, h, fill, stroke, stroke_width)\n\n    def _render_rounded_rect(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染圆角矩形: [x, y, w, h, radius]"""\n        # x, y 是位置，需要用 normalized_to_absolute\n        x, y = self._transform_point((geo[0], geo[1]), bounds, transform)\n        # Rectangular dimensions follow their respective canvas axes; only the\n        # corner radius remains based on the short edge.\n        w = geo[2] * bounds[2]\n        h = geo[3] * bounds[3]\n        r = self._scaled_size(geo[4], bounds, transform)\n\n        abs_x = bounds[0] + x\n        abs_y = bounds[1] + y\n        abs_r = r\n\n        fill, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        self.engine.draw_rounded_rect(abs_x, abs_y, w, h, abs_r, fill, stroke, stroke_width)\n\n    def _render_circle(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染圆形: [cx, cy, r]"""\n        cx, cy = self._transform_point((geo[0], geo[1]), bounds, transform)\n        r = self._scaled_size(geo[2], bounds, transform)\n\n        fill, stroke, stroke_width, gradient = self._get_fill_and_stroke(style)\n\n        if gradient:\n            # 用多边形近似圆形来做渐变\n            from .geometry import sample_ellipse\n            points = sample_ellipse(cx, cy, r, r)\n            self.engine.draw_gradient_fill(points, gradient, bounds)\n            if stroke:\n                self.engine.draw_polyline(points, stroke, stroke_width, close=True)\n        else:\n            self.engine.draw_circle(cx, cy, r, fill, stroke, stroke_width)\n\n    def _render_ellipse(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染椭圆: [cx, cy, rx, ry]"""\n        cx, cy = self._transform_point((geo[0], geo[1]), bounds, transform)\n        rx = self._scaled_size(geo[2], bounds, transform, \'x\')\n        ry = self._scaled_size(geo[3], bounds, transform, \'y\')\n\n        fill, stroke, stroke_width, gradient = self._get_fill_and_stroke(style)\n\n        if gradient:\n            from .geometry import sample_ellipse\n            points = sample_ellipse(cx, cy, rx, ry)\n            self.engine.draw_gradient_fill(points, gradient, bounds)\n            if stroke:\n                self.engine.draw_polyline(points, stroke, stroke_width, close=True)\n        else:\n            self.engine.draw_ellipse(cx, cy, rx, ry, fill, stroke, stroke_width)\n\n    def _render_polygon(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染多边形: [[x,y], ...]"""\n        points = self._transform_points(geo, bounds, transform)\n        self._render_polygon_with_style(points, style, bounds, transform)\n\n    def _render_polygon_with_style(self, points: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """用样式渲染多边形"""\n        fill, stroke, stroke_width, gradient = self._get_fill_and_stroke(style)\n\n        if gradient:\n            self.engine.draw_gradient_fill(points, gradient, bounds)\n            if stroke:\n                self.engine.draw_polyline(points, stroke, stroke_width, close=True)\n        else:\n            self.engine.draw_polygon(points, fill, stroke, stroke_width)\n\n    def _render_arc(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染弧形: [cx, cy, r, start, end]"""\n        cx, cy = self._transform_point((geo[0], geo[1]), bounds, transform)\n        r = self._scaled_size(geo[2], bounds, transform)\n        start = geo[3]\n        end = geo[4]\n\n        _, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        color = stroke or (0, 0, 0)\n\n        self.engine.draw_arc(cx, cy, r, start, end, color, max(1, stroke_width))\n\n    def _render_quadratic(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染二次贝塞尔: [[p0], [p1], [p2]]"""\n        p0 = self._transform_point(tuple(geo[0]), bounds, transform)\n        p1 = self._transform_point(tuple(geo[1]), bounds, transform)\n        p2 = self._transform_point(tuple(geo[2]), bounds, transform)\n\n        _, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        color = stroke or (0, 0, 0)\n\n        self.engine.draw_quadratic(p0, p1, p2, color, max(1, stroke_width))\n\n    def _render_bezier(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染三次贝塞尔: [[p0], [p1], [p2], [p3]]"""\n        points = self._transform_points(geo, bounds, transform)\n\n        _, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        color = stroke or (0, 0, 0)\n\n        self.engine.draw_bezier(points, color, max(1, stroke_width))\n\n    def _render_path(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染复合路径: [[\'M\', x, y], [\'L\', x, y], ...]"""\n        # 转换路径命令中的坐标\n        commands = []\n        for cmd in geo:\n            if not cmd:\n                continue\n\n            op = cmd[0]\n\n            if op == \'M\' and len(cmd) >= 3:\n                pt = self._transform_point((cmd[1], cmd[2]), bounds, transform)\n                commands.append([\'M\', pt[0], pt[1]])\n\n            elif op == \'L\' and len(cmd) >= 3:\n                pt = self._transform_point((cmd[1], cmd[2]), bounds, transform)\n                commands.append([\'L\', pt[0], pt[1]])\n\n            elif op == \'Q\' and len(cmd) >= 5:\n                p1 = self._transform_point((cmd[1], cmd[2]), bounds, transform)\n                p2 = self._transform_point((cmd[3], cmd[4]), bounds, transform)\n                commands.append([\'Q\', p1[0], p1[1], p2[0], p2[1]])\n\n            elif op == \'C\' and len(cmd) >= 7:\n                p1 = self._transform_point((cmd[1], cmd[2]), bounds, transform)\n                p2 = self._transform_point((cmd[3], cmd[4]), bounds, transform)\n                p3 = self._transform_point((cmd[5], cmd[6]), bounds, transform)\n                commands.append([\'C\', p1[0], p1[1], p2[0], p2[1], p3[0], p3[1]])\n\n            elif op == \'Z\':\n                commands.append([\'Z\'])\n\n        fill, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        self.engine.draw_path(commands, fill, stroke, max(1, stroke_width))\n\n    def _render_ring(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染圆环: [cx, cy, r_inner, r_outer]"""\n        cx, cy = self._transform_point((geo[0], geo[1]), bounds, transform)\n        r_inner = self._scaled_size(geo[2], bounds, transform)\n        r_outer = self._scaled_size(geo[3], bounds, transform)\n\n        fill, stroke, stroke_width, _ = self._get_fill_and_stroke(style)\n        self.engine.draw_ring(cx, cy, r_inner, r_outer, fill, stroke, stroke_width)\n\n    def _render_text(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染文字: [x, y, text]"""\n        x, y = self._transform_point((geo[0], geo[1]), bounds, transform)\n        text = geo[2]\n\n        # 文字样式\n        font_family = style.get(\'font_family\', \'Microsoft YaHei\')\n        font_size = style.get(\'font_size\', 16)\n        font_weight = style.get(\'font_weight\', \'normal\')\n        align = style.get(\'align\', \'center\')\n        color = style.get(\'color\', (0, 0, 0))\n\n        # 字号直接使用，不做转换\n        abs_size = max(8, font_size)\n\n        self.engine.draw_text(text, x, y, abs_size, color, font_family, align, font_weight)\n\n    def _render_group(self, geo: list, style: dict, bounds: Bounds, transform: Optional[dict]):\n        """渲染组: [children]"""\n        self.parse(geo, bounds, transform)\n', 'canal_delights.core.sound_effects': '"""Layered, code-synthesized stereo interaction sounds; no audio assets."""\nfrom array import array\nimport io\nimport math\nimport threading\nimport wave\n\nSAMPLE_RATE = 22050\nEFFECT_DURATIONS = {\n    \'key\': .28, \'scroll\': 1.0, \'page\': .6,\n    \'water\': .8, \'stamp\': .4, \'fresh\': .6,\n}\nSYNTHESIS_METHODS = (\'karplus-strong\', \'filtered-noise\', \'cyclic-texture\')\n\n\ndef _noise(count, seed):\n    """Deterministic white noise, allowing identical builds and tests."""\n    values = [0.] * count\n    state = seed\n    for index in range(count):\n        state = (1664525 * state + 1013904223) & 0xffffffff\n        values[index] = state / 2147483648. - 1.\n    return values\n\n\ndef _filtered_noise(count, sample_rate, seed, fast_hz, slow_hz=0):\n    raw = _noise(count, seed)\n    fast = slow = 0.\n    fast_a = min(1., math.tau * fast_hz / sample_rate)\n    slow_a = min(1., math.tau * slow_hz / sample_rate) if slow_hz else 0.\n    result = [0.] * count\n    for index, value in enumerate(raw):\n        fast += fast_a * (value - fast)\n        if slow_hz:\n            slow += slow_a * (value - slow)\n            result[index] = fast - slow\n        else:\n            result[index] = fast\n    return result\n\n\ndef _add_karplus(left, right, sample_rate, onset, duration, frequency, amplitude,\n                 pan=.5, damping=.992, seed=0xA11CE):\n    """Noise-excited Karplus–Strong body: a struck object, not a sine tone."""\n    start, count = round(onset * sample_rate), round(duration * sample_rate)\n    lg, rg = math.sqrt(1-pan), math.sqrt(pan)\n    delay = max(2, round(sample_rate / frequency))\n    ring = _noise(delay, seed)\n    position = 0\n    for index in range(min(count, len(left)-start)):\n        t = index / sample_rate\n        value = ring[position]\n        following = ring[(position+1) % delay]\n        ring[position] = (value+following)*.5*damping\n        position = (position+1) % delay\n        env = min(1.,t/.004)*min(1.,(duration-t)/.025)\n        value *= env*amplitude\n        left[start+index] += value*lg; right[start+index] += value*rg\n\n\ndef _cyclic_texture(size, seed):\n    """A seamless random control ring used for non-oscillator water texture."""\n    return _noise(size, seed)\n\n\ndef _paper_layer(left, right, sample_rate, seed, start, duration, amplitude, direction=1):\n    count = round(duration * sample_rate)\n    texture = _filtered_noise(count, sample_rate, seed, 2600, 260)\n    onset = round(start * sample_rate)\n    for index in range(min(count, len(left)-onset)):\n        progress = index / max(1, count-1)\n        # Two irregular cloth/paper swells avoid a generic white-noise "whoosh".\n        arch = 4*progress*(1-progress)\n        flutter = (progress*3.1) % 1\n        flutter = 4*flutter*(1-flutter)\n        shape = arch**1.5 * (.72 + .28*flutter*flutter)\n        pan = .18+.64*progress if direction > 0 else .82-.64*progress\n        value = texture[index] * shape * amplitude\n        left[onset+index] += value*math.sqrt(1-pan)\n        right[onset+index] += value*math.sqrt(pan)\n\n\ndef _design_effect(kind, left, right, sample_rate, strength):\n    duration = EFFECT_DURATIONS[kind]\n    if kind == \'key\':\n        # Two noise-excited wooden bodies create an unmistakable percussion hit.\n        _add_karplus(left,right,sample_rate,0,.24,310,.27*strength,.45,.985,0xB4A0)\n        _add_karplus(left,right,sample_rate,.012,.16,520,.085*strength,.56,.978,0xB4A1)\n    elif kind == \'scroll\':\n        _paper_layer(left,right,sample_rate,0x5107,0,duration,.34*strength,1)\n        _paper_layer(left,right,sample_rate,0x8A31,.13,.70,.15*strength,-1)\n        _add_karplus(left,right,sample_rate,.04,.35,185,.075*strength,.38,.994,0x5108)\n    elif kind == \'page\':\n        _paper_layer(left,right,sample_rate,0xFACE,0,.52,.38*strength,1)\n        _paper_layer(left,right,sample_rate,0xB00C,.20,.34,.16*strength,-1)\n        _add_karplus(left,right,sample_rate,.38,.18,410,.055*strength,.72,.982,0xFACF)\n    elif kind == \'water\':\n        # Seamless interpolated random rings: flowing texture without oscillators.\n        broad, detail = _cyclic_texture(37,0xA0A0), _cyclic_texture(83,0xA0A1)\n        def sample_ring(ring, progress):\n            position=progress*len(ring); base=int(position)%len(ring); mix=position-int(position)\n            mix=mix*mix*(3-2*mix)\n            return ring[base]*(1-mix)+ring[(base+1)%len(ring)]*mix\n        for index in range(len(left)):\n            p = index / len(left)\n            ripple=.72*sample_ring(broad,p)+.28*sample_ring(detail,p)\n            breathe=.84+.16*(1-abs(2*((p*2)%1)-1))\n            # Water is an ambience bed: audible at crawl speed, but still\n            # multiplied by the boat-speed ratio before final output gain.\n            left[index] += ripple*breathe*.24*strength\n            right[index] += (ripple*.84+sample_ring(detail,p)*.16)*breathe*.24*strength\n        for onset, pan in ((.17,.24),(.49,.72)):\n            _add_karplus(left,right,sample_rate,onset,.18,260,.035*strength,pan,.987,0xA0B0+int(onset*100))\n    elif kind == \'stamp\':\n        # Felted impact + wooden body + brief paper contact.\n        _add_karplus(left,right,sample_rate,0,.32,96,.30*strength,.5,.996,0x57A0)\n        _add_karplus(left,right,sample_rate,.008,.18,286,.13*strength,.47,.986,0x57A1)\n        _paper_layer(left,right,sample_rate,0x57A9,0,.12,.10*strength,-1)\n    else:  # fresh: airy D-major pentatonic chime, not a digital three-beep scale.\n        for onset, frequency, pan in ((0,587.33,.30),(.12,739.99,.50),(.25,880.,.70)):\n            _add_karplus(left,right,sample_rate,onset,.34,frequency,.13*strength,pan,.994,0xC100+int(onset*100))\n        air = _filtered_noise(len(left), sample_rate, 0xC1EA, 900, 120)\n        for index, value in enumerate(air):\n            progress = index/len(left)\n            env = (4*progress*(1-progress))**2\n            left[index] += value*env*.018*strength; right[index] += value*env*.021*strength\n\n\ndef synthesize_effect(kind, volume=.8, sample_rate=SAMPLE_RATE, water_level=1.0):\n    """Create a polished named effect as safe, click-free stereo PCM."""\n    if kind not in EFFECT_DURATIONS: raise ValueError(f\'unknown effect: {kind}\')\n    count = round(EFFECT_DURATIONS[kind]*sample_rate)\n    left, right = [0.]*count, [0.]*count\n    strength = max(0.,min(1.,volume)) * (max(0.,min(1.,water_level)) if kind==\'water\' else 1.)\n    _design_effect(kind,left,right,sample_rate,strength)\n    # Non-looping sounds end exactly at silence; water is periodic by construction.\n    if kind != \'water\':\n        fade = max(1, round(.018*sample_rate))\n        for index in range(fade):\n            gain = index/fade; left[index]*=gain; right[index]*=gain\n            gain = (fade-index-1)/fade; left[-index-1]*=gain; right[-index-1]*=gain\n    peak=max(max(map(abs,left)),max(map(abs,right)),1e-9); gain=min(1.,.72/peak)\n    frames=array(\'h\')\n    for l,r in zip(left,right): frames.extend((round(l*gain*32767),round(r*gain*32767)))\n    stream=io.BytesIO()\n    with wave.open(stream,\'wb\') as wav:\n        wav.setnchannels(2); wav.setsampwidth(2); wav.setframerate(sample_rate); wav.writeframes(frames.tobytes())\n    return stream.getvalue()\n\n\nclass EffectPlayer:\n    """Non-blocking effect performer; water follows normalized boat speed."""\n    def __init__(self,volume=.8,sound_module=None):\n        if sound_module is None:\n            try: import winsound as sound_module\n            except ImportError: sound_module=None\n        self.sound,self.volume=sound_module,volume; self.enabled=True; self.water_level=0.; self._cache={}; self._stopped=threading.Event(); self._water_thread=None\n    def set_volume(self,volume):\n        value=max(0.,min(1.,volume))\n        if value != self.volume:self._cache.clear()\n        self.volume=value\n    def _perform(self,payload):\n        try: self.sound.PlaySound(payload,self.sound.SND_MEMORY)\n        except RuntimeError: pass\n    def play(self,kind):\n        if not self.sound or not self.enabled or self.volume<=0:return\n        payload=self._cache.get(kind) or synthesize_effect(kind,self.volume)\n        threading.Thread(target=self._perform,args=(payload,),daemon=True).start()\n    def set_water_level(self,level):\n        self.water_level=max(0.,min(1.,level))\n        if self.water_level>.02 and (not self._water_thread or not self._water_thread.is_alive()):\n            self._stopped.clear(); self._water_thread=threading.Thread(target=self._water_loop,daemon=True); self._water_thread.start()\n    def _water_loop(self):\n        while not self._stopped.is_set() and self.water_level>.02:\n            if self.sound and self.enabled and self.volume>0:self._perform(synthesize_effect(\'water\',self.volume,water_level=self.water_level))\n    def stop(self): self._stopped.set(); self.water_level=0.\n    def prepare(self):\n        for kind in EFFECT_DURATIONS:\n            if kind != \'water\':self._cache[kind]=synthesize_effect(kind,self.volume)\n    def set_enabled(self,enabled):\n        self.enabled=bool(enabled)\n        if not self.enabled:self.stop()\n', 'canal_delights.core.splash': '"""Boat-wake droplets only; deliberately not a general ambient particle system."""\n\nfrom dataclasses import dataclass\nimport random\n\n\n@dataclass\nclass SplashDrop:\n    x: float\n    y: float\n    vx: float\n    vy: float\n    life: float\n    max_life: float\n    size: float\n\n\nclass SplashSystem:\n    def __init__(self, seed: int = 2026, limit: int = 36):\n        self.random = random.Random(seed)\n        self.limit = limit\n        self.drops: list[SplashDrop] = []\n\n    def emit(self, x: float, y: float, direction: float, count: int = 2):\n        available = max(0, self.limit - len(self.drops))\n        for _ in range(min(count, available)):\n            lifetime = self.random.uniform(.26, .48)\n            self.drops.append(SplashDrop(\n                x=x + self.random.uniform(-.010, .010),\n                y=y + self.random.uniform(-.006, .004),\n                vx=-direction * self.random.uniform(.020, .048) + self.random.uniform(-.006, .006),\n                vy=self.random.uniform(.035, .075),\n                life=lifetime,\n                max_life=lifetime,\n                size=self.random.uniform(.003, .007),\n            ))\n\n    def step(self, delta_seconds: float):\n        dt = max(0.0, min(.1, delta_seconds))\n        alive = []\n        for drop in self.drops:\n            drop.life -= dt\n            if drop.life <= 0:\n                continue\n            drop.x += drop.vx * dt\n            drop.y += drop.vy * dt\n            drop.vy -= .14 * dt\n            alive.append(drop)\n        self.drops = alive\n\n    def drawing_data(self) -> list:\n        data = []\n        for drop in self.drops:\n            fade = drop.life / drop.max_life\n            color = (\n                int(222 + 25 * fade),\n                int(235 + 17 * fade),\n                int(231 + 21 * fade),\n            )\n            data.append([\'E\', [drop.x, drop.y, drop.size, drop.size * .55], {\n                \'fill\': color, \'z\': 75,\n            }])\n        return data\n', 'canal_delights.core.styles': '"""\n样式模块 - 颜色处理、渐变插值、RGBA预混色\n"""\n\nfrom typing import Tuple, Optional, Union, List\n\n\n# ============================================\n# 类型定义\n# ============================================\n\nRGB = Tuple[int, int, int]\nRGBA = Tuple[int, int, int, int]\nColor = Union[RGB, RGBA]\n\n\n# ============================================\n# 颜色校验\n# ============================================\n\ndef validate_rgb(color: tuple) -> RGB:\n    """\n    校验 RGB 颜色\n\n    参数:\n        color: (r, g, b) 元组，每通道 0-255 整数\n\n    返回:\n        校验后的 RGB 元组\n\n    异常:\n        ValueError: 颜色格式无效\n    """\n    if not isinstance(color, (tuple, list)):\n        raise ValueError(f"颜色必须是元组或列表，得到: {type(color)}")\n\n    if len(color) not in (3, 4):\n        raise ValueError(f"RGB 颜色必须有 3 或 4 个通道，得到: {len(color)}")\n\n    for i, c in enumerate(color[:3]):\n        if not isinstance(c, int):\n            raise ValueError(f"颜色通道必须是整数，通道 {i} 得到: {type(c)}")\n        if c < 0 or c > 255:\n            raise ValueError(f"颜色通道必须在 0-255 范围内，通道 {i} 得到: {c}")\n\n    return (color[0], color[1], color[2])\n\n\ndef validate_rgba(color: tuple) -> RGBA:\n    """\n    校验 RGBA 颜色\n\n    参数:\n        color: (r, g, b, a) 元组\n\n    返回:\n        校验后的 RGBA 元组\n    """\n    rgb_part = validate_rgb(color)\n\n    if len(color) == 3:\n        return rgb_part + (255,)\n\n    a = color[3]\n    if not isinstance(a, (int, float)):\n        raise ValueError(f"Alpha 通道必须是数字，得到: {type(a)}")\n    if isinstance(a, float):\n        if a < 0.0 or a > 1.0:\n            raise ValueError(f"浮点 Alpha 必须在 0.0-1.0 范围内，得到: {a}")\n        a = int(a * 255)\n    else:\n        if a < 0 or a > 255:\n            raise ValueError(f"整数 Alpha 必须在 0-255 范围内，得到: {a}")\n\n    return rgb_part + (a,)\n\n\ndef is_valid_color(value) -> bool:\n    """检查值是否为有效颜色"""\n    try:\n        validate_rgb(value)\n        return True\n    except (ValueError, TypeError, IndexError):\n        return False\n\n\n# ============================================\n# 颜色转换\n# ============================================\n\ndef rgb_to_hex(color: RGB) -> str:\n    """RGB 转十六进制颜色字符串"""\n    r, g, b = validate_rgb(color)\n    return f"#{r:02x}{g:02x}{b:02x}"\n\n\ndef rgb_to_turtle(color: RGB) -> Tuple[float, float, float]:\n    """RGB 转 Turtle 格式 (0.0-1.0)"""\n    r, g, b = validate_rgb(color)\n    return (r / 255.0, g / 255.0, b / 255.0)\n\n\n# ============================================\n# RGBA 预混色\n# ============================================\n\ndef premultiply_alpha(\n    foreground: Color,\n    background: RGB,\n) -> RGB:\n    """\n    RGBA 预混色\n\n    公式: out = alpha * foreground + (1 - alpha) * background\n\n    参数:\n        foreground: 前景色 RGB 或 RGBA\n        background: 背景色 RGB\n\n    返回:\n        混色后的 RGB\n    """\n    if len(foreground) == 3:\n        return validate_rgb(foreground)\n\n    r_fg, g_fg, b_fg, a = validate_rgba(foreground)\n    r_bg, g_bg, b_bg = validate_rgb(background)\n\n    alpha = a / 255.0\n\n    r_out = int(alpha * r_fg + (1 - alpha) * r_bg)\n    g_out = int(alpha * g_fg + (1 - alpha) * g_bg)\n    b_out = int(alpha * b_fg + (1 - alpha) * b_bg)\n\n    # 限制范围\n    r_out = max(0, min(255, r_out))\n    g_out = max(0, min(255, g_out))\n    b_out = max(0, min(255, b_out))\n\n    return (r_out, g_out, b_out)\n\n\ndef apply_opacity(\n    color: Color,\n    opacity: float,\n    background: Optional[RGB] = None,\n) -> RGB:\n    """\n    应用不透明度\n\n    参数:\n        color: 颜色\n        opacity: 不透明度 0.0-1.0\n        background: 背景色（opacity < 1 时必须提供）\n\n    返回:\n        混色后的 RGB\n    """\n    if opacity >= 1.0:\n        if len(color) == 4:\n            return (color[0], color[1], color[2])\n        return validate_rgb(color)\n\n    if background is None:\n        # 无背景时，丢弃 alpha\n        if len(color) == 4:\n            return (color[0], color[1], color[2])\n        return validate_rgb(color)\n\n    # 合并 opacity 和 alpha\n    if len(color) == 4:\n        r, g, b, a = validate_rgba(color)\n        effective_alpha = (a / 255.0) * opacity\n        fg_with_opacity = (r, g, b, int(effective_alpha * 255))\n    else:\n        r, g, b = validate_rgb(color)\n        fg_with_opacity = (r, g, b, int(opacity * 255))\n\n    return premultiply_alpha(fg_with_opacity, background)\n\n\n# ============================================\n# 颜色插值\n# ============================================\n\ndef lerp_color(color1: RGB, color2: RGB, t: float) -> RGB:\n    """\n    颜色线性插值\n\n    参数:\n        color1: 起始颜色\n        color2: 结束颜色\n        t: 插值因子 0.0-1.0\n\n    返回:\n        插值后的 RGB\n    """\n    r1, g1, b1 = validate_rgb(color1)\n    r2, g2, b2 = validate_rgb(color2)\n\n    t = max(0.0, min(1.0, t))\n\n    r = int(r1 + (r2 - r1) * t)\n    g = int(g1 + (g2 - g1) * t)\n    b = int(b1 + (b2 - b1) * t)\n\n    return (r, g, b)\n\n\ndef interpolate_gradient_stops(\n    stops: List[tuple],\n    t: float,\n) -> RGB:\n    """\n    在渐变色标间插值\n\n    参数:\n        stops: 色标列表 [[color, position], ...]\n               position: 0.0-1.0\n        t: 插值位置 0.0-1.0\n\n    返回:\n        插值后的 RGB\n    """\n    if not stops:\n        raise ValueError("色标列表不能为空")\n\n    if len(stops) == 1:\n        color = stops[0][0]\n        if len(color) == 4:\n            return (color[0], color[1], color[2])\n        return validate_rgb(color)\n\n    # 确保 t 在范围内\n    t = max(0.0, min(1.0, t))\n\n    # 找到 t 所在的区间\n    for i in range(len(stops) - 1):\n        color1, pos1 = stops[i]\n        color2, pos2 = stops[i + 1]\n\n        if pos1 <= t <= pos2:\n            # 在这个区间内插值\n            if pos2 == pos1:\n                local_t = 0.0\n            else:\n                local_t = (t - pos1) / (pos2 - pos1)\n\n            # 处理 RGBA\n            if len(color1) == 4:\n                color1 = (color1[0], color1[1], color1[2])\n            if len(color2) == 4:\n                color2 = (color2[0], color2[1], color2[2])\n\n            return lerp_color(color1, color2, local_t)\n\n    # 超出范围，返回最近的色标\n    if t < stops[0][1]:\n        color = stops[0][0]\n    else:\n        color = stops[-1][0]\n\n    if len(color) == 4:\n        return (color[0], color[1], color[2])\n    return validate_rgb(color)\n\n\n# ============================================\n# 样式解析\n# ============================================\n\ndef parse_style(style_data: dict, background: Optional[RGB] = None) -> dict:\n    """\n    解析样式，应用预混色\n\n    参数:\n        style_data: 样式字典\n        background: 背景色（用于预混色）\n\n    返回:\n        处理后的样式字典\n    """\n    result = style_data.copy()\n\n    # 处理填充色\n    fill = result.get(\'fill\')\n    opacity = result.get(\'opacity\', 1.0)\n    blend_with = result.get(\'blend_with\', background)\n\n    if fill is not None:\n        if opacity < 1.0 and blend_with is not None:\n            result[\'fill\'] = apply_opacity(fill, opacity, blend_with)\n        elif len(fill) == 4:\n            if blend_with:\n                result[\'fill\'] = premultiply_alpha(fill, blend_with)\n            else:\n                result[\'fill\'] = (fill[0], fill[1], fill[2])\n\n    # 处理描边色\n    stroke = result.get(\'stroke\')\n    if stroke is not None:\n        if opacity < 1.0 and blend_with is not None:\n            result[\'stroke\'] = apply_opacity(stroke, opacity, blend_with)\n        elif len(stroke) == 4:\n            if blend_with:\n                result[\'stroke\'] = premultiply_alpha(stroke, blend_with)\n            else:\n                result[\'stroke\'] = (stroke[0], stroke[1], stroke[2])\n\n    return result\n\n\n# ============================================\n# 字体回退\n# ============================================\n\ndef get_font_family(preferred: str, available: List[str]) -> str:\n    """\n    获取可用字体\n\n    参数:\n        preferred: 首选字体\n        available: 可用字体列表\n\n    返回:\n        可用的字体名称\n    """\n    if preferred in available:\n        return preferred\n\n    # 回退到系统默认\n    for fallback in [\'Microsoft YaHei\', \'PingFang SC\', \'sans-serif\']:\n        if fallback in available:\n            return fallback\n\n    return \'sans-serif\'\n', 'canal_delights.state': '"""\n状态机 - 管理应用状态和转换\n"""\n\nfrom enum import Enum, auto\nfrom dataclasses import dataclass, field\nfrom typing import Set\n\n\nclass Mode(Enum):\n    """应用模式"""\n    INTRO = auto()        # 开场卷轴\n    LOADING = auto()      # 首次音频与场景预热\n    MAP = auto()          # 运河地图\n    CITY = auto()         # 城市场景\n    FOOD_DETAIL = auto()  # 美食详情\n    ATLAS = auto()        # 美食图鉴\n    SETTINGS = auto()     # 设置\n    FINALE = auto()       # 终章长卷\n\n\n@dataclass\nclass AppState:\n    """应用状态"""\n    mode: Mode = Mode.INTRO\n    current_city: int = 0  # 0-4 对应五城\n    current_food: int = 0  # 0-3 对应每城四道美食\n    atlas_page: int = 0    # 0 为总览，1-5 为城市页\n    visited_cities: Set[int] = field(default_factory=set)\n    discovered_foods: Set[str] = field(default_factory=set)  # "city_food" 格式\n    stamped_cities: Set[int] = field(default_factory=set)\n    help_open: bool = False\n    completion_open: bool = False\n    transition_locked: bool = False\n\n    def can_go_back(self) -> bool:\n        """是否可以返回上一级"""\n        return self.mode in [Mode.MAP, Mode.CITY, Mode.FOOD_DETAIL, Mode.ATLAS, Mode.SETTINGS]\n\n    def is_all_stamped(self) -> bool:\n        """是否五城全部盖章"""\n        return len(self.stamped_cities) >= 5\n\n    def get_food_key(self) -> str:\n        """获取当前美食的唯一标识"""\n        return f"{self.current_city}_{self.current_food}"\n\n\nclass StateMachine:\n    """状态机 - 管理状态转换"""\n\n    def __init__(self, state: AppState, city_count: int = 5, food_count: int = 4):\n        self.state = state\n        self.city_count = city_count\n        self.food_count = food_count\n\n    def next_city(self):\n        """下一个城市"""\n        if self.state.mode == Mode.MAP and not self.state.transition_locked:\n            self.state.current_city = (self.state.current_city + 1) % self.city_count\n\n    def prev_city(self):\n        """上一个城市"""\n        if self.state.mode == Mode.MAP and not self.state.transition_locked:\n            self.state.current_city = (self.state.current_city - 1) % self.city_count\n\n    def enter_city(self):\n        """进入城市"""\n        if self.state.mode == Mode.MAP and not self.state.transition_locked:\n            self.state.mode = Mode.CITY\n            self.state.visited_cities.add(self.state.current_city)\n            self.state.current_food = 0\n\n    def next_food(self):\n        """下一道美食"""\n        if self.state.mode == Mode.CITY and not self.state.transition_locked:\n            self.state.current_food = (self.state.current_food + 1) % self.food_count\n\n    def prev_food(self):\n        """上一道美食"""\n        if self.state.mode == Mode.CITY and not self.state.transition_locked:\n            self.state.current_food = (self.state.current_food - 1) % self.food_count\n\n    def open_food(self):\n        """打开美食详情"""\n        if self.state.mode == Mode.CITY and not self.state.transition_locked:\n            self.state.mode = Mode.FOOD_DETAIL\n\n    def complete_tasting(self):\n        """完成品鉴"""\n        if self.state.mode == Mode.FOOD_DETAIL and not self.state.transition_locked:\n            food_key = self.state.get_food_key()\n            self.state.discovered_foods.add(food_key)\n\n            # 四道菜全部发现后，给城市盖章。\n            city = self.state.current_city\n            if all(f"{city}_{index}" in self.state.discovered_foods\n                   for index in range(self.food_count)):\n                self.state.stamped_cities.add(city)\n\n            self.state.mode = Mode.CITY\n\n    def back(self):\n        """返回上一级"""\n        if self.state.transition_locked:\n            return\n\n        if self.state.mode == Mode.FOOD_DETAIL:\n            self.state.mode = Mode.CITY\n        elif self.state.mode == Mode.CITY:\n            self.state.mode = Mode.MAP\n        elif self.state.mode == Mode.ATLAS:\n            self.state.mode = Mode.MAP\n        elif self.state.mode == Mode.SETTINGS:\n            self.state.mode = Mode.MAP\n        elif self.state.mode == Mode.MAP:\n            self.state.mode = Mode.INTRO\n\n    def open_atlas(self):\n        """从地图打开图鉴。"""\n        if self.state.mode == Mode.MAP and not self.state.transition_locked:\n            self.state.mode = Mode.ATLAS\n            self.state.atlas_page = 0\n\n    def turn_atlas(self, direction: int):\n        """翻动图鉴，页码限制在总览与五个城市页之间。"""\n        if self.state.mode == Mode.ATLAS and not self.state.transition_locked:\n            self.state.atlas_page = max(\n                0, min(self.city_count, self.state.atlas_page + direction),\n            )\n\n    def open_settings(self):\n        """从地图打开设置。"""\n        if self.state.mode == Mode.MAP and not self.state.transition_locked:\n            self.state.mode = Mode.SETTINGS\n\n    def start_journey(self):\n        """开始旅程"""\n        if self.state.mode == Mode.INTRO and not self.state.transition_locked:\n            self.state.mode = Mode.MAP\n\n    def start_loading(self):\n        if self.state.mode == Mode.INTRO and not self.state.transition_locked:\n            self.state.mode = Mode.LOADING\n\n    def finish_loading(self):\n        if self.state.mode == Mode.LOADING and not self.state.transition_locked:\n            self.state.mode = Mode.MAP\n\n    def go_to_finale(self):\n        """进入终章"""\n        if self.state.mode == Mode.MAP and self.state.is_all_stamped():\n            self.state.mode = Mode.FINALE\n\n    def return_from_finale(self):\n        """从终章返回"""\n        if self.state.mode == Mode.FINALE:\n            self.state.mode = Mode.MAP\n\n    def toggle_help(self):\n        """切换帮助"""\n        self.state.help_open = not self.state.help_open\n', 'canal_delights.views.__init__': '"""\n视图模块 - G2 阶段实现\n"""\n', 'canal_delights.views.base': '"""\n视图基础类\n"""\n\nfrom typing import List\nfrom ..core.engine import DrawingEngine\nfrom ..core.renderer import DrawingDataParser\nfrom ..config import rgb\n\n\nclass View:\n    """视图基类"""\n\n    def __init__(self, engine: DrawingEngine, parser: DrawingDataParser):\n        self.engine = engine\n        self.parser = parser\n        self.bounds = (0, 0, engine.width, engine.height)\n\n    def render(self, state):\n        """渲染视图 - 子类实现"""\n        raise NotImplementedError\n\n    def draw_text(self, x: float, y: float, text: str, size: int, color: tuple, align: str = \'center\'):\n        """辅助方法：绘制文字"""\n        return [\'T\', [x, y, text], {\'font_size\': size, \'color\': color, \'align\': align}]\n\n    def draw_rect(self, x: float, y: float, w: float, h: float, fill: tuple):\n        """辅助方法：绘制矩形"""\n        return [\'R\', [x, y, w, h], {\'fill\': fill}]\n\n    def draw_circle(self, x: float, y: float, r: float, fill: tuple):\n        """辅助方法：绘制圆形"""\n        return [\'C\', [x, y, r], {\'fill\': fill}]\n', 'canal_delights.core.embedded_mp3': 'BGM_MP3_BASE64 = __canal_audio_payload__\n'}


class _SourceLoader(importlib.abc.Loader):
    def create_module(self, spec):
        return None

    def exec_module(self, module):
        if module.__name__ == 'canal_delights.core.embedded_mp3':
            module.__dict__['__canal_audio_payload__'] = _AUDIO_MP3_BASE64
        exec(compile(_MODULE_SOURCES[module.__name__], module.__name__, 'exec'), module.__dict__)


class _SourceFinder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _MODULE_SOURCES:
            return None
        package = fullname + '.__init__' in _MODULE_SOURCES
        return importlib.util.spec_from_loader(fullname, _SourceLoader(), is_package=package)


sys.meta_path.insert(0, _SourceFinder())


def _run():
    from canal_delights.app import main
    main()


